function partnerPill(s){
  return s==='live'?pill('active','Live'):s==='onboarding'?pill('inprogress','Onboarding'):
         s==='review'?pill('pending','In review'):s==='suspended'?pill('down','Suspended'):pill('rejected');
}
function statusPill(s){
  const map={live:'active',active:'active',pending:'pending',draft:'draft',rejected:'rejected',suspended:'suspended',
    paid:'paid',approved:'approved',open:'open',resolved:'resolved',escalated:'breached',partner:'inprogress',
    cancelled:'inactive',paused:'suspended',onboarding:'inprogress',review:'pending'};
  const lbl={live:'Live',pending:'Pending review',partner:'With partner',escalated:'Escalated',paused:'Paused'};
  return pill(map[s]||'unavailable', lbl[s]);
}
function healthPill(h){
  return h==='healthy'?pill('active','Healthy'):h==='attention'?pill('degraded','Needs attention'):pill('down','At risk');
}
/* Confidence is a three-level scale. It is drawn as a filled meter as well as
   written out, so it survives monochrome and does not rely on the reader
   parsing a sentence. The qualifier after an em dash is kept — "partial
   evidence" is the useful half of "low confidence". */
function confLevel(txt){
  const t=String(txt||'').toLowerCase();
  if(t.indexOf('high')===0)   return 3;
  if(t.indexOf('medium')===0) return 2;
  if(t.indexOf('low')===0)    return 1;
  return 0;
}
function confMeter(n){
  let bars='';
  for(let i=1;i<=3;i++){
    bars += '<rect x="'+((i-1)*5)+'" y="'+(10-i*3)+'" width="3" height="'+(i*3)+'" '+
            'class="'+(i<=n?'on':'off')+'"/>';
  }
  return '<svg class="confmeter" width="13" height="10" viewBox="0 0 13 10" aria-hidden="true" focusable="false">'+bars+'</svg>';
}
function confChip(txt){
  const n=confLevel(txt);
  if(!n) return '<span class="ai-conf conf-0" title="Model confidence">'+SH('dash',10)+esc('Not scored')+'</span>';
  const full=String(txt);
  const dash=full.indexOf('—');
  const head=(dash>-1?full.slice(0,dash):full).trim();
  const why =(dash>-1?full.slice(dash+1):'').trim();
  const word=head.split(/\s+/)[0];
  return '<span class="ai-conf conf-'+n+'" title="Model confidence: '+esc(full)+'">'+
    confMeter(n)+'<span class="conf-word">'+esc(word)+'</span>'+
    '<span class="sr-only"> '+esc('confidence')+'</span>'+
    (why?'<span class="conf-why">'+esc(why)+'</span>':'')+'</span>';
}
function aiInsight(i){
  return '<div class="ai-insight">'+
    '<span class="ai-mark">'+ICO(i.icon||'ai',12)+'</span>'+
    '<div class="ai-body">'+
      '<div class="ai-top"><h5>'+esc(i.title)+'</h5>'+confChip(i.conf)+'</div>'+
      '<p>'+i.body+'</p>'+
      (i.acts?'<div class="ai-acts">'+i.acts+'</div>':'')+
      /* The provenance line names real collections and counts, so only its
         label is translated. Renaming ONB_STATE would make it unverifiable. */
      (i.src?'<div class="ai-src">'+ICO('database',11)+
        esc(String(i.src).replace(/^Read:/, 'Read'+':'))+'</div>':'')+
    '</div></div>';
}
function verticalTiles(onclick){
  return '<div class="verticals">'+VERTICALS.map(v=>{
    const n=LIVE_PRODUCTS.filter(p=>p.v===v.id).length;
    return '<button class="vtile" onclick="'+onclick.replace('$V',v.id)+'">'+
      '<span class="vico cat-'+v.id+'" style="border-color:currentColor">'+ICO(v.icon,15)+'</span>'+
      '<span class="vname">'+esc(v.name.replace(' Marketplace',''))+'</span>'+
      '<span class="vcount">'+n+' listings · '+esc(v.aud)+'</span></button>';
  }).join('')+'</div>';
}

/* ===========================================================================
   STATE LAYER
   Actions in these prototypes mutate the shared dataset. An order placed in the
   consumer storefront is visible to the operator; a listing submitted by a
   partner lands in the operator's review queue; clearing the last onboarding
   gate makes a partner live everywhere. Nothing here is a stub that only fires
   a toast.
   =========================================================================== */

const SEQ = {ord:889200, sub:9200, apr:5600, lq:800, sku:9100, tck:2200, ptr:1015, obt:9500};
function nextId(pfx,key){ SEQ[key]+=1; return pfx+SEQ[key]; }
const TODAY = '25 Jul 2026';

/* ------------------------------- orders ---------------------------------- */
function createOrder(sku, qty, ctx){
  const p = SKUMAP[sku]; if(!p) return null;
  /* Reserve at order time. Units leave stock at dispatch, not before, so a
     cancellation before shipping returns them rather than losing them. */
  if(typeof reserveStock==='function') reserveStock(sku, qty, null, 'hard');
  const stages = PIPELINES[p.fulfil];
  const gross = +(p.price*qty).toFixed(2);
  const o = {
    id:nextId('ORD-','ord'),
    sku:p.id, name:p.name, v:p.v, cat:p.cat,
    seller:p.seller, partnerId:p.partner,
    buyer:ctx.buyer, buyerType:ctx.buyerType,
    qty:qty, unit:p.unit||null, gross:gross,
    comm:+(gross*(p.comm/100)).toFixed(2),
    model:p.model, fulfil:p.fulfil,
    stages:stages, stage:1, failed:false,           /* payment authorised / approved */
    placed:'Just now', channel:ctx.channel, pay:ctx.pay,
    isNew:true
  };
  ORDERS.unshift(o);
  return o;
}

/* Consumer purchase: creates orders, and a subscription for anything recurring. */
function placeConsumerOrders(){
  const made=[];
  CART.forEach(l=>{
    const p=SKUMAP[l.sku];
    const o=createOrder(l.sku, l.qty, {buyer:SHOPPER.name, buyerType:'Consumer',
      channel:'Consumer web', pay:'Bill to mobile'});
    if(o) made.push(o);
    if(p.model==='monthly'){
      MY_SUBS.unshift({
        id:nextId('SUB-','sub'), sku:p.id, name:p.name, seller:p.seller, v:p.v,
        price:p.price, cycle:'Monthly', next:'25 Aug 2026', started:TODAY,
        status:'active', autoRenew:true, isNew:true
      });
    }
  });
  CART.length=0; updateCartBadge(); recomputeDerived();
  return made;
}

/* Enterprise purchase: a requisition, which only becomes an order once approved. */
function createRequisition(ctx){
  const lines = CART.map(l=>({sku:l.sku, qty:l.qty, name:SKUMAP[l.sku].name, v:SKUMAP[l.sku].v,
                              price:SKUMAP[l.sku].price, model:SKUMAP[l.sku].model}));
  const total = lines.reduce((a,l)=>a+l.price*l.qty,0);
  const needsFinance = total>=2000;
  const hasSecurity = lines.some(l=>l.v==='security');
  const req = {
    id:nextId('APR-','apr'),
    item: lines.length===1 ? lines[0].name+(lines[0].qty>1?' ×'+lines[0].qty:'')
                           : lines.length+' items from '+new Set(lines.map(l=>SKUMAP[l.sku].seller)).size+' sellers',
    sku: lines[0].sku, lines: lines, v: lines[0].v,
    amount:+total.toFixed(2),
    requester: BUYER.who+' ('+BUYER.role+')',
    raised:'Just now',
    need: needsFinance ? 'Finance approval' : hasSecurity ? 'IT sign-off' : 'None — within policy',
    reason: ctx.reason || 'Raised from the business catalogue',
    status: (needsFinance||hasSecurity) ? 'pending' : 'approved',
    policy: needsFinance ? 'Above the '+CUR0(2000)+' threshold'
          : hasSecurity ? 'Security purchase — IT sign-off required'
          : 'Below the '+CUR0(2000)+' threshold',
    isNew:true
  };
  APPROVALS.unshift(req);
  CART.length=0; updateCartBadge();
  if(req.status==='approved') fulfilRequisition(req);
  recomputeDerived();
  return req;
}

/* Approving a requisition places the real orders and starts any subscription. */
function fulfilRequisition(req){
  const made=[];
  (req.lines||[{sku:req.sku, qty:1}]).forEach(l=>{
    const o=createOrder(l.sku, l.qty, {buyer:BUYER.company, buyerType:'Enterprise',
      channel:'Enterprise portal', pay:'Invoice, net 30'});
    if(o) made.push(o);
    const p=SKUMAP[l.sku];
    if(p && p.model==='monthly'){
      const existing = ENT_SUBS.find(s=>s.sku===p.id && s.status==='active');
      if(existing){
        existing.qty += l.qty; existing.seatsTotal += l.qty;
        existing.pending = (existing.pending||0) + l.qty;
        existing.monthly = +(existing.qty*existing.price).toFixed(2);
      } else {
        ENT_SUBS.unshift({
          id:nextId('ESB-','sub'), sku:p.id, name:p.name, seller:p.seller, v:p.v,
          unit:p.unit||'per licence', qty:l.qty, price:p.price,
          monthly:+(p.price*l.qty).toFixed(2), renews:'Rolling', status:'active',
          seatsUsed:0, seatsTotal:l.qty, pending:l.qty, isNew:true
        });
      }
    }
  });
  BUYER.budgetSpent = +(BUYER.budgetSpent + req.amount).toFixed(2);
  recomputeDerived();
  return made;
}

/* ---------------------- partner / product onboarding --------------------- */
/* One generic gate machine, used by the partner console and the operator queue. */
function onbCurrentGate(state){ return ONB_STEPS.find(s=>state[s.id]==='now') || null; }
function onbCleared(state){ return ONB_STEPS.filter(s=>state[s.id]==='done').length; }
function onbClearGate(state){
  const cur = onbCurrentGate(state);
  if(!cur) return null;
  state[cur.id]='done';
  /* Skip gates that are already cleared. A partner adding a second marketplace
     carries KYC and bank verification over, so those gates must not reopen. */
  for(let i=ONB_STEPS.indexOf(cur)+1; i<ONB_STEPS.length; i++){
    const nxt = ONB_STEPS[i];
    if(state[nxt.id]!=='done'){ state[nxt.id]='now'; return nxt; }
  }
  return null;                                   /* nothing left — journey complete */
}
function onbComplete(state){ return ONB_STEPS.every(s=>state[s.id]==='done'); }

/* Submitting a listing creates a real product and puts it in the operator queue. */
function createListing(spec){
  const id = nextId('SKU-','sku');
  const p = {
    id:id, v:spec.v, cat:spec.cat, name:spec.name||'Untitled listing',
    partner:spec.partner, seller:spec.seller,
    price:+spec.price||0, model:spec.model, fulfil:spec.fulfil,
    rating:null, reviews:0, stock:'in', status:'pending', listed:TODAY,
    desc:spec.desc||'No description provided.', tags:spec.tags||[],
    comm:spec.comm, endpoint:spec.endpoint||null, isNew:true
  };
  PRODUCTS.push(p); SKUMAP[id]=p;
  /* Media travels with the listing rather than being discarded at submit. */
  PRODUCT_MEDIA[id] = (spec.media||[]).map((m,i)=>Object.assign({},m,{id:'MD-'+id.replace('SKU-','')+'-'+(i+1)}));
  LISTING_QUEUE.unshift({
    id:nextId('LQ-','lq'), sku:id, name:p.name, partner:p.seller, v:p.v,
    submitted:TODAY, age:'Just now', check:'Standard listing review', risk:'low',
    issue:null, price:p.price, isNew:true
  });
  recomputeDerived();
  return p;
}
function publishListing(queueItem){
  const p = SKUMAP[queueItem.sku];
  if(p){ p.status='live'; }
  const i = LISTING_QUEUE.indexOf(queueItem);
  if(i>-1) LISTING_QUEUE.splice(i,1);
  recomputeDerived();
  return p;
}
function rejectListing(queueItem){
  const p = SKUMAP[queueItem.sku];
  if(p){ p.status='rejected'; }
  const i = LISTING_QUEUE.indexOf(queueItem);
  if(i>-1) LISTING_QUEUE.splice(i,1);
  recomputeDerived();
}

/* A partner that clears every gate goes live for real. */
function partnerGoLive(p){
  p.status='live'; p.joined=TODAY;
  if(!p.rating) p.rating=null;
  PRODUCTS.filter(x=>x.partner===p.id && x.status==='draft').forEach(x=>x.status='pending');
  /* Going live without a collections policy means the first failed payment on
     day one has nothing to run against. Onboarding seeds one from the category
     they sell in; they can edit it or replace it, but they never start empty. */
  const seeded = (typeof seedPartnerLadders==='function') ? seedPartnerLadders(p) : [];
  if(seeded.length && typeof audit==='function')
    audit('dunning.ladder',{object:p.name, after:'seeded',
      detail:seeded.length+' default ladder'+(seeded.length===1?'':'s')+' provided at onboarding from the '+
        (LPMAP[seeded[0].fromProfile]||{name:'category'}).name+' profile'});
  recomputeDerived();
  return seeded;
}

/* ------------------------------ settlement -------------------------------- */
function approveSettlementRun(period){
  audit('settlement.approved',{object:period+' run',
    detail:'Statements released for the cycle date', before:'pending', after:'approved'});
  let n=0;
  SETTLEMENTS.filter(s=>s.period===period && s.status==='pending').forEach(s=>{ s.status='approved'; n++; });
  recomputeDerived();
  return n;
}


/* A search box that re-renders its own page must hand focus back, or the field
   loses a character every keystroke. */
function searchRerender(el, assign, view){
  const pos = el.selectionStart;
  const id  = el.id;
  assign(el.value);
  App.go(view);
  /* App.go renders on a 90ms timer, so hand focus back just after that. */
  setTimeout(()=>{
    const again = document.getElementById(id);
    if(again){ again.focus(); try{ again.setSelectionRange(pos,pos); }catch(e){} }
  }, 125);
}


/* ------------------------------ partner invitation ------------------------ */
/* An invitation is a real record: the partner appears in the onboarding queue
   at the application gate, with a task owned by them and a stated recipient. */
function invitePartner(spec){
  const id = nextId('PTR-','ptr');
  const p = {
    id:id, name:spec.name, type:spec.type, verticals:spec.verticals.slice(),
    country:spec.country, tier:'Bronze', status:'onboarding', joined:'—',
    rating:null, plan:spec.plan||null, contact:spec.contact, email:spec.email,
    invited:TODAY, invitedBy:spec.invitedBy||'Marketplace operations', isNew:true
  };
  PARTNERS.push(p); PMAP[id]=p;
  ONB_STATE[id] = {apply:'now', kyc:'todo', agree:'todo', finance:'todo', tech:'todo',
                   assure:'todo', golive:'todo', started:TODAY, sla:'5 working days',
                   owner:'Marketplace onboarding desk'};
  /* Give the new seller the same ladder everybody else has, with only the gate
     they are actually on live. A queue that shows one task for a new partner
     and twelve for an old one is not a queue anybody can plan against. */
  seedTasksForPartner(id);
  const first=ONB_TASKS.filter(t=>t.partnerId===id && t.step==='apply' && t.key==='form')[0];
  if(first){
    first.detail='Invitation sent to '+spec.email+' on '+TODAY+'. The link is valid for 14 days.';
    first.due='In 14 days';
  }
  if(p.plan && CPMAP[p.plan]) CPMAP[p.plan].partners += 1;
  recomputeDerived();
  return p;
}
function resendInvite(id){
  const p=PMAP[id]; if(!p) return null;
  p.invited=TODAY;
  return p;
}

/* ===========================================================================
   ADMINISTRATION — users and roles, notification rules
   One implementation, four contexts. The shape is the same everywhere because
   the job is the same; the vocabulary and the permissions differ.
   =========================================================================== */

function orgRoles(ctx){ return ORG_ROLES[ctx]||[]; }
function orgUsers(ctx){ return ORG_USERS[ctx]||[]; }
function roleById(ctx,id){ return orgRoles(ctx).find(r=>r.id===id)||{name:id,scope:'—',perms:[]}; }
function roleUsers(ctx,id){ return orgUsers(ctx).filter(u=>u.role===id && u.status!=='removed'); }
function activeOrgUsers(ctx){ return orgUsers(ctx).filter(u=>u.status==='active'); }
function invitedOrgUsers(ctx){ return orgUsers(ctx).filter(u=>u.status==='invited'); }

function userStatePill(s){
  return s==='active'?pill('active','Active'):s==='invited'?pill('pending','Invited'):
         s==='suspended'?pill('suspended','Suspended'):pill('inactive','Removed');
}

/* ------------------------------ users and roles --------------------------- */
function usersView(cfg){
  const ctx=cfg.ctx;
  const roles=orgRoles(ctx), users=orgUsers(ctx).filter(u=>u.status!=='removed');
  const grid=PERM_GRID[ctx]||[];

  return pagehead(cfg.title,
    users.length+' '+cfg.userNoun+'s across '+roles.length+' roles · '+
    activeOrgUsers(ctx).length+' active, '+invitedOrgUsers(ctx).length+' invited'+
    (orgUsers(ctx).filter(u=>u.status==='suspended').length?', '+orgUsers(ctx).filter(u=>u.status==='suspended').length+' suspended':''),
    exportBtn(cfg.title)+
    '<button class="btn btn-primary" onclick="inviteOrgUserDialog(\''+ctx+'\')">'+ICO('userplus',14)+cfg.inviteLabel+'</button>')+
  '<div class="stack">'+

  (cfg.banner||'')+

  '<div class="grid g4">'+
    metric({icon:'users',label:cfg.userNoun.charAt(0).toUpperCase()+cfg.userNoun.slice(1)+'s',value:String(users.length),
      foot:activeOrgUsers(ctx).length+' active'})+
    metric({icon:'shield',label:'Roles',value:String(roles.length),
      foot:roles.filter(r=>r.system).length+' built-in, '+roles.filter(r=>!r.system).length+' custom'})+
    metric({icon:'mail',label:'Invited, not yet joined',value:String(invitedOrgUsers(ctx).length),
      foot:invitedOrgUsers(ctx).length?'Links expire 14 days after sending':'Nothing outstanding'})+
    metric({icon:'lock',label:'Security gaps',
      value:String(activeOrgUsers(ctx).filter(u=>!u.mfa || u.pwdStrength==='weak' || u.mustReset).length),
      foot:activeOrgUsers(ctx).filter(u=>!u.mfa).length+' without MFA · '+
           activeOrgUsers(ctx).filter(u=>u.pwdStrength==='weak').length+' weak password'})+
  '</div>'+

  panel('Roles in use',
    '<div class="tablewrap"><table class="tbl"><thead><tr><th style="min-width:180px">Role</th><th>Scope</th>'+
    '<th class="num">Full</th><th class="num">Scoped</th><th class="num">People</th><th></th></tr></thead><tbody>'+
    roles.map((r,i)=>'<tr><td><div class="cellmain">'+esc(r.name)+'</div>'+
      '<div class="cellsub t-num">'+esc(r.id)+(r.system?' · built-in':' · custom')+'</div></td>'+
      '<td>'+esc(r.scope)+'</td>'+
      '<td class="num t-num">'+grid.filter(row=>row[i+1]===2).length+'</td>'+
      '<td class="num t-num">'+grid.filter(row=>row[i+1]===1).length+'</td>'+
      '<td class="num t-num cellmain">'+roleUsers(ctx,r.id).length+'</td>'+
      '<td class="acts"><button class="btn btn-sm btn-quiet" onclick="App.go(\''+(cfg.rolesView||'roles')+'\')">Configure</button></td>'+
    '</tr>').join('')+'</tbody></table></div>',
    {flush:true,icon:'shield',
     sub:cfg.roleSub,
     acts:'<button class="btn btn-sm" onclick="App.go(\''+(cfg.rolesView||'roles')+'\')">'+ICO('key',13)+'Roles configuration</button>'})+

  /* Somebody invited a moment ago is on whichever page their surname falls on,
     which reads as the invitation having failed. Name them above the table. */
  /* Only while the invitation is still outstanding. A note about somebody who
     has since signed in — or been removed — is a note about nothing. */
  ((typeof LAST_INVITE!=='undefined' && LAST_INVITE[ctx] &&
    (users.filter(u=>u.id===LAST_INVITE[ctx].id && u.status==='invited').length>0))
    ? banner('info','<strong>'+esc(LAST_INVITE[ctx].name)+' has been invited as '+
      esc(LAST_INVITE[ctx].roleName)+'.</strong> The link goes to '+esc(LAST_INVITE[ctx].email)+
      ' and is valid for 14 days. They appear below as <em>Invited</em> until they sign in. '+
      '<button class="linkbtn" onclick="openOrgUser(\''+ctx+'\',\''+LAST_INVITE[ctx].id+
      '\')">Open their record</button>')
    : '')+

  panel(cfg.dirTitle, dt('dtOrgUsers_'+ctx,{
    rows:users, noun:cfg.userNoun+'s', pageSize:12, sortKey:'name', idKey:'id',
    onRow:"openOrgUser('"+ctx+"','$ID')",
    searchFields:['name','email','id'], searchPlaceholder:'Search name or email',
    chips:[{key:'status',options:[{label:'Active',value:'active'},{label:'Invited',value:'invited'},
      {label:'Suspended',value:'suspended'}]},
      /* Every role, not the first four. A filter that cannot reach two thirds
         of the roles is a filter that quietly lies about what is there. */
      {key:'role',options:roles.map(r=>({label:r.name,value:r.id}))}],
    actions:exportBtn(cfg.dirTitle),
    columns:[
      {key:'name',label:cfg.userNoun.charAt(0).toUpperCase()+cfg.userNoun.slice(1),render:r=>
        '<div class="row" style="gap:8px"><span class="avatar" aria-hidden="true">'+esc(FMT.initials(r.name))+'</span>'+
        '<div><div class="cellmain">'+esc(r.name)+(r.you?' <span class="tag">you</span>':'')+'</div>'+
        '<div class="cellsub">'+esc(r.email)+'</div></div></div>'},
      {key:'role',label:'Role',render:r=>'<div class="cellmain">'+esc(roleById(ctx,r.role).name)+'</div>'+
        '<div class="cellsub">'+esc(roleById(ctx,r.role).scope)+'</div>'},
      (cfg.showCap
        ? {key:'cap',label:'Monthly cap',align:'right',render:r=>
            r.cap==null?'<span class="t-small muted">No cap</span>'
            :r.cap===0?'<span class="t-small muted">Cannot buy</span>'
            :'<div style="min-width:120px">'+meter(Math.min(100,(r.spent||0)/r.cap*100), CUR(r.spent||0)+' of '+CUR(r.cap))+'</div>'}
        : {key:'lastActive',label:'Last active',render:r=>r.lastActive==='Never'
            ?'<span class="nodata">Never signed in</span>':esc(r.lastActive)}),
      {key:'mfa',label:'MFA',render:r=>r.mfa?pill('active','On'):pill('warning','Off')},
      {key:'pwdChanged',label:'Password',render:r=>r.mustReset
        ? pill('overdue','Reset required')
        : r.pwdChanged
          ? '<div class="t-small">'+esc(r.pwdChanged)+'</div><div class="cellsub">'+
            (r.pwdStrength==='weak'?'weak':r.pwdStrength==='fair'?'fair':'strong')+'</div>'
          : '<span class="nodata">Not set</span>'},
      {key:'status',label:'State',render:r=>userStatePill(r.status)},
      {key:'__acts',label:'',sort:false,render:r=>
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();openOrgUser(\''+ctx+'\',\''+r.id+'\')">Manage</button>'}
    ]}),{flush:true,icon:'users'})+
  securityPanel(ctx)+
  '</div>';
}

function openOrgUser(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  const r=roleById(ctx,u.role);
  const isCon = ctx==='consumer';
  openInspector(
    '<div class="insp-head"><span class="avatar" style="width:36px;height:36px;font-size:13px" aria-hidden="true">'+
      esc(FMT.initials(u.name))+'</span><div class="grow">'+
      '<div class="row" style="gap:6px">'+userStatePill(u.status)+(u.mfa?pill('active','MFA on'):pill('warning','MFA off'))+'</div>'+
      '<h3 class="t-sub" style="margin-top:5px">'+esc(u.name)+(u.you?' (you)':'')+'</h3>'+
      '<div class="t-small muted">'+esc(u.email)+' · '+esc(u.id)+'</div></div>'+
      '<button class="iconbtn" onclick="closeInspector()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="insp-body stack">'+
      (u.status==='invited'?banner('info','Invitation sent '+esc(u.joined)+' to <strong>'+esc(u.email)+
        '</strong>. They have not signed in yet, so no permissions are in effect.'):'')+
      (u.note?banner('warning',esc(u.note)):'')+
      '<dl class="deflist">'+
        '<dt>Role</dt><dd>'+esc(r.name)+'<div class="t-tiny muted">'+esc(r.scope)+'</div></dd>'+
        '<dt>'+(isCon?'Added':'Joined')+'</dt><dd>'+esc(u.joined)+'</dd>'+
        '<dt>Last active</dt><dd>'+(u.lastActive==='Never'?'<span class="nodata">Never signed in</span>':esc(u.lastActive))+'</dd>'+
        '<dt>Multi-factor</dt><dd>'+(u.mfa?'On':'Off — policy expects it for anyone who can approve or pay')+'</dd>'+
        '<dt>Password</dt><dd>'+(u.mustReset
          ? '<span style="color:var(--nim-danger-fg)">Reset required before next sign-in</span>'
          : u.pwdChanged ? 'Last changed '+esc(u.pwdChanged)+' · '+esc(u.pwdStrength)
                         : '<span class="nodata">Not set — signs in by one-time code</span>')+'</dd>'+
        '<dt>Open sessions</dt><dd>'+(u.sessions||0)+'</dd>'+
        (u.lastReset?'<dt>Last reset sent</dt><dd>'+esc(u.lastReset)+'</dd>':'')+
        (isCon&&u.cap!=null?'<dt>Monthly cap</dt><dd>'+(u.cap===0?'Cannot buy':CUR(u.cap)+' · '+CUR(u.spent||0)+' used this month')+'</dd>':'')+
      '</dl>'+
      '<div class="divider"></div><h4 class="t-sub">What this role permits</h4>'+
      '<div class="tagset">'+r.perms.map(p=>'<span class="tag">'+esc(p)+'</span>').join('')+'</div>'+
    '</div>'+
    '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button><div class="spacer"></div>'+
      (u.status==='invited'
        ? '<button class="btn btn-sm" onclick="resendOrgInvite(\''+ctx+'\',\''+u.id+'\')">Resend invitation</button>'
        : u.you
          ? '<button class="btn btn-sm" onclick="changePasswordDialog(\''+ctx+'\',\''+u.id+'\')">Change my password</button>'
          : '<button class="btn btn-sm" onclick="resetUserPassword(\''+ctx+'\',\''+u.id+'\')">Send reset link</button>'+
            '<button class="btn btn-sm" onclick="forceResetUser(\''+ctx+'\',\''+u.id+'\')">Force reset</button>')+
      (isCon&&u.cap!=null&&!u.you
        ? '<button class="btn btn-sm" onclick="setSpendCapDialog(\''+ctx+'\',\''+u.id+'\')">Spend cap</button>'
        : '')+
      '<button class="btn btn-sm" onclick="changeRoleDialog(\''+ctx+'\',\''+u.id+'\')">Change role</button>'+
      (u.you
        ? '<span class="t-tiny muted">You cannot remove yourself</span>'
        : '<button class="btn btn-sm btn-danger" onclick="removeOrgUserDialog(\''+ctx+'\',\''+u.id+'\')">'+
          (isCon?'Remove':'Deactivate')+'</button>')+
    '</div>', u.name);
}

function inviteOrgUserDialog(ctx){
  const roles=orgRoles(ctx);
  const isCon = ctx==='consumer';
  openModal('<div class="modal-head">'+ICO('userplus',18)+'<div class="grow"><h3 class="t-sub">'+
    (isCon?'Add someone to your account':'Invite a user')+'</h3>'+
    '<div class="t-small muted">'+(isCon
      ? 'They get an invitation by email and pick their own sign-in. Nothing is charged for adding a person.'
      : 'They receive a sign-in invitation by email. Permissions only take effect once they accept.')+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="grid g2">'+
        '<div class="field"><label for="iuName">Full name</label><input class="inp" id="iuName" data-autofocus placeholder="'+
          (isCon?'e.g. Rohan Raman':'e.g. Sofia Almeida')+'">'+
          '<div class="err" id="iuNameErr" hidden>'+ICO('alert',12)+'A name is required.</div></div>'+
        '<div class="field"><label for="iuEmail">Email</label><input class="inp" id="iuEmail" inputmode="email" placeholder="name@6dtech.co.in">'+
          '<div class="err" id="iuEmailErr" hidden>'+ICO('alert',12)+'A valid email is required — the invitation goes there.</div></div>'+
      '</div>'+
      '<div class="field"><label for="iuRole">Role</label><select class="inp" id="iuRole">'+
        roles.map(r=>'<option value="'+r.id+'">'+esc(r.name)+' — '+esc(r.scope)+'</option>').join('')+'</select>'+
        '<div class="hint">Roles are defined above. You can change it later.</div></div>'+
      (isCon
        ? '<div class="field"><label for="iuCap">Monthly spend cap</label><select class="inp" id="iuCap">'+
          '<option value="0">Cannot buy anything</option><option value="15">'+CUR(15)+' a month</option>'+
          '<option value="25" selected>'+CUR(25)+' a month</option><option value="40">'+CUR(40)+' a month</option>'+
          '<option value="">No cap</option></select>'+
          '<div class="hint">Anything above the cap comes to you for approval.</div></div>'
        : '<label class="checkline"><input type="checkbox" id="iuMfa" checked> Require multi-factor authentication at first sign-in</label>')+
      '<div class="impact"><strong>What happens next</strong><ul>'+
        '<li>An invitation is emailed to the address above and expires in 14 days.</li>'+
        '<li>They appear immediately as <strong>Invited</strong> with no permissions in effect.</li>'+
        '<li>Permissions start the moment they accept and sign in.</li>'+
        (isCon?'<li>Adding a person costs nothing — only what they buy is charged.</li>'
              :'<li>The invitation and the role granted are written to the audit trail.</li>')+
      '</ul></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">You can withdraw an invitation before it is accepted.</span>'+
    '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
    '<button class="btn btn-primary" onclick="submitOrgInvite(\''+ctx+'\')">'+
      (isCon?'Send invitation':'Send invitation')+'</button></div>',
    {wide:true,label:'Invite a user'});
}
function submitOrgInvite(ctx){
  const g=id=>document.getElementById(id);
  const name=(g('iuName').value||'').trim();
  const email=(g('iuEmail').value||'').trim();
  const okEmail=/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(email);
  g('iuNameErr').hidden=!!name;  g('iuName').setAttribute('aria-invalid',!name);
  g('iuEmailErr').hidden=okEmail;g('iuEmail').setAttribute('aria-invalid',!okEmail);
  if(!name||!okEmail){ (!name?g('iuName'):g('iuEmail')).focus(); return; }
  const role=g('iuRole').value;
  const capEl=g('iuCap');
  const mfaEl=g('iuMfa');
  closeModal();
  const u=addOrgUser(ctx,{name:name, email:email, role:role,
    cap: capEl ? (capEl.value===''?null:+capEl.value) : undefined,
    mfa: mfaEl ? mfaEl.checked : false});
  LAST_INVITE[ctx]={id:u.id, name:name, email:email,
    roleName:(roleById(ctx,role)||{}).name||role};
  toast('Invitation sent to '+name+' at '+email+' as '+roleById(ctx,role).name);
  App.go(App.view);
}
/* Who was invited most recently, per console, so the directory can say so
   rather than leaving them to be hunted for. */
const LAST_INVITE={};
function addOrgUser(ctx,spec){
  logAudit(ctx,'user.invited',{object:spec.email, detail:'Invited as '+
    ((roleById(ctx,spec.role)||{}).name||spec.role)+(spec.cap?' with a '+CUR(spec.cap)+' monthly cap':'')});
  SEQ.orgu = (SEQ.orgu||0)+1;
  const pfx={operator:'OU-',partner:'PU-',buyer:'BU-',consumer:'CU-'}[ctx]||'XU-';
  const u={id:pfx+(90+SEQ.orgu), name:spec.name, email:spec.email, role:spec.role,
           status:'invited', lastActive:'Never', mfa:!!spec.mfa, joined:TODAY, isNew:true};
  if(spec.cap!==undefined){ u.cap=spec.cap; u.spent=0; }
  ORG_USERS[ctx].push(u);
  return u;
}
function resendOrgInvite(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  u.joined=TODAY;
  toast('Invitation resent to '+u.email+' — link valid for 14 days');
  closeInspector(); App.go(App.view);
}
function changeRoleDialog(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  const cur=roleById(ctx,u.role);
  closeInspector();
  confirmAction({
    title:'Change role for '+u.name, subtitle:'Currently '+cur.name+' · '+cur.scope,
    risk: u.you ? 'high' : 'normal',
    confirmLabel:'Change role', requireType: u.you ? 'CHANGE' : null,
    body:'<div class="field"><label for="crRole">New role</label><select class="inp" id="crRole" data-autofocus>'+
      orgRoles(ctx).map(r=>'<option value="'+r.id+'"'+(r.id===u.role?' selected':'')+'>'+esc(r.name)+' — '+esc(r.scope)+'</option>').join('')+
      '</select></div>'+
      '<div class="field" style="margin-top:12px"><label for="crWhy">Reason (kept in the audit trail)</label>'+
      '<textarea class="inp" id="crWhy"></textarea></div>',
    impact:[
      'Permissions change at their next sign-in — an open session keeps the old role until it ends.',
      esc(u.name)+' is notified by email that their access changed and by whom.',
      u.you ? '<strong>You are changing your own role.</strong> If the new role cannot manage users, you will not be able to change it back yourself.'
            : 'Anything they have already done keeps their old role recorded against it.',
      'The change is written to the audit trail with your identity.'
    ],
    footNote: u.you ? 'Type CHANGE to confirm you understand you may lock yourself out of this screen.' : '',
    onConfirm:(vals)=>{
      const to=(vals||{}).crRole||u.role;
      const from=roleById(ctx,u.role).name;
      logAudit(ctx,'user.role.changed',{object:u.name+' · '+u.email,
        detail:'Takes effect at their next sign-in',
        before:from, after:(roleById(ctx,to)||{}).name||to});
      u.role=to;
      toast(u.name+' moved from '+from+' to '+roleById(ctx,to).name);
      App.go(App.view);
    }
  });
}
function removeOrgUserDialog(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  const isCon=ctx==='consumer';
  closeInspector();
  confirmAction({
    title:(isCon?'Remove ':'Deactivate ')+u.name, subtitle:roleById(ctx,u.role).name+' · '+u.email,
    risk:'high', confirmLabel:(isCon?'Remove from the account':'Deactivate'), requireType:'REMOVE',
    body:'<div class="field"><label for="ruWhy">Reason</label><textarea class="inp" id="ruWhy" data-autofocus '+
      'placeholder="Kept in the audit trail"></textarea></div>',
    impact:[
      'Access ends immediately and any open session is terminated.',
      isCon ? 'Anything they subscribed to stays on the account and keeps billing until you cancel it.'
            : 'Work they own — requisitions, tickets, listings — stays and is reassigned to you.',
      'Their history is retained for audit; this is not a deletion.',
      isCon ? 'You can re-invite them later, but their profile with sellers starts fresh.'
            : 'Re-inviting them later creates a new invitation, not a restore.'
    ],
    footNote:'Type REMOVE to confirm.',
    onConfirm:()=>{
      logAudit(ctx,'user.removed',{object:u.name+' · '+u.email,
        detail:'Access ended; history retained for audit', before:u.status, after:'removed'});
      u.status='removed';
      toast(u.name+(isCon?' removed from the account':' deactivated')+' — access ended','warn');
      App.go(App.view);
    }
  });
}
function setSpendCapDialog(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  closeInspector();
  confirmAction({
    title:'Spend cap for '+u.name, subtitle:(u.cap?CUR(u.cap)+' a month · '+CUR(u.spent||0)+' used':'No cap set'),
    risk:'normal', confirmLabel:'Save cap',
    body:'<div class="field"><label for="scCap">Monthly cap</label><select class="inp" id="scCap" data-autofocus>'+
      ['0','15','25','40','60',''].map(v=>'<option value="'+v+'"'+((u.cap==null&&v==='')||String(u.cap)===v?' selected':'')+'>'+
        (v===''?'No cap':v==='0'?'Cannot buy anything':CUR(+v)+' a month')+'</option>').join('')+'</select></div>',
    impact:[
      'Applies from now — it does not claw back anything already bought this month.',
      'Anything above the cap becomes a request that comes to you for approval.',
      esc(u.name)+' sees their cap and what is left of it on their own screen.',
      'Subscriptions already running continue even if they exceed a new lower cap.'
    ],
    onConfirm:(vals)=>{
      const v=(vals||{}).scCap;
      logAudit(ctx,'cap.changed',{object:u.name,
        detail:'Monthly spend cap adjusted',
        before:(u.cap==null?'no cap':CUR(u.cap)), after:(v===''?'no cap':v==='0'?'no purchases':CUR(+v))});
      u.cap = v==='' ? null : +v;
      toast('Cap for '+u.name+' set to '+(u.cap==null?'no cap':u.cap===0?'no purchases':CUR(u.cap)+' a month'));
      App.go(App.view);
    }
  });
}

/* ---------------------------- notification rules -------------------------- */
function notifView(cfg){
  const ctx=cfg.ctx;
  const rules=NOTIF_RULES[ctx]||[];
  const prefs=NOTIF_PREFS[ctx]||{};
  const log=NOTIF_LOG[ctx]||[];
  const chans=cfg.channels||['In-app','Email','SMS'];
  const on=rules.filter(r=>r.on);

  return pagehead(cfg.title,
    on.length+' of '+rules.length+' rules are on · '+cfg.scopeNote,
    '<button class="btn" onclick="App.notifications()">'+ICO('bell',13)+'Recent alerts</button>'+
    (cfg.canCreate!==false
      ? '<button class="btn btn-primary" onclick="newNotifRuleDialog(\''+ctx+'\')">'+
        ICO('plus',14)+'New rule</button>' : ''))+
  '<div class="stack">'+

  (cfg.banner||'')+

  '<div class="grid g4">'+
    metric({icon:'bell',label:'Rules on',value:on.length+' of '+rules.length,
      foot:rules.filter(r=>r.sev==='high'&&r.on).length+' are urgent-severity'})+
    metric({icon:'send',label:'Sent in the last 7 days',value:cfg.sentCount||'184',foot:'Across all channels'})+
    metric({icon:'alert',label:'Failed delivery',value:String(log.filter(l=>l.state!=='delivered').length),
      foot:log.filter(l=>l.state!=='delivered').length?'Bounced — check the address':'Everything delivered'})+
    metric({icon:'clock',label:'Quiet hours',value:prefs.quiet&&prefs.quiet!=='None — operations run 24/7'?'On':'Off',
      foot:esc(prefs.quiet||'Not set')})+
  '</div>'+

  (cfg.rules===false ? '' :
  panel('Rules', dt('dtNotif_'+ctx,{
    rows:rules, noun:'rules', pageSize:12, toolbar:false, sortKey:'id', idKey:'id',
    onRow:"editNotifRule('"+ctx+"','$ID')",
    columns:[
      {key:'name',label:'Alert',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.id)+'</div>'},
      {key:'event',label:'Fires when',render:r=>'<span class="t-small">'+esc(r.event)+'</span>'},
      {key:'who',label:'Goes to',render:r=>'<span class="t-small">'+esc(r.who)+'</span>'},
      {key:'chans',label:'Channels',sort:false,render:r=>'<div class="tagset">'+
        r.chans.map(c=>'<span class="tag">'+esc(c)+'</span>').join('')+'</div>'},
      {key:'sev',label:'Severity',render:r=>r.sev==='high'?pill('overdue','Urgent'):r.sev==='low'?pill('neutral','Low'):pill('open','Normal')},
      {key:'last',label:'Last fired',render:r=>r.last==='Never'?'<span class="dim">Never</span>':esc(r.last)},
      {key:'throttle',label:'How often',render:r=>'<span class="t-small">'+esc(r.throttle||'Every time')+'</span>'},
      {key:'on',label:'On',render:r=>'<label class="toggle"><input type="checkbox" '+(r.on?'checked':'')+
        ' onchange="event.stopPropagation();toggleNotifRule(\''+ctx+'\',\''+r.id+'\',this.checked)"><span class="track"></span>'+
        '<span class="sr-only">'+esc(r.name)+'</span></label>'},
      {key:'__acts',label:'',sort:false,render:r=>
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();editNotifMessage(\''+ctx+'\',\''+r.id+'\')">Message</button>'+
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();editNotifRule(\''+ctx+'\',\''+r.id+'\')">Edit</button>'}
    ]}),{flush:true,icon:'bell',
    sub:'Turning a rule off stops it for everyone it is addressed to, not just for you.'}))+

  (cfg.messages===false ? '' : notifMessagesPanel(ctx))+

  '<div class="'+(cfg.severity===false?'stack':'grid g2')+'">'+
    (cfg.severity===false ? '' :
    panel('Channels by severity',
      '<div class="tablewrap"><table class="tbl"><thead><tr><th>Severity</th>'+
      chans.map(c=>'<th style="text-align:center">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+
      [['Urgent','high'],['Normal','normal'],['Low','low']].map(sv=>{
        const set=rules.filter(r=>r.sev===sv[1]&&r.on);
        return '<tr><td class="cellmain">'+sv[0]+'<div class="cellsub">'+set.length+' rules on</div></td>'+
          chans.map(c=>{
            const used=set.some(r=>r.chans.indexOf(c)>-1);
            return '<td style="text-align:center">'+(used
              ? '<span class="pill pill-success">'+SH('check')+'On</span>'
              : '<span class="dim">'+SH('dash',11)+'</span>')+'</td>';
          }).join('')+'</tr>';
      }).join('')+'</tbody></table></div>'+
      '<div class="divider"></div>'+
      '<div class="t-tiny muted">SMS is reserved for urgent severity so it keeps meaning something.</div>',
      {flush:false,icon:'send'}))+

    panel('Delivery preferences',
      '<div class="stack" style="gap:11px">'+
        '<div class="field"><label for="npDigest">Bundle non-urgent alerts</label>'+
        '<select class="inp" id="npDigest" onchange="setNotifPref(\''+ctx+'\',\'digest\',this.value)">'+
          ['Off — send every alert','Daily digest at 08:00','Weekly digest, Monday 08:00'].map(o=>
          '<option'+(prefs.digest===o?' selected':'')+'>'+esc(o)+'</option>').join('')+'</select></div>'+
        '<div class="field"><label for="npQuiet">Quiet hours</label>'+
        '<select class="inp" id="npQuiet" onchange="setNotifPref(\''+ctx+'\',\'quiet\',this.value)">'+
          [prefs.quiet,'None','21:00 to 07:00 except failures','22:00 to 07:00 except delivery problems',
           '19:00 to 08:00 except overdue invoices'].filter((v,i,a)=>v&&a.indexOf(v)===i).map(o=>
          '<option'+(prefs.quiet===o?' selected':'')+'>'+esc(o)+'</option>').join('')+'</select>'+
        '<div class="hint">'+esc(cfg.quietNote||'Urgent alerts always come through.')+'</div></div>'+
        '<label class="toggle"><input type="checkbox" '+(prefs.escalate?'checked':'')+
          ' onchange="setNotifPref(\''+ctx+'\',\'escalate\',this.checked)"><span class="track"></span>'+
          esc(cfg.escalateLabel||'Escalate an unacknowledged urgent alert after 30 minutes')+'</label>'+
      '</div>'+
      '<div class="divider"></div>'+
      '<div class="row"><span class="t-tiny muted grow">Preferences apply to '+esc(cfg.prefScope||'this account')+'.</span>'+
      (cfg.test===false?''
        :'<button class="btn btn-sm" onclick="sendTestNotif(\''+ctx+'\')">Send a test</button>')+'</div>',
      {icon:'settings'})+
  '</div>'+

  (cfg.recent===false ? '' :
  panel('Recent deliveries',
    '<table class="tbl"><thead><tr><th>When</th><th>Rule</th><th>Recipients</th><th>Channels</th><th>State</th></tr></thead><tbody>'+
    log.map(l=>'<tr><td class="cellmain">'+esc(l.when)+'</td><td>'+esc(l.rule)+'</td>'+
      '<td>'+esc(l.to)+'</td><td><div class="tagset">'+l.chan.split(', ').map(c=>'<span class="tag">'+esc(c)+'</span>').join('')+'</div></td>'+
      '<td>'+(l.state==='delivered'?pill('active','Delivered'):pill('down','Bounced'))+'</td></tr>').join('')+
    '</tbody></table>'+
    (log.some(l=>l.state!=='delivered')
      ? '<div class="divider"></div>'+banner('warning','One delivery bounced. A bounced address is retried twice, then the rule stops targeting it until the address is corrected.')
      : ''),
    {flush:false,icon:'history'}))+
  (cfg.append||'')+
  '</div>';
}
function toggleNotifRule(ctx,id,on){
  const r=(NOTIF_RULES[ctx]||[]).find(x=>x.id===id); if(!r) return;
  r.on=!!on;
  toast(r.name+' '+(r.on?'on — sending to '+r.who.toLowerCase():'off — nobody will be alerted'), r.on?'ok':'warn');
}
function setNotifPref(ctx,key,val){
  NOTIF_PREFS[ctx]=NOTIF_PREFS[ctx]||{};
  NOTIF_PREFS[ctx][key]=val;
  toast(key==='digest'?'Bundling set to “'+val+'”'
       :key==='quiet'?'Quiet hours set to “'+val+'”'
       :'Escalation '+(val?'on':'off'));
}
/* A test that only says "sent" proves nothing. This creates a real delivery
   against the real provider, so it lands in the delivery log with a receipt
   state like any other message — including a channel with no true receipt,
   which is the thing worth discovering before you rely on it. */
function sendTestNotif(ctx){
  const chans=((NOTIF_RULES[ctx]||[])[0]||{}).chans||['Email'];
  const made=[];
  chans.forEach(ch=>{
    const prov=CHANNEL_PROVIDERS.filter(p=>p.chan===ch && p.role==='primary')[0]
             || CHANNEL_PROVIDERS.filter(p=>p.chan===ch)[0];
    if(!prov){ return; }
    window.__DLRSEQ=(window.__DLRSEQ||0)+1;
    const d={id:'MSG-T'+window.__DLRSEQ, ctx:ctx, chan:ch, provider:prov.name,
      to:testRecipient(ctx,ch), rule:'Test message', when:TODAY+' just now',
      attempts:1, state:prov.dlr?'delivered':'unknown', code:null,
      cost:prov.cost||0, isTest:true, isNew:true};
    DELIVERIES.unshift(d); made.push(d);
  });
  if(!made.length){ toast('No provider is configured for those channels','warn'); return; }
  const noReceipt=made.filter(d=>d.state==='unknown');
  if(typeof audit==='function') audit('channel.config',{object:'Test message',
    detail:'Test sent over '+made.map(d=>d.chan).join(', ')+' — visible in the delivery log', sev:'info'});
  toast(noReceipt.length
    ? 'Sent over '+made.map(d=>d.chan).join(' and ')+' — '+
      noReceipt.map(d=>d.chan).join(' and ')+' returns no receipt, so it shows as sent, not delivered'
    : 'Sent over '+made.map(d=>d.chan).join(' and ')+' — check the delivery log for the receipt');
  if(typeof App!=='undefined') App.go(App.view);
}
function testRecipient(ctx,ch){
  const mail = ctx==='operator' ? 'ops@6dtech.co.in'
             : ctx==='partner'  ? ((typeof ME_P!=='undefined'&&ME_P)?'billing@'+ME_P.name.toLowerCase().replace(/[^a-z]+/g,'')+'.example':'seller@example')
             : ctx==='buyer'    ? 'procurement@gmail.com'
             : 'you@example';
  if(ch==='Email') return mail;
  if(ch==='SMS'||ch==='WhatsApp') return '+91 80000 6' + String(1000+(ctx.length*7)).slice(0,4);
  return mail;
}

/* ===========================================================================
   ROLES CONFIGURATION
   The permission grid is the configuration surface, not a picture of one.
   Every cell is a control; the matrix and the role list stay in step.
   =========================================================================== */
const PERM_LEVELS = [
  {v:2, name:'Full',    cls:'success', shape:'check', hint:'May do this without limit'},
  {v:1, name:'Scoped',  cls:'partial', shape:'half',  hint:'May do this only inside its own boundary'},
  {v:0, name:'None',    cls:'neutral', shape:'dash',  hint:'Not permitted'}
];
function permCell(ctx,row,col,editable){
  const v=PERM_GRID[ctx][row][col+1];
  const L=PERM_LEVELS.find(x=>x.v===v)||PERM_LEVELS[2];
  const inner = v===0
    ? '<span class="dim" title="'+esc(L.hint)+'">'+SH('dash',11)+'</span>'
    : '<span class="pill pill-'+L.cls+'" title="'+esc(L.hint)+'">'+SH(L.shape)+esc(L.name)+'</span>';
  if(!editable) return inner;
  return '<button class="permcell" onclick="cyclePerm(\''+ctx+'\','+row+','+col+')" '+
    'aria-label="'+esc(PERM_GRID[ctx][row][0]+' — '+ORG_ROLES[ctx][col].name+' — currently '+L.name+'. Click to change.')+'">'+
    inner+'</button>';
}
function cyclePerm(ctx,row,col){
  (function(){ const g=PERM_GRID[ctx]; const r=g&&g[row]; const rn=(orgRoles(ctx)[col]||{}).name;
    if(r) logAudit(ctx,'role.perm.changed',{object:rn+' · '+r[0],
      detail:'Changed in the roles matrix', before:PERM_LEVELS[r[col+1]], after:PERM_LEVELS[(r[col+1]+1)%3]}); })();
  const cur=PERM_GRID[ctx][row][col+1];
  const order=[2,1,0];
  PERM_GRID[ctx][row][col+1]=order[(order.indexOf(cur)+1)%order.length];
  const nxt=PERM_LEVELS.find(x=>x.v===PERM_GRID[ctx][row][col+1]);
  syncRolePerms(ctx,col);
  toast(ORG_ROLES[ctx][col].name+' — '+PERM_GRID[ctx][row][0].toLowerCase()+' set to '+nxt.name.toLowerCase());
  App.go(App.view);
}
/* The permission tags on a role are derived from the grid, so the two can
   never disagree. */
function syncRolePerms(ctx,col){
  const r=ORG_ROLES[ctx][col]; if(!r) return;
  r.perms = PERM_GRID[ctx]
    .filter(row=>row[col+1]>0)
    .map(row=>row[0].toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.|\.$/g,'').slice(0,34));
  r.granted = PERM_GRID[ctx].filter(row=>row[col+1]===2).length;
  r.scopedCount = PERM_GRID[ctx].filter(row=>row[col+1]===1).length;
}

function rolesView(cfg){
  const ctx=cfg.ctx;
  const roles=orgRoles(ctx), grid=PERM_GRID[ctx]||[];
  const assigned=id=>roleUsers(ctx,id).length;
  return pagehead(cfg.title||'Roles configuration',
    roles.length+' roles · '+grid.length+' capabilities · every cell below is editable',
    exportBtn('Role configuration')+
    '<button class="btn btn-primary" onclick="createRoleDialog(\''+ctx+'\')">'+ICO('plus',14)+'Create a role</button>')+
  '<div class="stack">'+

  (cfg.banner||banner('info','Changing a permission takes effect at the next sign-in for anyone holding the role. '+
    'Built-in roles can be edited but not deleted, because the platform routes work to them by name.'))+

  '<div class="grid g4">'+
    metric({icon:'shield',label:'Roles',value:String(roles.length),
      foot:roles.filter(r=>r.system).length+' built-in, '+roles.filter(r=>!r.system).length+' custom'})+
    metric({icon:'key',label:'Capabilities governed',value:String(grid.length),foot:'Each can be full, scoped or none'})+
    metric({icon:'users',label:'Assignments',value:String(orgUsers(ctx).filter(u=>u.status!=='removed').length),
      foot:roles.filter(r=>!assigned(r.id)).length+' roles with nobody in them'})+
    metric({icon:'lock',label:'Roles that can manage users',
      value:String(grid.filter(r=>/manage users|Add or remove people/i.test(r[0]))
        .reduce((a,r)=>Math.max(a, r.slice(1).filter(v=>v===2).length),0)),
      foot:'Keep this small — it is the keys to the account'})+
  '</div>'+

  panel('Roles', dt('dtRoleCfg_'+ctx,{
    rows:roles, noun:'roles', pageSize:12, toolbar:false, sortKey:'name', idKey:'id',
    columns:[
      {key:'name',label:'Role',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.id)+(r.system?' · built-in':' · custom')+'</div>'},
      {key:'scope',label:'Scope',render:r=>esc(r.scope)},
      {key:'__full',label:'Full',align:'right',sort:false,render:r=>{
        const i=roles.indexOf(r);
        return '<span class="t-num">'+grid.filter(row=>row[i+1]===2).length+'</span>';}},
      {key:'__scoped',label:'Scoped',align:'right',sort:false,render:r=>{
        const i=roles.indexOf(r);
        return '<span class="t-num">'+grid.filter(row=>row[i+1]===1).length+'</span>';}},
      {key:'__none',label:'None',align:'right',sort:false,render:r=>{
        const i=roles.indexOf(r);
        return '<span class="t-num dim">'+grid.filter(row=>row[i+1]===0).length+'</span>';}},
      {key:'__n',label:'People',align:'right',sort:false,render:r=>assigned(r.id)
        ? '<span class="t-num cellmain">'+assigned(r.id)+'</span>'
        : '<span class="dim">Nobody</span>'},
      {key:'__acts',label:'',sort:false,render:r=>
        '<button class="btn btn-sm btn-quiet" onclick="editRoleDialog(\''+ctx+'\',\''+r.id+'\')">Edit</button>'+
        '<button class="btn btn-sm btn-quiet" onclick="cloneRole(\''+ctx+'\',\''+r.id+'\')">Clone</button>'+
        (r.system
          ? '<button class="btn btn-sm btn-quiet" disabled title="Built-in roles cannot be deleted">Delete</button>'
          : '<button class="btn btn-sm btn-quiet" onclick="deleteRoleDialog(\''+ctx+'\',\''+r.id+'\')">Delete</button>')}
    ]}),{flush:true,icon:'shield'})+

  panel('Permission matrix',
    /* With a dozen roles the matrix is wider than any screen. It scrolls, and
       the capability column is pinned — a grid of ticks you can scroll but
       whose row labels have gone is worse than no grid. */
    (roles.length>7
      ? '<p class="t-tiny muted" style="margin:0 0 8px">'+roles.length+' roles — scroll sideways to reach '+
        'them all. The capability stays in view.</p>'
      : '')+
    '<div class="tablewrap"><table class="tbl permgrid"><thead><tr>'+
      '<th class="pinned" style="min-width:250px">Capability</th>'+
    roles.map((r,i)=>'<th style="text-align:center;min-width:104px">'+esc(r.name)+
      '<div class="cellsub" style="font-weight:400">'+assigned(r.id)+' '+(assigned(r.id)===1?'person':'people')+'</div></th>').join('')+
    '</tr></thead><tbody>'+
    grid.map((row,ri)=>'<tr><td class="cellmain pinned">'+esc(row[0])+'</td>'+
      roles.map((r,ci)=>'<td style="text-align:center">'+permCell(ctx,ri,ci,true)+'</td>').join('')+
    '</tr>').join('')+
    '</tbody></table></div>',
    {flush:true,icon:'key',
     sub:'Click any cell to cycle it: full, then scoped, then not permitted. Scoped means the role may act only inside its own boundary.',
     acts:'<div class="row" style="gap:6px">'+PERM_LEVELS.map(l=>l.v===0
        ? '<span class="t-tiny muted">'+SH('dash',10)+' None</span>'
        : '<span class="pill pill-'+l.cls+'">'+SH(l.shape)+esc(l.name)+'</span>').join('')+'</div>'})+
  '</div>';
}

function createRoleDialog(ctx){
  const roles=orgRoles(ctx);
  openModal('<div class="modal-head">'+ICO('shield',18)+'<div class="grow"><h3 class="t-sub">Create a role</h3>'+
    '<div class="t-small muted">Start from nothing, or copy an existing role and adjust it.</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="grid g2">'+
        '<div class="field"><label for="nrName">Role name</label><input class="inp" id="nrName" data-autofocus '+
          'placeholder="e.g. Catalogue auditor">'+
          '<div class="err" id="nrNameErr" hidden>'+ICO('alert',12)+'A role needs a name people will recognise.</div></div>'+
        '<div class="field"><label for="nrScope">Scope</label><input class="inp" id="nrScope" '+
          'placeholder="What this role may see — shown next to the name"></div>'+
      '</div>'+
      '<div class="field"><label for="nrFrom">Start from</label><select class="inp" id="nrFrom">'+
        '<option value="">Nothing — every capability set to none</option>'+
        roles.map(r=>'<option value="'+r.id+'">Copy '+esc(r.name)+'</option>').join('')+'</select>'+
        '<div class="hint">You can change any capability afterwards in the matrix.</div></div>'+
      '<div class="impact"><strong>What a new role does and does not do</strong><ul>'+
        '<li>It is created with nobody in it, so nothing changes until you assign someone.</li>'+
        '<li>It appears as a column in the permission matrix straight away.</li>'+
        '<li>Custom roles can be deleted; built-in ones cannot, because work is routed to them by name.</li></ul></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">Roles are per portal — this one is not visible to other personas.</span>'+
    '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
    '<button class="btn btn-primary" onclick="submitRole(\''+ctx+'\')">Create role</button></div>',
    {wide:true,label:'Create a role'});
}
function submitRole(ctx){
  const g=id=>document.getElementById(id);
  const name=(g('nrName').value||'').trim();
  g('nrNameErr').hidden=!!name; g('nrName').setAttribute('aria-invalid',!name);
  if(!name){ g('nrName').focus(); return; }
  const scope=(g('nrScope').value||'').trim()||'Not yet described';
  const from=g('nrFrom').value;
  closeModal();
  addRole(ctx,{name:name, scope:scope, from:from});
  toast('Role “'+name+'” created — set its permissions in the matrix');
  App.go(App.view);
}
function addRole(ctx,spec){
  logAudit(ctx,'role.created',{object:spec.name, detail:'Scope: '+spec.scope});
  const pfx={operator:'OR-',partner:'PR-',buyer:'BY-',consumer:'CO-'}[ctx]||'RL-';
  SEQ.role=(SEQ.role||0)+1;
  const id=pfx+'C'+SEQ.role;
  const src=spec.from ? orgRoles(ctx).findIndex(r=>r.id===spec.from) : -1;
  const role={id:id, name:spec.name, scope:spec.scope, system:false, perms:[], isNew:true};
  ORG_ROLES[ctx].push(role);
  PERM_GRID[ctx].forEach(row=>{ row.push(src>-1 ? row[src+1] : 0); });
  syncRolePerms(ctx, ORG_ROLES[ctx].length-1);
  return role;
}
function editRoleDialog(ctx,id){
  const r=orgRoles(ctx).find(x=>x.id===id); if(!r) return;
  const n=roleUsers(ctx,id).length;
  confirmAction({
    title:'Edit '+r.name, subtitle:r.id+(r.system?' · built-in':' · custom')+' · '+n+' '+(n===1?'person':'people'),
    risk:'normal', confirmLabel:'Save role',
    body:'<div class="grid g2">'+
      '<div class="field"><label for="erName">Name</label><input class="inp" id="erName" data-autofocus value="'+esc(r.name)+'"></div>'+
      '<div class="field"><label for="erScope">Scope</label><input class="inp" id="erScope" value="'+esc(r.scope)+'"></div></div>'+
      '<div class="t-tiny muted" style="margin-top:10px">Permissions are edited in the matrix, not here — '+
      'that way the grid is always the single source of truth.</div>',
    impact:[
      n ? '<strong>'+n+' '+(n===1?'person holds':'people hold')+' this role.</strong> A rename shows on their profile immediately; permissions are unchanged.'
        : 'Nobody holds this role, so nothing changes for anyone today.',
      r.system ? 'This is a built-in role. Renaming it is cosmetic — the platform still routes work to it by its identifier.'
               : 'This is a custom role, so nothing outside this portal depends on its name.'
    ],
    onConfirm:(vals)=>{
      const nm=((vals||{}).erName||'').trim();
      if(nm) r.name=nm;
      const sc=((vals||{}).erScope||'').trim();
      if(sc) r.scope=sc;
      toast('Role saved');
      App.go(App.view);
    }
  });
}
function cloneRole(ctx,id){
  const r=orgRoles(ctx).find(x=>x.id===id); if(!r) return;
  const copy=addRole(ctx,{name:r.name+' (copy)', scope:r.scope, from:id});
  toast('Cloned as “'+copy.name+'” with the same permissions and nobody assigned');
  App.go(App.view);
}
function deleteRoleDialog(ctx,id){
  const r=orgRoles(ctx).find(x=>x.id===id); if(!r) return;
  const holders=roleUsers(ctx,id);
  if(r.system){ toast('Built-in roles cannot be deleted','warn'); return; }
  if(holders.length){
    openModal('<div class="modal-head">'+ICO('warning',18)+'<div class="grow"><h3 class="t-sub">'+esc(r.name)+' is in use</h3>'+
      '<div class="t-small muted">Move these people to another role first.</div></div>'+
      '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
      '<div class="modal-body stack">'+
        '<table class="tbl"><tbody>'+holders.map(u=>
          '<tr><td class="cellmain">'+esc(u.name)+'</td><td class="cellsub">'+esc(u.email)+'</td></tr>').join('')+'</tbody></table>'+
        '<div class="impact"><strong>Why this is blocked</strong><ul>'+
          '<li>Deleting a role in use would leave '+holders.length+' '+(holders.length===1?'person':'people')+' with no permissions at all.</li>'+
          '<li>Reassign them, then delete the empty role.</li></ul></div>'+
      '</div>'+
      '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Close</button><div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="closeModal();App.go(\''+(cfgUsersView(ctx))+'\')" data-autofocus>Go to the user list</button></div>',
      {label:'Role in use'});
    return;
  }
  confirmAction({
    title:'Delete '+r.name, subtitle:r.id+' · nobody holds it', risk:'normal', confirmLabel:'Delete role',
    impact:['The role and its column disappear from the permission matrix.',
            'Nobody is affected, because nobody holds it.',
            'Any audit entry that records someone acting under it keeps the role name.'],
    onConfirm:()=>{
      const i=ORG_ROLES[ctx].indexOf(r);
      ORG_ROLES[ctx].splice(i,1);
      PERM_GRID[ctx].forEach(row=>row.splice(i+1,1));
      toast(r.name+' deleted');
      App.go(App.view);
    }
  });
}
/* Each portal names its user screen differently. */
function cfgUsersView(ctx){ return {operator:'users',partner:'team',buyer:'users',consumer:'access'}[ctx]||'users'; }

/* ===========================================================================
   PASSWORDS, MFA AND SESSIONS
   =========================================================================== */
function pwdPill(s){
  return s==='strong'?pill('active','Strong'):s==='fair'?pill('degraded','Fair'):pill('overdue','Weak');
}
function securityRows(ctx,me){
  const u = me || orgUsers(ctx).filter(x=>x.you)[0];
  if(!u) return '';
  return '<div class="stack" style="gap:11px">'+
      '<div class="row"><div class="grow"><div class="t-small strong">Password</div>'+
        '<div class="t-tiny muted">'+(u.pwdChanged?'Last changed '+esc(u.pwdChanged):'Never set — you sign in by one-time code')+'</div></div>'+
        (u.pwdChanged?pwdPill(u.pwdStrength):pill('neutral','Not set'))+'</div>'+
      '<div class="row"><div class="grow"><div class="t-small strong">Multi-factor authentication</div>'+
        '<div class="t-tiny muted">'+esc(PWD_POLICY.mfa)+'</div></div>'+
        '<label class="toggle"><input type="checkbox" '+(u.mfa?'checked':'')+
          ' onchange="toggleMfa(\''+ctx+'\',\''+u.id+'\',this.checked)"><span class="track"></span>'+
          '<span class="sr-only">Multi-factor authentication</span></label></div>'+
      '<div class="row"><div class="grow"><div class="t-small strong">Active sessions</div>'+
        '<div class="t-tiny muted">'+(u.sessions||1)+' signed in, including this one</div></div>'+
        '<button class="btn btn-sm" onclick="signOutOthers(\''+ctx+'\',\''+u.id+'\')">Sign out elsewhere</button></div>'+
      '<div class="divider"></div>'+
      '<div class="row"><button class="btn btn-primary" onclick="changePasswordDialog(\''+ctx+'\',\''+u.id+'\')">'+
        ICO('key',14)+'Change my password</button></div>'+
    '</div>';
}
function securityPanel(ctx,me){
  const u = me || orgUsers(ctx).filter(x=>x.you)[0];
  if(!u) return '';
  return panel('Your sign-in and security',
    '<div class="grid g2">'+securityRows(ctx,u)+
    '<div class="stack" style="gap:8px">'+
      '<div class="t-small strong">Password policy</div>'+
      [['Minimum length',PWD_POLICY.minLength+' characters'],
       ['Must include','upper and lower case, a number and a symbol'],
       ['Reuse',PWD_POLICY.reuse],
       ['Expiry',PWD_POLICY.expiry],
       ['Lockout',PWD_POLICY.lockout]].map(r=>
      '<div class="row"><span class="t-small grow">'+esc(r[0])+'</span>'+
      '<span class="t-small strong" style="max-width:60%;text-align:right">'+esc(r[1])+'</span></div>').join('')+
      '<div class="divider"></div>'+
      '<div class="t-tiny muted">Rotation on a schedule is deliberately not required. Forcing regular changes '+
      'pushes people toward weaker, patterned passwords; rotation on suspicion does not.</div>'+
    '</div></div>',
    {icon:'lock'});
}
function changePasswordDialog(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  closeInspector();
  openModal('<div class="modal-head">'+ICO('key',18)+'<div class="grow"><h3 class="t-sub">Change your password</h3>'+
    '<div class="t-small muted">'+esc(u.email)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="field"><label for="cpOld">Current password</label>'+
        '<input class="inp" id="cpOld" type="password" data-autofocus autocomplete="current-password">'+
        '<div class="err" id="cpOldErr" hidden>'+ICO('alert',12)+'Enter your current password.</div></div>'+
      '<div class="field"><label for="cpNew">New password</label>'+
        '<input class="inp" id="cpNew" type="password" autocomplete="new-password" oninput="pwdMeter(this.value)">'+
        '<div id="cpMeter" style="margin-top:7px"></div>'+
        '<div class="err" id="cpNewErr" hidden>'+ICO('alert',12)+'At least '+PWD_POLICY.minLength+
          ' characters with upper and lower case, a number and a symbol.</div></div>'+
      '<div class="field"><label for="cpAgain">Confirm new password</label>'+
        '<input class="inp" id="cpAgain" type="password" autocomplete="new-password">'+
        '<div class="err" id="cpAgainErr" hidden>'+ICO('alert',12)+'The two entries do not match.</div></div>'+
      '<label class="checkline"><input type="checkbox" id="cpOut" checked> Sign out my other sessions</label>'+
      '<div class="impact"><strong>After you change it</strong><ul>'+
        '<li>This session stays signed in; other devices are signed out if you leave the box ticked.</li>'+
        '<li>It cannot match any of your last 5 passwords.</li>'+
        '<li>Nobody at the marketplace can see your password, including support.</li></ul></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">The password is checked against the policy above; it is never shown to anyone, including support.</span>'+
    '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
    '<button class="btn btn-primary" onclick="submitPassword(\''+ctx+'\',\''+id+'\')">Change password</button></div>',
    {wide:true,label:'Change your password'});
}
function pwdScore(v){
  let s=0;
  if(v.length>=PWD_POLICY.minLength) s++;
  if(/[a-z]/.test(v)&&/[A-Z]/.test(v)) s++;
  if(/\d/.test(v)) s++;
  if(/[^A-Za-z0-9]/.test(v)) s++;
  if(v.length>=16) s++;
  return s;
}
function pwdMeter(v){
  const host=document.getElementById('cpMeter'); if(!host) return;
  const s=pwdScore(v);
  const label=v.length===0?'':s<=2?'Weak':s===3?'Fair':s===4?'Strong':'Very strong';
  host.innerHTML = v.length===0 ? '' :
    meter(s/5*100, label)+
    '<div class="t-tiny muted" style="margin-top:4px">'+
    [ v.length>=PWD_POLICY.minLength?null:'needs '+(PWD_POLICY.minLength-v.length)+' more characters',
      (/[a-z]/.test(v)&&/[A-Z]/.test(v))?null:'needs upper and lower case',
      /\d/.test(v)?null:'needs a number',
      /[^A-Za-z0-9]/.test(v)?null:'needs a symbol'
    ].filter(Boolean).join(' · ')+'</div>';
}
function submitPassword(ctx,id){
  const g=x=>document.getElementById(x);
  const oldv=g('cpOld').value||'', nv=g('cpNew').value||'', ag=g('cpAgain').value||'';
  const okOld=oldv.length>0;
  const okNew=nv.length>=PWD_POLICY.minLength && /[a-z]/.test(nv) && /[A-Z]/.test(nv) && /\d/.test(nv) && /[^A-Za-z0-9]/.test(nv);
  const okMatch=okNew && nv===ag;
  g('cpOldErr').hidden=okOld;     g('cpOld').setAttribute('aria-invalid',!okOld);
  g('cpNewErr').hidden=okNew;     g('cpNew').setAttribute('aria-invalid',!okNew);
  g('cpAgainErr').hidden=okMatch; g('cpAgain').setAttribute('aria-invalid',!okMatch);
  if(!okOld||!okNew||!okMatch){ (!okOld?g('cpOld'):!okNew?g('cpNew'):g('cpAgain')).focus(); return; }
  const signOut=g('cpOut').checked;
  closeModal();
  const u=orgUsers(ctx).find(x=>x.id===id);
  if(u){
    logAudit(ctx,'password.changed',{actor:u.name, role:u.role, object:'Own account',
      detail:'Changed by the account holder'+(signOut?'; other sessions signed out':'')});
    if(signOut) logAudit(ctx,'session.revoked',{actor:u.name, role:u.role, object:'Own account',
      detail:(u.sessions>1?(u.sessions-1)+' other session'+(u.sessions>2?'s':'')+' ended':'No other sessions were open')});
    u.pwdChanged=TODAY;
    u.pwdStrength=pwdScore(nv)>=4?'strong':pwdScore(nv)===3?'fair':'weak';
    u.mustReset=false;
    if(signOut) u.sessions=1;
  }
  toast('Password changed'+(signOut?' — other sessions signed out':''));
  App.go(App.view);
}
function resetUserPassword(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  closeInspector();
  confirmAction({
    title:'Send a reset link to '+u.name, subtitle:u.email, risk:'normal',
    confirmLabel:'Send reset link',
    impact:['A single-use link is emailed to <strong>'+esc(u.email)+'</strong> and expires in 60 minutes.',
            'Their current password keeps working until they use the link.',
            'You never see the old or the new password — nobody at the marketplace does.',
            'The reset is recorded against their account with your name.'],
    footNote:'If the address is wrong, fix it before sending — the link goes wherever the address points.',
    onConfirm:()=>{
      u.lastReset=TODAY;
      toast('Reset link sent to '+u.email+' — valid for 60 minutes');
      App.go(App.view);
    }
  });
}
function forceResetUser(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  closeInspector();
  confirmAction({
    title:'Force '+u.name+' to set a new password', subtitle:u.email, risk:'high',
    confirmLabel:'Force a reset', requireType:'RESET',
    impact:['Their current password stops working <strong>immediately</strong>.',
            'Every session they have open is ended.',
            'They must set a new password before they can do anything.',
            'Use this when an account may be compromised, not as routine hygiene.'],
    footNote:'Type RESET to confirm. They will be locked out until they act.',
    onConfirm:()=>{
      logAudit(ctx,'password.reset',{object:u.name+' · '+u.email,
        detail:'Forced reset; current password invalidated and '+u.sessions+' session'+
          (u.sessions===1?'':'s')+' ended', before:'active', after:'reset required'});
      u.mustReset=true; u.sessions=0; u.pwdChanged=null; u.lastReset=TODAY;
      toast(u.name+' must set a new password before their next sign-in','warn');
      App.go(App.view);
    }
  });
}
function toggleMfa(ctx,id,on){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  if(!on){
    confirmAction({
      title:'Turn off multi-factor for '+u.name, subtitle:u.email, risk:'high',
      confirmLabel:'Turn it off', requireType:'OFF',
      impact:['A stolen password alone would then be enough to sign in as them.',
              'Policy requires it for anyone who can approve, pay or manage users.',
              'The change is recorded in the audit trail with your name against it.'],
      footNote:'Type OFF to confirm you accept the weaker position.',
      onConfirm:()=>{
        logAudit(ctx,'mfa.disabled',{object:u.name+' · '+u.email,
          detail:'Disabled with typed confirmation; policy expects MFA for this role',
          before:'on', after:'off'});
        u.mfa=false; toast('Multi-factor turned off for '+u.name,'warn'); App.go(App.view); }
    });
    App.go(App.view);       /* restore the toggle until the dialog is answered */
    return;
  }
  u.mfa=true;
  toast('Multi-factor turned on for '+u.name);
}
function signOutOthers(ctx,id){
  const u=orgUsers(ctx).find(x=>x.id===id); if(!u) return;
  const others=Math.max(0,(u.sessions||1)-1);
  if(!others){ toast('No other sessions are open'); return; }
  u.sessions=1;
  toast(others+' other session'+(others===1?'':'s')+' signed out');
  App.go(App.view);
}

/* ===========================================================================
   SELF-BILLING STATEMENT / INVOICE DETAIL
   The document a partner is actually paid against. It must be readable before
   anyone approves a run, because approval is the last reversible moment.
   =========================================================================== */
function stmDocNo(st){
  const yr = (st.period.match(/\d{4}/)||['2026'])[0];
  const seq = BTMAP[BILL_TEMPLATE_ASSIGN.partner].nextSeq + (SETTLEMENTS.indexOf(st)%97);
  return BTMAP[BILL_TEMPLATE_ASSIGN.partner].numbering
    .replace('{YYYY}',yr).replace('{PARTNER}',st.partnerId.replace('PTR-',''))
    .replace('{SEQ}',String(seq));
}
/* Order lines are grouped by SKU, because that is how a seller reconciles. */
function stmLines(st){
  const own = ORDERS.filter(o=>o.partnerId===st.partnerId);
  const by={};
  own.forEach(o=>{
    const k=o.sku;
    if(!by[k]) by[k]={sku:o.sku,name:o.name,v:o.v,orders:0,units:0,gross:0};
    by[k].orders++; by[k].units += (o.qty||1); by[k].gross += o.gross;
  });
  const lines = Object.keys(by).map(k=>by[k]).sort((a,b)=>b.gross-a.gross);
  /* Scale the lines so they reconcile to the statement gross for its period. */
  const raw = lines.reduce((a,l)=>a+l.gross,0) || 1;
  const k = st.gross / raw;
  lines.forEach(l=>{ l.gross = +(l.gross*k).toFixed(2); });
  /* Push the rounding difference onto the largest line so the total is exact. */
  if(lines.length){
    const diff = +(st.gross - lines.reduce((a,l)=>a+l.gross,0)).toFixed(2);
    lines[0].gross = +(lines[0].gross + diff).toFixed(2);
  }
  return lines;
}
function stmHeld(st){
  return DISPUTES.filter(d=>d.status!=='resolved' && d.partner===st.partner);
}
function openStatement(id){
  const st = SETTLEMENTS.find(x=>x.id===id); if(!st) return;
  const F = BTMAP[BILL_TEMPLATE_ASSIGN.partner];
  const b = PARTNER_BILLING[st.partnerId] || {};
  const lines = stmLines(st);
  const held = stmHeld(st);
  const taxable = +(st.commission + st.fees).toFixed(2);
  const tax = +(taxable*0.18).toFixed(2);

  const money=(label,val,cls)=>'<div class="row"><span class="t-small grow">'+esc(label)+'</span>'+
    '<span class="t-num '+(cls||'')+'">'+val+'</span></div>';

  openInspector(
    '<div class="insp-head">'+ICO('invoice',18)+'<div class="grow">'+
      '<div class="row" style="gap:6px">'+statusPill(st.status)+
        (held.length?pill('overdue','Held — dispute open'):'')+
        (b.override?pill('info','Billing override'):'')+'</div>'+
      '<h3 class="t-sub" style="margin-top:5px">'+esc(F.docTitle)+' · '+esc(st.partner)+'</h3>'+
      '<div class="t-small muted t-num">'+esc(stmDocNo(st))+' · '+esc(st.period)+'</div></div>'+
      '<button class="iconbtn" onclick="closeInspector()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="insp-body stack">'+

      (held.length
        ? banner('warning','<strong>'+held.length+' open dispute'+(held.length===1?'':'s')+' against this partner.</strong> '+
          'This statement is held automatically and rolls into the next run unless the dispute closes first.')
        : '')+

      '<dl class="deflist">'+
        '<dt>Document</dt><dd>'+esc(F.docTitle)+' <span class="t-tiny muted">('+esc(F.template)+')</span></dd>'+
        '<dt>Reference</dt><dd class="t-num">'+esc(stmDocNo(st))+'</dd>'+
        '<dt>Issued by</dt><dd>'+esc(MP.operator)+' on behalf of '+esc(st.partner)+'</dd>'+
        '<dt>Period</dt><dd>'+esc(st.period)+' · '+esc(b.cycle||'Monthly')+', '+esc(b.terms||'net 30')+'</dd>'+
        '<dt>Due</dt><dd>'+esc(st.due)+(st.paidOn?' · paid '+esc(st.paidOn):'')+'</dd>'+
        '<dt>Commission plan</dt><dd>'+esc(st.planName)+' <span class="t-tiny muted">('+esc(st.plan)+')</span></dd>'+
        '<dt>Payment method</dt><dd>'+esc(st.method)+(b.minPayout?' · minimum payout '+CUR(b.minPayout):'')+'</dd>'+
        '<dt>Holdback</dt><dd>'+esc(b.holdback||'None')+'</dd>'+
      '</dl>'+

      '<div class="divider"></div>'+
      '<h4 class="t-sub">What sold — '+lines.length+' lines, '+st.orders+' orders</h4>'+
      '<div class="tablewrap" style="max-height:260px;overflow:auto">'+
        '<table class="tbl"><thead><tr><th>Line</th><th class="num">Orders</th><th class="num">Units</th>'+
        '<th class="num">Gross</th></tr></thead><tbody>'+
        lines.map(l=>'<tr><td><div class="cellmain">'+esc(l.name)+'</div>'+
          '<div class="cellsub t-num">'+esc(l.sku)+' · '+esc(vName(l.v))+'</div></td>'+
          '<td class="num t-num">'+l.orders+'</td>'+
          '<td class="num t-num">'+FMT.num(l.units)+'</td>'+
          '<td class="num t-num">'+CUR(l.gross)+'</td></tr>').join('')+
        '</tbody></table></div>'+

      '<div class="divider"></div>'+
      '<h4 class="t-sub">How it reconciles</h4>'+
      '<div class="stack" style="gap:6px">'+
        money('Gross sales in period', CUR(st.gross),'cellmain')+
        money('Marketplace commission ('+(st.commission/st.gross*100).toFixed(1)+'%)','−'+CUR(st.commission))+
        money('Payment and platform fees','−'+CUR(st.fees))+
        money('Refunds and chargebacks', st.refunds?'−'+CUR(st.refunds):'—')+
        money('Withholding tax', st.wht?'−'+CUR(st.wht):'Not applicable — certificate on file')+
        '<div class="divider" style="margin:4px 0"></div>'+
        money('Net payable to '+st.partner, CUR(st.net),'cellmain')+
      '</div>'+
      splitBar(st.gross, {base: st.commission/st.gross*100})+

      '<div class="divider"></div>'+
      '<h4 class="t-sub">Tax</h4>'+
      '<div class="stack" style="gap:6px">'+
        money(F.taxLabel+' on marketplace services (18% of '+CUR(taxable)+')', CUR(tax))+
        '<div class="t-tiny muted">'+esc(F.taxNote)+'</div>'+
      '</div>'+

      '<div class="divider"></div>'+
      '<div class="t-tiny muted">'+esc(F.remittance)+'<br>'+esc(F.footer)+'</div>'+
    '</div>'+
    '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-sm" onclick="downloadStatementPdf(SETTLEMENTS.filter(function(x){return x.id===\''+st.id+'\'})[0])">'+ICO('download',13)+'Download</button>'+
      (typeof VIEWS!=='undefined' && VIEWS.billing
        ? '<button class="btn btn-sm" onclick="closeInspector();App.go(\'billing\')">'+ICO('settings',13)+'Bill format</button>'
        : '')+
      (st.status==='pending' && typeof approveStatement==='function'
        ? (held.length
            ? '<button class="btn btn-sm btn-primary" disabled title="Held while a dispute is open">Approve</button>'
            : '<button class="btn btn-sm btn-primary" onclick="approveStatement(\''+st.id+'\')">'+ICO('checkcircle',13)+'Approve '+CUR(st.net)+'</button>')
        : '')+
    '</div>', 'Statement '+st.id);
}

/* ===========================================================================
   BILLING CONFIGURATION
   Two things sit here that are usually scattered: how the document is rendered,
   and what cycle each partner is actually billed on. The second one is where
   money goes wrong, so overrides are made loud rather than hidden in a plan.
   =========================================================================== */
/* The document sketch.

   It draws from the template's own section list, so ticking a section changes
   what appears here. It used to draw a fixed set of blocks whatever was
   selected, which made the whole panel a decoration: somebody could switch
   four things off and watch nothing happen. */
function billSketch(F, ctx){
  const has = id => billHas(F, id);
  const yr='2026';
  const no = String(F.numbering||'').replace('{YYYY}',yr).replace('{PARTNER}','1003')
    .replace('{SEQ}',String(F.nextSeq||1));
  const forSeller = ctx==='operator' || F.audience==='partner';
  const lines = forSeller
    ? [['Sentinel MDR Essentials · SKU-6001','128','$41,344.00'],
       ['Sentinel VPN Gateway · SKU-6004','54','$9,126.00']]
    : [['Sentinel MDR Essentials · Cadence Health','40 seats','$12,920.00'],
       ['Nimbus Air Quality sensor · Facilities','120 units','$8,520.00']];
  const party = forSeller ? MP.operator : (typeof BUYER!=='undefined'? BUYER.company : MP.operator);
  const poNeeded = (ctx==='buyer' || F.audience==='enterprise') &&
    (typeof BUYER_TAX!=='undefined' ? BUYER_TAX.poRequired : F.poRequired);

  return '<div class="doc-preview" aria-label="Document preview">'+
    (has('masthead')
      ? '<div class="doc-head">'+
          (F.logo?'<div class="doc-logo">'+esc(party)+'</div>':'')+
          '<div class="doc-title">'+esc(F.docTitle||'Invoice')+'</div>'+
        '</div>'
      : '')+
    (has('parties')
      ? '<div class="doc-meta">'+
          '<span>Reference <strong class="t-num">'+esc(no)+'</strong></span>'+
          '<span>Date <strong>25 Jul 2026</strong></span>'+
          '<span>Currency <strong>'+esc(String(F.currency||'USD').split('—')[0].trim())+'</strong></span>'+
          (poNeeded?'<span>PO <strong class="t-num">'+esc(F.poNumber||'—')+'</strong></span>':'')+
        '</div>'+
        '<div class="doc-line"><span>Billed to <strong>'+
          esc(forSeller ? 'Sentinel Cyber' : party)+'</strong></span><span></span>'+
          '<span class="t-num"></span></div>'
      : '')+
    (has('hero')
      ? '<div class="doc-hero"><span>Amount due</span><strong class="t-num">$47,988.44</strong>'+
        '<span class="t-tiny">by 15 Aug 2026</span></div>'
      : '')+
    (F.showOrderLines===false
      ? '<div class="doc-line"><span>Totals only — line detail suppressed on this template</span>'+
        '<span></span><span></span></div>'
      : (has('subs')
          ? lines.slice(0,1).map(l=>'<div class="doc-line"><span>'+esc(l[0])+'</span>'+
              '<span class="t-num">'+esc(l[1])+'</span><span class="t-num">'+esc(l[2])+'</span></div>').join('')
          : '')+
        (has('usage')
          ? lines.slice(1).map(l=>'<div class="doc-line"><span>'+esc(l[0])+'</span>'+
              '<span class="t-num">'+esc(l[1])+'</span><span class="t-num">'+esc(l[2])+'</span></div>').join('')
          : ''))+
    (has('credits')
      ? '<div class="doc-line"><span>Credits and adjustments</span><span></span>'+
        '<span class="t-num">$0.00</span></div>'
      : '')+
    (has('tax')
      ? '<div class="doc-tot"><span>'+esc(F.taxLabel||'Tax')+'</span>'+
        '<span class="t-num">$1,234.56</span></div>'
      : '')+
    (has('summary')
      ? '<div class="doc-tot grand"><span>'+esc(forSeller?'Net payable to partner':'Total due')+
        '</span><span class="t-num">$47,988.44</span></div>'
      : '')+
    (has('payments')
      ? '<div class="doc-line"><span>Paid this period</span><span></span>'+
        '<span class="t-num">$0.00</span></div>'
      : '')+
    (has('howtopay')
      ? '<div class="doc-block"><strong>How to pay</strong><br>'+
        esc(forSeller?'Paid to the account on your settlement record.'
                     :'Bank transfer or direct debit, quoting '+no+'.')+'</div>'
      : '')+
    (has('support')
      ? '<div class="doc-block"><strong>Questions about this bill</strong><br>'+
        esc((typeof BILL_SUPPORT!=='undefined'? BILL_SUPPORT.phone+' · '+BILL_SUPPORT.hours
                                              : 'Support contact'))+'</div>'
      : '')+
    (has('advert')
      ? '<div class="doc-block is-ad"><strong>One relevant offer</strong><br>'+
        '<span class="t-tiny">Placed here by the template. Never appears on a dunning or final notice.</span>'+
        '</div>'
      : '')+
    (has('terms')
      ? '<div class="doc-block is-terms"><strong>Terms</strong><br>'+
        '<span class="t-tiny">1. Payment is due by the date shown. 2. Queries within 30 days. '+
        '3. Late payment attracts interest at the statutory rate.</span></div>'
      : '')+
    (has('slip')
      ? '<div class="doc-slip"><span class="t-tiny">— — — — detach below this line — — — —</span>'+
        '<div class="row"><span class="grow t-tiny">Payment slip · '+esc(no)+'</span>'+
        '<strong class="t-num">$47,988.44</strong></div></div>'
      : '')+
    '<div class="doc-foot">'+esc(F.remittance||'')+
      (F.footer?'<br>'+esc(F.footer):'')+'</div>'+
  '</div>';
}
function billPreview(ctx){
  const aud = ctx==='operator' ? 'partner' : ctx==='buyer' ? 'enterprise' : 'consumer';
  const F = BTMAP[BILL_TEMPLATE_ASSIGN[aud]] || BILL_TEMPLATES[0];
  return billSketch(F, ctx);
}
function setBillFormat(ctx,key,val){
  /* Writes to the template, not to a parallel settings object. */
  const aud = ctx==='operator' ? 'partner' : ctx==='buyer' ? 'enterprise' : 'consumer';
  const F=BTMAP[BILL_TEMPLATE_ASSIGN[aud]]; if(!F) return;
  F[key] = val;
  if(typeof audit==='function') audit('bill.template',{object:F.name,
    detail:key+' changed on the template '+aud+' bills use'});
  const box=$('#billPreview'); if(box) box.innerHTML = billPreview(ctx);
  const tag=$('#billDirty'); if(tag) tag.hidden=false;
}
function saveBillFormat(ctx){
  const aud = ctx==='operator' ? 'partner' : ctx==='buyer' ? 'enterprise' : 'consumer';
  const F=BTMAP[BILL_TEMPLATE_ASSIGN[aud]]; if(!F) return;
  ['docTitle','numbering','taxLabel','currency','language','accent','remittance','footer'].forEach(k=>{
    const el=$('#bf_'+k); if(el) F[k]=el.value;
  });
  const box=$('#billPreview'); if(box) box.innerHTML = billPreview(ctx);
  const tag=$('#billDirty'); if(tag) tag.hidden=true;
  toast('Document format saved — applies to documents issued from now on');
}
function billFormatPanel(ctx){
  /* One source of truth. This panel edits the template that audience is
     actually assigned, so the numbering pattern here and the sections on the
     template screen can never disagree about the same document. */
  const aud = ctx==='operator' ? 'partner' : ctx==='buyer' ? 'enterprise' : 'consumer';
  const tid = BILL_TEMPLATE_ASSIGN[aud];
  const F = BTMAP[tid];
  if(!F) return '';
  const others = BILL_TEMPLATES.filter(t=>t.audience===aud||t.audience==='any');
  const sel=(id,val,opts,label,hint)=>'<div class="field"><label for="bf_'+id+'">'+esc(label)+'</label>'+
    '<select class="inp" id="bf_'+id+'" onchange="setBillFormat(\''+ctx+'\',\''+id+'\',this.value)">'+
    opts.map(o=>'<option'+(val===o?' selected':'')+'>'+esc(o)+'</option>').join('')+'</select>'+
    (hint?'<div class="hint">'+hint+'</div>':'')+'</div>';
  const txt=(id,val,label,hint)=>'<div class="field"><label for="bf_'+id+'">'+esc(label)+'</label>'+
    '<input class="inp" id="bf_'+id+'" value="'+esc(val==null?'':val)+'" '+
    'onchange="setBillFormat(\''+ctx+'\',\''+id+'\',this.value)">'+
    (hint?'<div class="hint">'+hint+'</div>':'')+'</div>';

  return panel('Bill formatting',
    banner('info','<strong>These settings belong to the template, not to this screen.</strong> You are editing '+
      '<strong>'+esc(F.name)+'</strong>, the template '+esc(aud)+' bills currently use. Change which template '+
      'that is below, and everything here follows it.')+
    '<div class="field" style="max-width:360px"><label for="bf_which">Template in use for '+esc(aud)+' bills</label>'+
      '<select class="inp" id="bf_which" onchange="assignBillTemplate(\''+aud+'\',this.value);App.go(App.view)">'+
      others.map(t=>'<option value="'+t.id+'"'+(t.id===tid?' selected':'')+'>'+esc(t.name)+'</option>').join('')+
      '</select></div>'+
    '<div class="grid g2">'+
      txt('docTitle',F.docTitle,'Document title',
        '"Tax invoice" carries a legal meaning in some jurisdictions. Use it deliberately.')+
      txt('numbering',F.numbering,'Numbering pattern',
        'Tokens: <span class="t-num">{YYYY}</span>, <span class="t-num">{PARTNER}</span>, '+
        '<span class="t-num">{SEQ}</span>. Next sequence is <span class="t-num">'+F.nextSeq+'</span>.')+
      sel('dateFormat',F.dateFormat,['DD MMM YYYY','YYYY-MM-DD','MM/DD/YYYY'],'Date format')+
      txt('currency',F.currency,'Currency')+
      txt('taxLabel',F.taxLabel,'Tax label','What the tax line is called on the face of the document.')+
      sel('rounding',F.rounding,['Half up, 2 decimal places','Half even, 2 decimal places',
        'Truncate, 2 decimal places'],'Rounding')+
      txt('language',F.language,'Language')+
      txt('accent',F.accent,'Accent colour')+
    '</div>'+
    '<div class="field"><label for="bf_remittance">Remittance wording</label>'+
      '<textarea class="inp" id="bf_remittance" rows="2" '+
      'onchange="setBillFormat(\''+ctx+'\',\'remittance\',this.value)">'+esc(F.remittance||'')+'</textarea></div>'+
    '<div class="field"><label for="bf_footer">Footer</label>'+
      '<textarea class="inp" id="bf_footer" rows="2" '+
      'onchange="setBillFormat(\''+ctx+'\',\'footer\',this.value)">'+esc(F.footer||'')+'</textarea></div>'+

    '<div class="divider"></div><h4 class="t-sub">Sections on this template</h4>'+
    '<p class="t-tiny muted">The same list as the template editor, because it is the same template. Four cannot '+
      'be switched off.</p>'+
    '<div class="checkgrid">'+BILL_SECTIONS.map(sec=>
      '<label class="checkline"><input type="checkbox"'+
      (billHas(F,sec.id)?' checked':'')+(sec.locked?' disabled':'')+
      ' onchange="toggleBillSection(\''+F.id+'\',\''+sec.id+'\',this.checked,\''+ctx+'\')">'+
      '<span>'+esc(sec.label)+(sec.locked?' <span class="t-tiny muted">always on</span>':'')+'</span></label>').join('')+
    '</div>'+
    '<div class="divider"></div><h4 class="t-sub">How it comes out</h4>'+
    '<div id="billPreview">'+billPreview(ctx)+'</div>'+
    '<p class="t-tiny muted">A sketch of the document, redrawn as you change a field. '+
      '<strong>Preview a bill</strong> generates the real PDF on this template.</p>'+
    '<div class="rowend">'+
      '<span class="t-tiny" id="billDirty" hidden style="color:var(--nim-warning-fg)">Unsaved</span>'+
      '<button class="btn btn-sm" onclick="previewBillTemplate(\''+F.id+'\')">Preview a bill</button>'+
      '<button class="btn btn-sm" onclick="billTemplateDialog(\''+F.id+'\')">Open the full editor</button>'+
      /* Editing a built-in in place is rarely what somebody wants. Saving the
         current settings as a new named template puts it in the list where it
         can be assigned, without disturbing what other audiences use. */
      '<button class="btn btn-sm btn-primary" onclick="saveAsTemplate(\''+F.id+'\',\''+aud+'\')">'+
        'Save as a template</button>'+
    '</div>',
    {icon:'invoice', sub:F.name+' · '+F.sections.length+' of '+BILL_SECTIONS.length+' sections'});
}
function toggleBillSection(tid,sec,on,ctx){
  const t=BTMAP[tid]; if(!t) return;
  const i=t.sections.indexOf(sec);
  if(on && i===-1) t.sections.push(sec);
  if(!on && i>-1)  t.sections.splice(i,1);
  if(typeof audit==='function') audit('bill.template',{object:t.name,
    detail:(on?'Added ':'Removed ')+sec+' section'});
  /* Redraw the sketch where it stands. Reloading the whole screen threw away
     the scroll position, so the one thing the person was watching moved out
     of view at the moment it changed. */
  const box=$('#billPreview');
  if(box && ctx){ box.innerHTML = billPreview(ctx); const tag=$('#billDirty'); if(tag) tag.hidden=false; }
  else App.go(App.view);
}

function partnerBillingRows(){
  return PARTNERS.filter(p=>p.status==='live'||p.status==='onboarding')
    .map(p=>Object.assign({name:p.name, tier:p.tier, country:p.country, planName:(CPMAP[p.plan]||{}).name||'Unassigned',
      id:p.id}, PARTNER_BILLING[p.id]||{}));
}
function billingCycleView(){
  const rows = partnerBillingRows();
  const over = rows.filter(r=>r.override);
  const nextRun = {Weekly:'31 Jul 2026', Fortnightly:'07 Aug 2026', Monthly:'15 Aug 2026', Quarterly:'30 Sep 2026'};
  return panel('Bill cycle by partner',
    dt('dtPBill',{
      rows:rows, noun:'partners', pageSize:12, sortKey:'name', idKey:'id',
      searchFields:['name','planName','cycle','country'], searchPlaceholder:'Search partner, plan or cycle',
      chips:[{key:'cycle',options:BILL_CYCLES.map(c=>({label:c,value:c}))},
             {key:'override',options:[{label:'Overridden',value:true},{label:'Plan default',value:false}]}],
      actions:exportBtn('Partner billing configuration'),
      columns:[
        {key:'name',label:'Partner',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
          '<div class="cellsub">'+esc(r.planName)+' · '+esc(r.country)+'</div>'},
        {key:'cycle',label:'Cycle',render:r=>'<div class="t-small strong">'+esc(r.cycle)+'</div>'+
          '<div class="cellsub">next '+esc(nextRun[r.cycle]||'—')+'</div>'},
        {key:'terms',label:'Terms',render:r=>'<span class="t-small">'+esc(r.terms)+'</span>'},
        {key:'holdback',label:'Holdback',render:r=>r.holdback==='None'
          ? '<span class="dim">None</span>' : '<span class="t-small">'+esc(r.holdback)+'</span>'},
        {key:'minPayout',label:'Minimum payout',align:'right',render:r=>'<span class="t-num">'+CUR(r.minPayout)+'</span>'},
        {key:'method',label:'Method',render:r=>'<span class="t-small">'+esc(r.method)+'</span>'},
        {key:'selfBill',label:'Self-billing',render:r=>r.selfBill?pill('active','On'):pill('neutral','Partner invoices')},
        {key:'override',label:'Source',render:r=>r.override
          ? '<span class="pill pill-info">'+SH('diamond')+'Override</span>'
          : '<span class="dim">Plan default</span>'},
        {key:'__acts',label:'',sort:false,render:r=>
          '<button class="btn btn-sm btn-quiet" onclick="editPartnerBilling(\''+r.id+'\')">Configure</button>'}
      ]}),
    {flush:true, icon:'clock',
     sub:over.length+' of '+rows.length+' partners are on something other than their plan default. '+
         'Every override below has a stated reason, because an override without one is how a cycle quietly drifts.'});
}
function editPartnerBilling(id){
  const p = PMAP[id]; const b = PARTNER_BILLING[id];
  if(!p||!b) return;
  const plan = CPMAP[p.plan];
  const planCycle = plan ? plan.cycle.split(',')[0].trim() : 'Monthly';
  const planTerms = plan ? (plan.cycle.split(',')[1]||' net 30').trim() : 'net 30';
  const opt=(list,v)=>list.map(o=>'<option'+(v===o?' selected':'')+'>'+esc(o)+'</option>').join('');
  closeInspector();
  openModal('<div class="modal-head">'+ICO('clock',18)+'<div class="grow"><h3 class="t-sub">Bill cycle — '+esc(p.name)+'</h3>'+
    '<div class="t-small muted">'+esc(plan?plan.name:'No commission plan')+' · plan default is '+esc(planCycle)+', '+esc(planTerms)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="grid g2">'+
        '<div class="field"><label for="pbCycle">Cycle</label><select class="inp" id="pbCycle" data-autofocus>'+opt(BILL_CYCLES,b.cycle)+'</select></div>'+
        '<div class="field"><label for="pbTerms">Payment terms</label><select class="inp" id="pbTerms">'+opt(BILL_TERMS,b.terms)+'</select></div>'+
        '<div class="field"><label for="pbHold">Holdback</label><select class="inp" id="pbHold">'+opt(BILL_HOLD,b.holdback)+'</select></div>'+
        '<div class="field"><label for="pbMin">Minimum payout</label>'+
          '<input class="inp" id="pbMin" type="number" min="0" step="10" value="'+b.minPayout+'">'+
          '<div class="hint">Below this, the balance rolls into the next cycle.</div></div>'+
        '<div class="field"><label for="pbMethod">Payment method</label><select class="inp" id="pbMethod">'+
          opt(['NEFT','SEPA','SWIFT','ACH','Local wallet'],b.method)+'</select></div>'+
        '<div class="field"><label for="pbCur">Settlement currency</label><select class="inp" id="pbCur">'+
          opt(['USD','EUR','INR','AED'],b.currency)+'</select></div>'+
      '</div>'+
      '<label class="checkline"><input type="checkbox" id="pbSelf" '+(b.selfBill?'checked':'')+
        '> Marketplace raises the invoice on the partner\'s behalf (self-billing)</label>'+
      '<div class="field"><label for="pbNote">Why this differs from the plan</label>'+
        '<textarea class="inp" id="pbNote" rows="2" placeholder="Required if anything above is not the plan default">'+
        esc(b.note||'')+'</textarea>'+
        '<div class="err" id="pbNoteErr" hidden>'+ICO('alert',12)+
          'An override needs a reason — it is the only record of why this partner is treated differently.</div></div>'+
      banner('info','A cycle change takes effect from the <strong>next</strong> run. The current period is already accruing '+
        'and will settle on the terms it opened under.')+
    '</div>'+
    '<div class="modal-foot">'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      (b.override?'<button class="btn btn-sm" onclick="resetPartnerBilling(\''+id+'\')">Reset to plan default</button>':'')+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="savePartnerBilling(\''+id+'\',\''+esc(planCycle)+'\',\''+esc(planTerms)+'\')">Save</button>'+
    '</div>', 'Bill cycle for '+p.name);
}
function savePartnerBilling(id,planCycle,planTerms){
  const b=PARTNER_BILLING[id]; const p=PMAP[id]; if(!b) return;
  const v=k=>{ const el=$('#'+k); return el ? (el.type==='checkbox'?el.checked:el.value) : null; };
  const next={cycle:v('pbCycle'),terms:v('pbTerms'),holdback:v('pbHold'),
              minPayout:parseFloat(v('pbMin')||'0')||0,method:v('pbMethod'),
              currency:v('pbCur'),selfBill:v('pbSelf'),note:(v('pbNote')||'').trim()};
  const plan = CPMAP[p.plan];
  const isOverride = next.cycle!==planCycle || next.terms!==planTerms ||
                     next.holdback!==(plan?plan.hold:'None') || next.minPayout!==50 || !next.selfBill;
  if(isOverride && !next.note){
    const e=$('#pbNoteErr'); if(e) e.hidden=false;
    const t=$('#pbNote'); if(t){ t.classList.add('inp-bad'); t.focus(); }
    return;
  }
  if(isOverride) audit('billing.override',{object:p.name,
    detail:next.note, before:planCycle+', '+planTerms, after:next.cycle+', '+next.terms});
  Object.assign(b,next,{override:isOverride, note:isOverride?next.note:null});
  closeModal();
  if(typeof App!=='undefined' && App.view) App.go(App.view);
  toast(p.name+' — '+b.cycle.toLowerCase()+', '+b.terms+(isOverride?' (override recorded)':' (back on plan default)'));
}
function resetPartnerBilling(id){
  const b=PARTNER_BILLING[id]; const p=PMAP[id]; if(!b) return;
  const plan=CPMAP[p.plan];
  Object.assign(b,{
    cycle: plan?plan.cycle.split(',')[0].trim():'Monthly',
    terms: plan?(plan.cycle.split(',')[1]||' net 30').trim():'net 30',
    holdback: plan?plan.hold:'None',
    minPayout:50, selfBill:true, override:false, note:null
  });
  closeModal();
  if(typeof App!=='undefined' && App.view) App.go(App.view);
  toast(p.name+' reset to the '+(plan?plan.name:'default')+' cycle');
}

