const MY_PROFILE = {};
function myProfile(ctx){
  const u = orgUsers(ctx).filter(x=>x.you)[0];
  if(!u) return null;
  if(!MY_PROFILE[ctx]){
    MY_PROFILE[ctx] = {
      name:u.name, email:u.email,
      jobTitle:{operator:'Head of marketplace operations',partner:'Seller operations lead',
                buyer:'Procurement manager',consumer:'Account owner'}[ctx]||'',
      phone:'+91 98450 '+(11200+orgUsers(ctx).indexOf(u)*7),
      timezone:'Asia/Kolkata (IST)',
      language:'English',
      dateFormat:'DD MMM YYYY',
      outOfOffice:false,
      delegate:null,
      digest:'Weekly, Monday 08:00'
    };
  }
  return MY_PROFILE[ctx];
}
