function adArt(b, compact){
  const motif = AD_ART[b.art] || AD_ART.twophones;
  const h = compact ? 44 : 58;
  return '<svg class="adartsvg" viewBox="0 0 96 72" height="'+h+'" role="img" '+
    'aria-label="'+esc(b.alt||'Promotional artwork')+'" focusable="false">'+
    '<g fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" '+
    'stroke-linejoin="round">'+motif+'</g></svg>';
}

/* The banner itself. Drawn artwork rather than stock photography, for the same
   honesty rule the rest of the build follows. */
function bannerEl(b,opts){
  opts=opts||{};
  if(!b) return '';
  return '<section class="adbanner'+(opts.compact?' adbanner-sm':'')+'" '+
      'style="--ad-accent:'+esc(b.accent)+'" role="region" aria-label="Promotion: '+esc(b.headline)+'">'+
    '<div class="adart">'+adArt(b, !!opts.compact)+'</div>'+
    '<div class="adbody">'+
      '<div class="adtag">Promotion</div>'+
      '<h3 class="adhead">'+esc(b.headline)+'</h3>'+
      '<p class="adsub">'+esc(b.sub)+'</p>'+
    '</div>'+
    '<div class="adcta">'+
      '<button class="btn btn-primary" onclick="bannerClick(\''+b.id+'\')">'+esc(b.cta)+'</button>'+
      (opts.showWhy!==false
        ? '<button class="linkbtn t-tiny" onclick="bannerWhy(\''+b.id+'\')">Why am I seeing this?</button>'
        : '')+
    '</div>'+
    '<span class="sr-only">'+esc(b.alt)+'</span>'+
  '</section>';
}
function bannerSlot(slot,ctxOpts,opts){
  const b=bnPick(slot,ctxOpts);
  if(!b) return '';
  if(b.impressions!=null) b.impressions++;
  return bannerEl(b,opts);
}
function bannerClick(id){
  const b=BNMAP[id]; if(!b) return;
  if(b.clicks!=null) b.clicks++;
  audit('promo.changed',{object:'Banner '+b.name, detail:'Banner clicked from the storefront', sev:'info'});
  if(b.target && typeof goVertical==='function'){ goVertical(b.target); return; }
  if(b.target && typeof App!=='undefined' && VIEWS[b.target]){ App.go(b.target); return; }
  toast(b.cta+' — '+b.headline);
}
/* Buyers are entitled to know why an ad is in front of them. */
function bannerWhy(id){
  const b=BNMAP[id]; if(!b) return;
  const pre=b.audience==='Signed out only';
  openModal('<div class="modal-head">'+ICO('info',18)+'<div class="grow"><h3 class="t-sub">Why you are seeing this</h3>'+
    '<div class="t-small muted">'+esc(b.name)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<dl class="deflist">'+
        '<dt>Shown to</dt><dd>'+esc(b.audience)+'</dd>'+
        '<dt>Where</dt><dd>'+esc((BANNER_SLOTS.find(s=>s.id===b.slot)||{}).label||b.slot)+'</dd>'+
        '<dt>Running</dt><dd>'+esc(b.from)+' to '+esc(b.to)+'</dd>'+
        (b.locale!=='All'?'<dt>Region</dt><dd>'+esc(b.locale)+'</dd>':'')+
        (b.device!=='All'?'<dt>Device</dt><dd>'+esc(b.device)+'</dd>':'')+
        '<dt>Linked offer</dt><dd>'+(b.promo&&DRMAP[b.promo]
          ? esc(DRMAP[b.promo].name)+' <span class="t-tiny muted">applies automatically at checkout</span>'
          : '<span class="nodata">None — this is an advertisement, not a discount</span>')+'</dd>'+
      '</dl>'+
      banner(pre?'info':'partial', pre
        ? '<strong>Nothing personal was used to choose this.</strong> You are not signed in, so the only things '+
          'known are your language and the kind of device you are on. It is the same banner everyone signed out sees.'
        : '<strong>This was chosen from your account type, not your browsing.</strong> The marketplace does not '+
          'profile what you look at to decide which promotion to show you.')+
      '<div class="t-tiny muted">Promotions can be turned off entirely in your notification preferences.</div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">Advertising here is operator-run. Sellers cannot buy placement.</span>'+
      '<button class="btn btn-primary" onclick="closeModal()">Close</button></div>',
    {label:'Why you are seeing this'});
}

/* ===========================================================================
   INVENTORY ENGINE  (INV-BE-001)
   available = onHand − reserved. Everything the buyer sees derives from that,
   so the storefront cannot promise stock the warehouse does not have.
   =========================================================================== */
function inv(sku){ return INVENTORY[sku]||null; }
function invAvailable(sku){
  const r=inv(sku); if(!r) return null;               /* null = not stocked, not zero */
  return Math.max(0, r.onHand - r.reserved);
}
function invState(sku){
  const r=inv(sku); if(!r) return 'notstocked';
  const a=invAvailable(sku);
  if(a<=0) return r.backorder && r.onOrder ? 'backorder' : 'out';
  if(a<=r.reorderAt) return 'low';
  return 'in';
}
function invPill(sku){
  const st=invState(sku);
  if(st==='notstocked') return '<span class="dim">Not stocked</span>';
  const a=invAvailable(sku);
  return st==='in'   ? pill('active','In stock · '+FMT.num(a))
       : st==='low'  ? pill('degraded','Low · '+FMT.num(a)+' left')
       : st==='backorder' ? pill('pending','On back order')
       : pill('down','Out of stock');
}
/* Buyer-facing wording. Deliberately does not print an exact count when there
   is plenty — an exact number invites a race the buyer will lose. */
function invBuyerLabel(sku){
  const st=invState(sku);
  const r=inv(sku);
  if(st==='notstocked') return null;
  const a=invAvailable(sku);
  if(st==='in')        return {text:'In stock', tone:'ok'};
  if(st==='low')       return {text:'Only '+a+' left', tone:'warn'};
  if(st==='backorder') return {text:'On back order — due '+(r.dueIn||'shortly'), tone:'warn'};
  return {text:'Out of stock', tone:'bad'};
}
/* ---- reservations (INV-BE-001-04) ---- */
function reserveStock(sku,qty,ref,kind){
  const r=inv(sku); if(!r) return {ok:true, held:0, reason:'not stocked'};
  const a=invAvailable(sku);
  if(a<=0) return {ok:false, held:0, reason:'nothing available'};
  const held=Math.min(qty,a);
  r.reserved+=held;
  SEQ.hold=(SEQ.hold||0)+1;
  RESERVATIONS.push({id:'HLD-'+(700+SEQ.hold), sku:sku, qty:held, ref:ref||null,
    kind:kind||'soft', placed:TODAY, expires:HOLD_TTL_MIN+' min', state:'held'});
  return {ok:held===qty, held:held, short:qty-held, reason: held<qty ? 'only '+held+' available' : null};
}
function releaseStock(sku,qty,ref){
  const r=inv(sku); if(!r) return;
  r.reserved=Math.max(0, r.reserved-qty);
  const h=RESERVATIONS.filter(x=>x.sku===sku && x.ref===ref && x.state==='held')[0];
  if(h){ h.state='released'; }
}
/* A hard reservation at payment; the goods leave stock at dispatch, not before. */
function confirmReservation(sku,qty,ref){
  const h=RESERVATIONS.filter(x=>x.sku===sku && x.ref===ref && x.state==='held')[0];
  if(h) h.kind='hard';
  return h||null;
}
function dispatchStock(sku,qty,ref){
  const r=inv(sku); if(!r) return;
  r.onHand=Math.max(0, r.onHand-qty);
  r.reserved=Math.max(0, r.reserved-qty);
  const h=RESERVATIONS.filter(x=>x.sku===sku && x.ref===ref && x.state!=='released')[0];
  if(h) h.state='dispatched';
  addMove(sku,'dispatch',-qty,{ref:ref, by:'Fulfilment automation'});
}
function addMove(sku,kind,qty,opts){
  opts=opts||{};
  const r=inv(sku); if(!r) return null;
  const labels={receipt:'Goods received',dispatch:'Order dispatched',count:'Stock count adjustment',
                return:'Customer return',damage:'Written off — damaged',transfer:'Warehouse transfer'};
  const m={id:'MOV-N'+(SEQ.move=(SEQ.move||0)+1), sku:sku, name:r.name, kind:kind,
           label:labels[kind]||kind, qty:qty, when:TODAY,
           by:opts.by||((typeof orgUsers==='function'&&App.cfg&&App.cfg.orgCtx)
              ? (orgUsers(App.cfg.orgCtx).filter(u=>u.you)[0]||{}).name||'You' : 'You'),
           ref:opts.ref||null, note:opts.note||null, isNew:true};
  STOCK_MOVES.unshift(m);
  return m;
}
/* The single entry point for a stock correction, so every change leaves a trace. */
function adjustStock(sku,delta,kind,note){
  const r=inv(sku); if(!r) return null;
  const before=r.onHand;
  r.onHand=Math.max(0, r.onHand+delta);
  addMove(sku,kind||'count',delta,{note:note});
  audit('order.intervened',{object:r.sku+' '+r.name,
    detail:(labelForKind(kind)||'Stock adjusted')+(note?' · '+note:''),
    before:before+' on hand', after:r.onHand+' on hand'});
  return r;
}
function labelForKind(k){
  return {receipt:'Goods received',count:'Stock count adjustment',return:'Customer return',
          damage:'Written off',transfer:'Warehouse transfer'}[k]||null;
}
function invSummary(filterFn){
  const rows=Object.keys(INVENTORY).map(k=>INVENTORY[k]).filter(filterFn||(()=>true));
  return {
    rows:rows,
    skus:rows.length,
    units:rows.reduce((a,r)=>a+r.onHand,0),
    reserved:rows.reduce((a,r)=>a+r.reserved,0),
    value:+rows.reduce((a,r)=>a+r.onHand*r.unitCost,0).toFixed(2),
    low:rows.filter(r=>invState(r.sku)==='low').length,
    out:rows.filter(r=>invState(r.sku)==='out').length,
    onOrder:rows.filter(r=>r.onOrder>0).length
  };
}

/* --------------------------- inventory console (INV-FE-001) --------------- */
function inventoryView(cfg){
  const own = cfg.partnerId
    ? (r=>r.partnerId===cfg.partnerId)
    : (()=>true);
  const s=invSummary(own);
  const moves=STOCK_MOVES.filter(m=>{ const r=inv(m.sku); return r && own(r); });
  const holds=RESERVATIONS.filter(h=>{ const r=inv(h.sku); return r && own(r) && h.state==='held'; });
  const critical=s.rows.filter(r=>invState(r.sku)==='out' && !r.onOrder);

  return pagehead(cfg.title||'Inventory',
    s.skus+' stocked lines · '+FMT.num(s.units)+' units on hand · '+CUR0(s.value)+' at cost',
    exportBtn('Inventory','dtInv')+
    (cfg.showSim!==false?'<button class="btn" onclick="simPoolDialog()">'+ICO('sim',13)+'SIM pool</button>':'')+
    '<button class="btn btn-primary" onclick="receiveStockDialog(\''+(cfg.partnerId||'')+'\')">'+
      ICO('upload',14)+'Receive stock</button>')+
  '<div class="stack">'+

  (critical.length
    ? banner('danger','<strong>'+critical.length+' line'+(critical.length===1?' is':'s are')+
      ' out of stock with nothing on order.</strong> '+esc(critical[0].name)+' is still listed and still sellable '+
      'in the storefront — availability comes from this ledger, so it now shows as out of stock rather than '+
      'accepting orders you cannot fulfil.')
    : s.low
    ? banner('warning','<strong>'+s.low+' line'+(s.low===1?' is':'s are')+' at or below the reorder point.</strong> '+
      s.onOrder+' already ha'+(s.onOrder===1?'s':'ve')+' a replenishment on the way.')
    : banner('success','<strong>Nothing below its reorder point.</strong> '+FMT.num(s.reserved)+
      ' units are reserved against orders in flight and are not available to sell.'))+

  '<div class="grid g4">'+
    metric({icon:'package',label:'Units on hand',value:FMT.num(s.units),
      foot:s.skus+' stocked lines · '+CUR0(s.value)+' at cost'})+
    metric({icon:'lock',label:'Reserved',value:FMT.num(s.reserved),
      foot:holds.length+' active hold'+(holds.length===1?'':'s')+' · released after '+HOLD_TTL_MIN+' min'})+
    metric({icon:'alert',label:'At or below reorder',value:String(s.low),
      foot:s.out?s.out+' already out of stock':'None out of stock'})+
    metric({icon:'truck',label:'On order',value:String(s.onOrder),
      foot:s.onOrder?'Replenishment inbound':'Nothing inbound'})+
  '</div>'+

  panel('Stock', dt('dtInv',{
    rows:s.rows, noun:'lines', pageSize:12, sortKey:'name', idKey:'sku',
    onRow:"openStock('$SKU')".replace('$SKU','$ID'),
    searchFields:['sku','name','seller','warehouse'], searchPlaceholder:'Search SKU, product or warehouse',
    chips:[{key:'warehouse',options:WAREHOUSES.map(w=>({label:w.name,value:w.id}))}],
    actions:exportBtn('Inventory','dtInv'),
    columns:[
      {key:'name',label:'Line',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.sku)+(cfg.partnerId?'':' · '+esc(r.seller))+'</div>'},
      {key:'warehouse',label:'Held at',render:r=>'<span class="t-small">'+
        esc((WAREHOUSES.find(w=>w.id===r.warehouse)||{}).name||r.warehouse)+'</span>'},
      {key:'onHand',label:'On hand',align:'right',render:r=>'<span class="t-num">'+FMT.num(r.onHand)+'</span>'},
      {key:'reserved',label:'Reserved',align:'right',render:r=>r.reserved
        ? '<span class="t-num">'+FMT.num(r.reserved)+'</span>' : '<span class="dim">—</span>'},
      {key:'__avail',label:'Available',align:'right',sort:false,exp:r=>invAvailable(r.sku),
       render:r=>'<span class="t-num cellmain">'+FMT.num(invAvailable(r.sku))+'</span>'},
      {key:'reorderAt',label:'Reorder at',align:'right',render:r=>'<span class="t-num">'+r.reorderAt+'</span>'},
      {key:'onOrder',label:'Inbound',align:'right',render:r=>r.onOrder
        ? '<div class="t-num">'+FMT.num(r.onOrder)+'</div><div class="cellsub">'+esc(r.dueIn||'')+'</div>'
        : '<span class="dim">—</span>'},
      {key:'__state',label:'State',sort:false,exp:r=>invState(r.sku),render:r=>invPill(r.sku)},
      {key:'__acts',label:'',sort:false,render:r=>
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();adjustStockDialog(\''+r.sku+'\')">Adjust</button>'}
    ]}),
    {flush:true, icon:'package',
     sub:'Available is on hand less what is reserved against orders in flight. That is the number the storefront '+
         'shows, which is why a line can read out of stock while units are physically present.'})+

  (holds.length
    ? panel('Active holds',
        '<div class="tablewrap"><table class="tbl"><thead><tr><th>Line</th><th class="num">Held</th>'+
        '<th>Against</th><th>Kind</th><th>Placed</th></tr></thead><tbody>'+
        holds.map(h=>'<tr><td class="cellmain">'+esc((inv(h.sku)||{}).name||h.sku)+'</td>'+
          '<td class="num t-num">'+h.qty+'</td>'+
          '<td class="t-small">'+esc(h.ref||'a basket')+'</td>'+
          '<td>'+(h.kind==='hard'?pill('active','Paid'):pill('pending','Basket hold'))+'</td>'+
          '<td class="t-small">'+esc(h.placed)+'</td></tr>').join('')+
        '</tbody></table></div>'+
        '<div class="t-tiny muted" style="margin-top:8px">A basket hold expires after '+HOLD_TTL_MIN+
        ' minutes and the units return to available. A paid hold stays until dispatch. Without holds, two buyers '+
        'can pay for the last unit within the same minute.</div>',
        {flush:true, icon:'lock'})
    : '')+

  panel('Movements', dt('dtMoves',{
    rows:moves, noun:'movements', pageSize:10, sortKey:'when', sortDir:'desc', idKey:'id',
    searchFields:['sku','name','label','by','ref'], searchPlaceholder:'Search movement, product or reference',
    chips:[{key:'kind',options:[{label:'Received',value:'receipt'},{label:'Dispatched',value:'dispatch'},
            {label:'Count',value:'count'},{label:'Return',value:'return'},{label:'Written off',value:'damage'}]}],
    actions:exportBtn('Stock movements','dtMoves'),
    columns:[
      {key:'when',label:'When',render:r=>esc(r.when)},
      {key:'name',label:'Line',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.sku)+'</div>'},
      {key:'label',label:'Movement',render:r=>'<span class="t-small">'+esc(r.label)+'</span>'},
      {key:'qty',label:'Units',align:'right',render:r=>'<span class="t-num'+(r.qty<0?'':' cellmain')+'">'+
        (r.qty>0?'+':'')+r.qty+'</span>'},
      {key:'by',label:'By',render:r=>'<span class="t-small">'+esc(r.by)+'</span>'},
      {key:'ref',label:'Reference',render:r=>r.ref?'<span class="t-num t-small">'+esc(r.ref)+'</span>'
        :(r.note?'<span class="t-small muted">'+esc(r.note)+'</span>':'<span class="dim">—</span>')}
    ]}),
    {flush:true, icon:'history',
     sub:'Append-only, like the audit trail. A stock figure nobody can explain is a stock figure nobody trusts.'})+

  (cfg.showPools!==false
    ? panel('Capacity pools',
        '<div class="stack" style="gap:12px">'+RESOURCE_POOLS.map(rp=>{
          const pct=+(rp.allocated/rp.capacity*100).toFixed(1);
          const hot=pct>=rp.alertAt;
          return '<div><div class="row"><span class="t-small strong grow">'+esc(rp.name)+'</span>'+
            '<span class="t-num t-small'+(hot?' cellmain':'')+'">'+FMT.num(rp.allocated)+' of '+
            FMT.num(rp.capacity)+' '+esc(rp.unit)+' · '+pct+'%</span></div>'+
            '<div class="bar" style="margin-top:5px"><span style="width:'+Math.min(100,pct)+'%"></span></div>'+
            (hot?'<div class="t-tiny" style="color:var(--nim-warning-fg);margin-top:4px">'+ICO('alert',11)+
              ' Past the '+rp.alertAt+'% alert point — capacity needs extending before the next large order.</div>':'')+
          '</div>';
        }).join('')+'</div>'+
        '<div class="divider"></div>'+
        '<p class="t-small muted" style="margin:0">Capacity is allocated rather than shipped, so it is inventory '+
        'in every sense that matters: it runs out, it needs a lead time to extend, and selling past it is an '+
        'outage rather than a late delivery.</p>',
        {icon:'gauge'})
    : '')+
  /* Appended inside the stack, not spliced in with a string replace. Replacing
     the first '</div>' put the warehouse panels inside whichever container
     happened to close first, which is why they were rendering at two-thirds
     width in the middle of the page. */
  (cfg.append||'')+
  '</div>';
}
function openStock(sku){
  const r=inv(sku); if(!r) return;
  const p=SKUMAP[sku];
  const moves=STOCK_MOVES.filter(m=>m.sku===sku);
  const holds=RESERVATIONS.filter(h=>h.sku===sku && h.state==='held');
  const a=invAvailable(sku);
  const wh=WAREHOUSES.find(w=>w.id===r.warehouse)||{};
  openInspector(
    '<div class="insp-head">'+ICO('package',18)+'<div class="grow">'+
      '<div class="row" style="gap:6px">'+invPill(sku)+(p?vBadge(p.v):'')+'</div>'+
      '<h3 class="t-sub" style="margin-top:5px">'+esc(r.name)+'</h3>'+
      '<div class="t-small muted t-num">'+esc(r.sku)+' · '+esc(r.seller)+'</div></div>'+
      '<button class="iconbtn" onclick="closeInspector()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="insp-body stack">'+
      '<div class="totals">'+
        '<span class="lbl">On hand</span><span class="val">'+FMT.num(r.onHand)+'</span>'+
        '<span class="lbl">Reserved against orders in flight</span><span class="val">less '+FMT.num(r.reserved)+'</span>'+
        '<span class="grand-lbl">Available to sell</span><span class="val grand">'+FMT.num(a)+'</span>'+
      '</div>'+
      (a<=0 && r.onHand>0
        ? banner('warning','<strong>Physically present but not sellable.</strong> Every unit on hand is reserved '+
          'against an order that has not shipped. The storefront shows this as out of stock, which is correct.')
        : '')+
      '<dl class="deflist">'+
        '<dt>Held at</dt><dd>'+esc(wh.name||r.warehouse)+
          (wh.cutoff?' <span class="t-tiny muted">cut-off '+esc(wh.cutoff)+'</span>':'')+'</dd>'+
        '<dt>Reorder point</dt><dd>'+r.reorderAt+' units</dd>'+
        '<dt>On order</dt><dd>'+(r.onOrder?FMT.num(r.onOrder)+' due '+esc(r.dueIn||'—')
          :'<span class="nodata">Nothing inbound</span>')+'</dd>'+
        '<dt>Back orders</dt><dd>'+(r.backorder?'Accepted — buyers can order beyond stock'
          :'Not accepted — the line goes out of stock')+'</dd>'+
        '<dt>Unit cost</dt><dd>'+(r.unitCost?CUR(r.unitCost):'<span class="nodata">Not set</span>')+'</dd>'+
        '<dt>Value on hand</dt><dd>'+CUR(+(r.onHand*r.unitCost).toFixed(2))+'</dd>'+
        '<dt>Last counted</dt><dd>'+esc(r.lastCount)+'</dd>'+
      '</dl>'+
      (holds.length
        ? '<div class="divider"></div><h4 class="t-sub">What is holding it</h4>'+
          '<table class="tbl"><tbody>'+holds.map(h=>
            '<tr><td class="cellmain">'+esc(h.ref||'A basket')+'</td>'+
            '<td class="num" style="width:64px">'+h.qty+'</td>'+
            '<td style="width:110px">'+(h.kind==='hard'?pill('active','Paid'):pill('pending','Basket'))+'</td>'+
            '</tr>').join('')+'</tbody></table>'
        : '')+
      (moves.length
        ? '<div class="divider"></div><h4 class="t-sub">Recent movements</h4>'+
          '<table class="tbl"><tbody>'+moves.slice(0,6).map(m=>
            '<tr><td><div class="cellmain">'+esc(m.label)+'</div>'+
            '<div class="cellsub">'+esc(m.when)+' · '+esc(m.by)+'</div></td>'+
            '<td class="num t-num" style="width:70px">'+(m.qty>0?'+':'')+m.qty+'</td></tr>').join('')+
          '</tbody></table>'
        : '')+
    '</div>'+
    '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-sm" onclick="closeInspector();adjustStockDialog(\''+sku+'\')">Adjust</button>'+
      '<button class="btn btn-sm btn-primary" onclick="closeInspector();receiveStockDialog(\'\',\''+sku+'\')">Receive</button>'+
    '</div>','Stock '+r.name);
}
function adjustStockDialog(sku){
  const r=inv(sku); if(!r) return;
  closeInspector();
  confirmAction({
    title:'Adjust '+r.name, subtitle:r.onHand+' on hand · '+invAvailable(sku)+' available',
    confirmLabel:'Record the adjustment',
    body:'<div class="grid g2">'+
      '<div class="field"><label for="asKind">Reason</label><select class="inp" id="asKind" data-autofocus>'+
        [['count','Stock count adjustment'],['return','Customer return'],['damage','Written off — damaged'],
         ['transfer','Warehouse transfer']].map(k=>'<option value="'+k[0]+'">'+k[1]+'</option>').join('')+
        '</select></div>'+
      '<div class="field"><label for="asQty">Change in units</label>'+
        '<input class="inp" id="asQty" type="number" value="0" step="1">'+
        '<div class="hint">Negative to reduce. On hand cannot go below zero.</div></div>'+
      '</div>'+
      '<div class="field"><label for="asNote">Note</label>'+
        '<input class="inp" id="asNote" placeholder="What was found, and where">'+
        '<div class="hint">A movement with no explanation is the one that gets queried at year end.</div></div>',
    impact:['The movement is appended to the ledger and cannot be edited afterwards.',
            'Availability on the storefront changes immediately.',
            'Reserved units are untouched — an adjustment does not cancel anyone\'s order.'],
    onConfirm:(v)=>{
      const q=parseInt((v&&v.asQty)||'0',10)||0;
      if(!q){ toast('No change entered','warn'); return; }
      adjustStock(sku,q,(v&&v.asKind)||'count',(v&&v.asNote)||'');
      App.go(App.view);
      toast(r.name+' adjusted by '+(q>0?'+':'')+q+' — now '+r.onHand+' on hand, '+invAvailable(sku)+' available');
    }
  });
}
function receiveStockDialog(partnerId,sku){
  const pool=Object.keys(INVENTORY).map(k=>INVENTORY[k])
    .filter(r=>!partnerId || r.partnerId===partnerId);
  if(!pool.length){ toast('Nothing stocked to receive against','warn'); return; }
  closeInspector();
  openModal('<div class="modal-head">'+ICO('upload',18)+'<div class="grow"><h3 class="t-sub">Receive stock</h3>'+
    '<div class="t-small muted">Goods in. This is the only way units enter the ledger.</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="field"><label for="rsSku">Line</label><select class="inp" id="rsSku" data-autofocus>'+
        pool.map(r=>'<option value="'+r.sku+'"'+(sku===r.sku?' selected':'')+'>'+esc(r.name)+
          ' — '+r.onHand+' on hand</option>').join('')+'</select></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="rsQty">Units received</label>'+
          '<input class="inp" id="rsQty" type="number" min="1" step="1" value="24">'+
          '<div class="err" id="rsQtyErr" hidden>'+ICO('alert',12)+'Receive at least one unit.</div></div>'+
        '<div class="field"><label for="rsRef">Delivery reference</label>'+
          '<input class="inp" id="rsRef" placeholder="Supplier note or PO number"></div>'+
      '</div>'+
      banner('info','Receiving does not clear a back order automatically. Orders waiting on stock are released by '+
        'fulfilment, so somebody sees them before a customer does.')+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">Appended to the ledger; cannot be edited afterwards.</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="submitReceive()">Receive</button></div>',
    {wide:true,label:'Receive stock'});
}
function submitReceive(){
  const g=k=>document.getElementById(k);
  const sku=g('rsSku').value;
  const qty=parseInt(g('rsQty').value,10)||0;
  if(qty<1){ g('rsQtyErr').hidden=false; g('rsQty').focus(); return; }
  const ref=(g('rsRef').value||'').trim();
  const r=inv(sku);
  closeModal();
  r.onHand+=qty;
  if(r.onOrder) r.onOrder=Math.max(0,r.onOrder-qty);
  addMove(sku,'receipt',qty,{ref:ref||null, note:ref?null:'No delivery reference given'});
  audit('order.intervened',{object:r.sku+' '+r.name, detail:'Goods received'+(ref?' · '+ref:''),
    before:(r.onHand-qty)+' on hand', after:r.onHand+' on hand'});
  App.go(App.view);
  toast(qty+' received into '+r.name+' — '+invAvailable(sku)+' now available');
}
function simPoolDialog(){
  const p=SIM_POOL;
  const low=p.available<=p.lowAt;
  openModal('<div class="modal-head">'+ICO('sim',18)+'<div class="grow"><h3 class="t-sub">SIM pool</h3>'+
    '<div class="t-small muted">'+FMT.num(p.total)+' loaded · '+FMT.num(p.available)+' available</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      (low?banner('warning','<strong>Below the '+FMT.num(p.lowAt)+' reorder point.</strong> A bulk IoT order can '+
        'consume several hundred profiles at once, so this needs a batch loading before the next large enterprise deal.')
        :banner('info','A SIM is inventory with a lifecycle rather than a count — available, reserved, activated, '+
        'retired. A retired profile cannot be reissued, so the pool only ever shrinks.'))+
      '<div class="grid g4">'+
        metric({icon:'sim',label:'Available',value:FMT.num(p.available),foot:'Ready to assign'})+
        metric({icon:'lock',label:'Reserved',value:FMT.num(p.reserved),foot:'Held against orders in flight'})+
        metric({icon:'zap',label:'Activated',value:FMT.num(p.activated),foot:'In service'})+
        metric({icon:'ban',label:'Retired',value:FMT.num(p.retired),foot:'Cannot be reissued'})+
      '</div>'+
      '<div class="tablewrap"><table class="tbl"><thead><tr><th>Batch</th><th>Type</th>'+
        '<th>Loaded</th><th class="num">Size</th><th class="num">Available</th><th class="num">Used</th>'+
        '</tr></thead><tbody>'+
      p.batches.map(b=>'<tr><td class="cellmain t-num">'+esc(b.id)+'</td>'+
        '<td><span class="tag">'+esc(b.type)+'</span></td>'+
        '<td class="t-small">'+esc(b.loaded)+'</td>'+
        '<td class="num t-num">'+FMT.num(b.count)+'</td>'+
        '<td class="num t-num cellmain">'+FMT.num(b.available)+'</td>'+
        '<td class="num t-num">'+FMT.num(b.count-b.available)+'</td></tr>').join('')+
      '</tbody></table></div>'+
      '<div class="t-tiny muted">ICCIDs are not listed here. A screen that prints ten thousand identifiers is not '+
      'a management tool, and the identifiers themselves are sensitive.</div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">Batches are loaded from the SIM vendor file.</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Close</button>'+
      '<button class="btn btn-primary" onclick="loadSimBatch()">'+ICO('upload',14)+'Load a batch</button></div>',
    {wide:true,label:'SIM pool'});
}
function loadSimBatch(){
  closeModal();
  confirmAction({
    title:'Load a SIM batch', subtitle:'From the vendor ICCID file',
    confirmLabel:'Load the batch',
    body:'<div class="grid g2">'+
      '<div class="field"><label for="sbType">Type</label><select class="inp" id="sbType" data-autofocus>'+
      '<option>eSIM</option><option>Physical</option></select></div>'+
      '<div class="field"><label for="sbCount">Profiles in the file</label>'+
      '<input class="inp" id="sbCount" type="number" min="100" step="500" value="5000"></div></div>',
    impact:['Profiles are added as available and can be assigned immediately.',
            'Duplicate ICCIDs in the file are rejected rather than merged — a duplicate would activate twice.',
            'The batch is recorded so a faulty vendor file can be traced back to its source.'],
    onConfirm:(v)=>{
      const n=parseInt((v&&v.sbCount)||'0',10)||0;
      if(n<100){ toast('A batch of fewer than 100 is not worth a load','warn'); return; }
      SIM_POOL.batches.unshift({id:'BAT-2026-'+(10+SIM_POOL.batches.length), loaded:TODAY,
        count:n, type:(v&&v.sbType)||'eSIM', available:n});
      SIM_POOL.total+=n; SIM_POOL.available+=n;
      audit('order.intervened',{object:'SIM pool', detail:FMT.num(n)+' profiles loaded',
        before:FMT.num(SIM_POOL.available-n)+' available', after:FMT.num(SIM_POOL.available)+' available'});
      App.go(App.view);
      toast(FMT.num(n)+' profiles loaded — '+FMT.num(SIM_POOL.available)+' now available');
    }
  });
}

/* ===========================================================================
   TICKETING  (SUP-BE-001, SUP-FE-001)
   The SLA clock stops while the ball is in the requester's court. Without
   that, every queue metric becomes a measure of how slowly customers reply.
   =========================================================================== */
function tktPri(p){
  return p==='P1' ? '<span class="pill pill-danger">'+SH('tri')+'P1</span>'
       : p==='P2' ? '<span class="pill pill-warning">'+SH('diamond')+'P2</span>'
       : p==='P3' ? '<span class="pill pill-info">'+SH('dot')+'P3</span>'
       : '<span class="dim">'+SH('dash',10)+' P4</span>';
}
function tktState(s){
  return s==='new'       ? pill('pending','New')
       : s==='open'      ? pill('inprogress','Open')
       : s==='waiting'   ? pill('neutral','Waiting on requester')
       : s==='escalated' ? pill('down','Escalated')
       : s==='resolved'  ? pill('approved','Resolved')
       : pill('inactive','Closed');
}
/* Percentage of the resolution target consumed, counting worked time only. */
function tktBurn(t){
  if(t.state==='resolved'||t.state==='closed') return null;
  return Math.round(t.workedHr/t.resolveTargetHr*100);
}
function tktSlaBar(t){
  const b=tktBurn(t);
  if(b==null) return '<span class="dim">Closed</span>';
  const over=b>100;
  return '<div style="min-width:112px"><div class="bar"><span style="width:'+Math.min(100,b)+'%'+
    (over?';background:var(--nim-danger-fg)':b>75?';background:var(--nim-warning-fg)':'')+'"></span></div>'+
    /* The closing quote on style matters: without it the parser swallows the
       following </td><td> and every column to the right shifts by one. */
    '<div class="t-tiny'+(over?'" style="color:var(--nim-danger-fg)"':' muted"')+'>'+
    (over?'Over by '+(t.workedHr-t.resolveTargetHr)+' h':(t.resolveTargetHr-t.workedHr)+' h left')+'</div></div>';
}
function tktVisible(ctx){
  if(ctx==='operator') return TICKETS.slice();
  return TICKETS.filter(t=>t.ctx===ctx);
}
function ticketsView(cfg){
  const ctx=cfg.ctx;
  const rows=tktVisible(ctx);
  const open=rows.filter(t=>['new','open','waiting','escalated'].indexOf(t.state)>-1);
  const breached=open.filter(t=>t.resolveBreached);
  const waiting=open.filter(t=>t.state==='waiting');
  const unassigned=open.filter(t=>!t.assignee);
  const firstBreached=rows.filter(t=>t.firstBreached).length;

  return pagehead(cfg.title||'Support',
    open.length+' open · '+breached.length+' past target · '+
      (rows.length-open.length)+' closed in the period',
    exportBtn('Tickets','dtTkt')+
    (ctx==='operator'?'<button class="btn" onclick="slaPolicyDialog()">'+ICO('clock',13)+'SLA policy</button>':'')+
    '<button class="btn btn-primary" onclick="newTicketDialog(\''+ctx+'\')">'+ICO('plus',14)+'Raise a ticket</button>')+
  '<div class="stack">'+

  (breached.length
    ? banner('danger','<strong>'+breached.length+' ticket'+(breached.length===1?' is':'s are')+
      ' past the resolution target.</strong> '+esc(breached[0].subject)+' has been escalated automatically — '+
      'nobody had to remember to do it, which is the point of an SLA rather than a promise.')
    : unassigned.length
    ? banner('warning','<strong>'+unassigned.length+' ticket'+(unassigned.length===1?' has':'s have')+
      ' nobody assigned.</strong> The first-response clock is running regardless.')
    : banner('success','<strong>Nothing past target.</strong> '+waiting.length+' ticket'+
      (waiting.length===1?' is':'s are')+' waiting on the requester, with the clock paused.'))+

  '<div class="grid g4">'+
    metric({icon:'support',label:'Open',value:String(open.length),
      foot:unassigned.length?unassigned.length+' unassigned':'All assigned'})+
    metric({icon:'clock',label:'Past resolution target',value:String(breached.length),
      foot:firstBreached?firstBreached+' also missed first response':'First response met on all'})+
    metric({icon:'pause',label:'Waiting on requester',value:String(waiting.length),
      foot:'Clock paused — not counted against us'})+
    metric({icon:'checkcircle',label:'Resolved',value:String(rows.filter(t=>t.state==='resolved'||t.state==='closed').length),
      foot:(function(){
        const done=rows.filter(t=>t.state==='resolved'||t.state==='closed');
        if(!done.length) return 'None yet';
        return 'Median '+Math.round(done.reduce((a,t)=>a+t.workedHr,0)/done.length)+' h worked';
      })()})+
  '</div>'+

  panel('Queue', dt('dtTkt',{
    rows:rows, noun:'tickets', pageSize:12, sortKey:'raised', sortDir:'desc', idKey:'id',
    onRow:"openTicket('$ID')",
    searchFields:['id','subject','raisedBy','org','ref'], searchPlaceholder:'Search ticket, subject or reference',
    chips:[{key:'state',options:TICKET_STATES.map(s=>({label:s.charAt(0).toUpperCase()+s.slice(1),value:s}))},
           {key:'pri',options:TICKET_PRIORITIES.map(p=>({label:p.id,value:p.id}))},
           {key:'cat',options:TICKET_CATEGORIES.map(c=>({label:c.label,value:c.id}))}],
    actions:exportBtn('Tickets','dtTkt'),
    columns:[
      {key:'id',label:'Ticket',render:r=>'<div class="cellmain t-num">'+esc(r.id)+'</div>'+
        '<div class="cellsub">'+esc(r.raised.split(' ').slice(0,3).join(' '))+'</div>'},
      {key:'subject',label:'Subject',render:r=>'<div class="cellmain">'+esc(r.subject)+'</div>'+
        '<div class="cellsub">'+esc((TCATMAP[r.cat]||{}).label||r.cat)+
        (r.ref?' · '+esc(r.ref):'')+'</div>'},
      (ctx==='operator'
        ? {key:'org',label:'From',render:r=>'<div class="t-small">'+esc(r.org)+'</div>'+
            '<div class="cellsub">'+esc(r.raisedBy)+'</div>'}
        : {key:'raisedBy',label:'Raised by',render:r=>'<span class="t-small">'+esc(r.raisedBy)+'</span>'}),
      {key:'pri',label:'Priority',render:r=>tktPri(r.pri)},
      {key:'assignee',label:'With',render:r=>r.assignee
        ? '<span class="t-small">'+esc(r.assignee)+'</span>'
        : '<span class="nodata">Unassigned</span>'},
      {key:'__sla',label:'Resolution SLA',sort:false,exp:r=>tktBurn(r),render:r=>tktSlaBar(r)},
      {key:'state',label:'State',render:r=>tktState(r)}
    ]}),
    {flush:true, icon:'support',
     sub:'Time spent waiting on the requester does not count against the target. Without that, the queue metric '+
         'becomes a measure of how quickly customers reply to us.'})+

  (ctx==='operator'
    ? panel('Where the time goes',
        '<div class="grid g2"><div>'+
          '<div class="tablewrap"><table class="tbl"><thead><tr><th>Category</th><th class="num">Open</th>'+
          '<th class="num">Past target</th><th class="num">Target</th></tr></thead><tbody>'+
          TICKET_CATEGORIES.filter(c=>rows.some(t=>t.cat===c.id)).map(c=>{
            const own=rows.filter(t=>t.cat===c.id);
            const op=own.filter(t=>['new','open','waiting','escalated'].indexOf(t.state)>-1);
            const br=op.filter(t=>t.resolveBreached);
            return '<tr><td><div class="cellmain">'+esc(c.label)+'</div>'+
              '<div class="cellsub">'+esc(c.owner)+'</div></td>'+
              '<td class="num t-num">'+op.length+'</td>'+
              '<td class="num t-num'+(br.length?' cellmain':'')+'">'+(br.length||'—')+'</td>'+
              '<td class="num t-small">'+c.resolveHr+' h</td></tr>';
          }).join('')+'</tbody></table></div>'+
        '</div><div>'+
          '<div class="t-small strong" style="margin-bottom:7px">Escalation ladder</div>'+
          '<div class="stack" style="gap:8px">'+SLA_ESCALATION.map((e,i)=>
            '<div class="row" style="gap:9px"><span class="t-tiny muted" style="width:14px">'+(i+1)+'</span>'+
            '<div class="grow"><div class="t-small strong">'+esc(e.at)+'</div>'+
            '<div class="t-tiny muted">'+esc(e.note)+'</div></div>'+
            '<span class="tag">'+esc(e.to)+'</span></div>').join('')+'</div>'+
          '<div class="t-tiny muted" style="margin-top:9px">Escalation is automatic. A ladder that depends on '+
          'someone noticing is a ladder that works on quiet days only.</div>'+
        '</div></div>',
        {icon:'chart'})
    : '')+
  '</div>';
}

/* --------------------------- ticket detail -------------------------------- */
function openTicket(id){
  const t=TICKETS.find(x=>x.id===id); if(!t) return;
  const c=TCATMAP[t.cat]||{}, p=TPRIMAP[t.pri]||{};
  const ctx=(typeof App!=='undefined'&&App.cfg)?App.cfg.orgCtx:'operator';
  const isAgent = ctx==='operator';
  const burn=tktBurn(t);

  openInspector(
    '<div class="insp-head">'+ICO('support',18)+'<div class="grow">'+
      '<div class="row" style="gap:6px">'+tktState(t.state)+tktPri(t.pri)+
      '<span class="tag">'+esc(c.label||t.cat)+'</span></div>'+
      '<h3 class="t-sub" style="margin-top:5px">'+esc(t.subject)+'</h3>'+
      '<div class="t-small muted t-num">'+esc(t.id)+' · raised '+esc(t.raised)+'</div></div>'+
      '<button class="iconbtn" onclick="closeInspector()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="insp-body stack">'+

      (t.state==='escalated'
        ? banner('danger','<strong>Escalated to '+esc(t.escalatedTo||'the function lead')+'</strong> on '+
          esc(t.escalatedAt||'—')+'. The resolution target passed and the ladder moved it automatically. '+
          'The requester has been told.')
        : t.state==='waiting'
        ? banner('info','<strong>Waiting on the requester.</strong> The SLA clock is paused and this time is not '+
          'counted against the target. It resumes the moment they reply.')
        : t.resolveBreached
        ? banner('warning','<strong>Past the resolution target.</strong> '+t.workedHr+' hours worked against a '+
          t.resolveTargetHr+'-hour target.')
        : '')+

      '<dl class="deflist">'+
        '<dt>Raised by</dt><dd>'+esc(t.raisedBy)+' <span class="t-tiny muted">('+esc(t.org)+')</span></dd>'+
        '<dt>Assigned to</dt><dd>'+(t.assignee?esc(t.assignee):'<span class="nodata">Nobody yet</span>')+'</dd>'+
        '<dt>Category</dt><dd>'+esc(c.label||t.cat)+' <span class="t-tiny muted">owned by '+esc(c.owner||'support')+'</span></dd>'+
        '<dt>Priority</dt><dd>'+esc(p.label||t.pri)+'</dd>'+
        (t.ref?'<dt>Relates to</dt><dd class="t-num">'+esc(t.ref)+'</dd>':'')+
        '<dt>First response</dt><dd>'+(t.firstReplyMin!=null
          ? t.firstReplyMin+' min against a '+t.firstTargetMin+'-min target'+
            (t.firstBreached?' <span style="color:var(--nim-danger-fg)">— missed</span>':' — met')
          : '<span style="color:var(--nim-danger-fg)">Not yet, target '+t.firstTargetMin+' min</span>')+'</dd>'+
        '<dt>Resolution target</dt><dd>'+t.resolveTargetHr+' h · '+t.workedHr+' h worked'+
          (t.waitedHr?' · '+t.waitedHr+' h paused waiting on the requester':'')+'</dd>'+
        (t.resolution?'<dt>Resolution</dt><dd>'+esc(t.resolution)+'</dd>':'')+
      '</dl>'+

      (burn!=null
        ? '<div class="divider"></div><h4 class="t-sub">SLA</h4>'+tktSlaBar(t)+
          '<div class="t-tiny muted" style="margin-top:6px">Worked time only. '+
          (t.waitedHr?t.waitedHr+' hours spent waiting on the requester are excluded.':
           'No time has been spent waiting on the requester.')+'</div>'
        : '')+

      '<div class="divider"></div><h4 class="t-sub">Conversation</h4>'+
      '<div class="stack" style="gap:9px">'+t.thread.map(m=>
        m.side==='system'
          ? '<div class="t-tiny muted" style="text-align:center;padding:3px 0">'+esc(m.text)+' · '+esc(m.when)+'</div>'
          : '<div class="tktmsg tktmsg-'+esc(m.side)+'">'+
            '<div class="row" style="gap:6px"><span class="t-tiny strong">'+esc(m.who)+'</span>'+
            '<span class="t-tiny muted grow">'+esc(m.when)+'</span>'+
            (m.side==='agent'?'<span class="tag">Marketplace</span>':'')+'</div>'+
            '<div class="t-small" style="margin-top:4px;line-height:1.55">'+esc(m.text)+'</div></div>'
      ).join('')+'</div>'+

      (isAgent && t.internal.length
        ? '<div class="divider"></div><h4 class="t-sub">Internal notes</h4>'+
          '<div class="stack" style="gap:8px">'+t.internal.map(n=>
            '<div class="tktmsg tktmsg-internal">'+
            '<div class="row" style="gap:6px"><span class="t-tiny strong">'+esc(n.who)+'</span>'+
            '<span class="t-tiny muted grow">'+esc(n.when)+'</span>'+pill('neutral','Not visible to the requester')+'</div>'+
            '<div class="t-small" style="margin-top:4px;line-height:1.55">'+esc(n.text)+'</div></div>').join('')+
          '</div>'
        : '')+

      (t.state!=='closed'
        ? '<div class="divider"></div>'+
          '<div class="field"><label for="tkReply">Reply</label>'+
            '<textarea class="inp" id="tkReply" rows="3" placeholder="'+
            (isAgent?'Visible to the requester':'Visible to the marketplace')+'"></textarea></div>'+
          (isAgent
            ? '<label class="checkline"><input type="checkbox" id="tkInternal"> Internal note — not sent to the requester</label>'+
              '<label class="checkline"><input type="checkbox" id="tkWait"> Mark as waiting on the requester, pausing the clock</label>'
            : '')
        : '')+
    '</div>'+
    '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
      '<div class="spacer"></div>'+
      (t.state==='closed' ? '<span class="t-tiny muted">Closed tickets are read-only.</span>' :
        (isAgent
          ? (t.state!=='escalated' && t.state!=='resolved'
              ? '<button class="btn btn-sm" onclick="escalateTicket(\''+t.id+'\')">Escalate</button>' : '')+
            (t.state!=='resolved'
              ? '<button class="btn btn-sm" onclick="assignTicket(\''+t.id+'\')">'+(t.assignee?'Reassign':'Assign')+'</button>'+
                '<button class="btn btn-sm" onclick="resolveTicket(\''+t.id+'\')">Resolve</button>' : '')
          : '')+
        '<button class="btn btn-sm btn-primary" onclick="replyTicket(\''+t.id+'\')">Send reply</button>')+
    '</div>','Ticket '+t.id);
}
function replyTicket(id){
  const t=TICKETS.find(x=>x.id===id); if(!t) return;
  const el=$('#tkReply'); const text=el?(el.value||'').trim():'';
  if(text.length<3){ toast('Write a reply before sending','warn'); if(el) el.focus(); return; }
  const ctx=App.cfg.orgCtx;
  const isAgent=ctx==='operator';
  const internal=isAgent && $('#tkInternal') && $('#tkInternal').checked;
  const wait=isAgent && $('#tkWait') && $('#tkWait').checked;
  const me=(typeof orgUsers==='function') ? (orgUsers(ctx).filter(u=>u.you)[0]||{}).name||'You' : 'You';
  const when=TODAY.split(' ').slice(0,2).join(' ')+' '+(CLOCK?CLOCK.hhmm:'now');

  if(internal){
    t.internal.push({who:me, when:when, text:text});
  } else {
    t.thread.push({who:me, side:isAgent?'agent':'requester', when:when, text:text});
    if(t.firstReplyMin==null && isAgent){
      t.firstReplyMin=Math.round(t.workedHr*60);
      t.firstBreached=t.firstReplyMin>t.firstTargetMin;
    }
    if(!isAgent && t.state==='waiting'){
      t.state='open';
      t.thread.push({who:'—', side:'system', when:when, text:'Requester replied — the SLA clock has resumed.'});
    }
    if(isAgent && wait){
      t.state='waiting';
      t.thread.push({who:'—', side:'system', when:when, text:'Waiting on the requester — the SLA clock is paused.'});
    } else if(t.state==='new'){ t.state='open'; }
  }
  closeInspector();
  App.go(App.view);
  toast(internal ? 'Internal note added — the requester will not see it'
                 : 'Reply sent'+(wait?' — clock paused while you wait':''));
}
function assignTicket(id){
  const t=TICKETS.find(x=>x.id===id); if(!t) return;
  const people=orgUsers('operator').filter(u=>u.status==='active');
  closeInspector();
  confirmAction({
    title:(t.assignee?'Reassign ':'Assign ')+t.id, subtitle:t.subject,
    confirmLabel:t.assignee?'Reassign':'Assign',
    body:'<div class="field"><label for="taWho">Assign to</label><select class="inp" id="taWho" data-autofocus>'+
      people.map(u=>'<option value="'+u.id+'"'+(t.assignee===u.name?' selected':'')+'>'+esc(u.name)+
        ' · '+esc((roleById('operator',u.role)||{}).name||u.role)+'</option>').join('')+'</select></div>',
    impact:['They are notified and the ticket appears in their queue.',
            'The SLA clock does not restart — reassignment does not buy time.',
            t.assignee?'The previous assignee is told, so nothing is silently taken off them.'
                      :'The first-response clock has been running since the ticket was raised.'],
    onConfirm:(v)=>{
      const u=people.find(x=>x.id===(v&&v.taWho));
      if(!u) return;
      const from=t.assignee;
      t.assignee=u.name; t.assigneeRole=u.role;
      if(t.state==='new') t.state='open';
      audit('order.intervened',{object:t.id+' '+t.subject,
        detail:'Ticket '+(from?'reassigned':'assigned'), before:from||'unassigned', after:u.name});
      App.go(App.view);
      toast(t.id+' assigned to '+u.name);
    }
  });
}
function escalateTicket(id){
  const t=TICKETS.find(x=>x.id===id); if(!t) return;
  closeInspector();
  confirmAction({
    title:'Escalate '+t.id, subtitle:t.subject, risk:'high', confirmLabel:'Escalate',
    body:'<div class="field"><label for="teTo">Escalate to</label><select class="inp" id="teTo" data-autofocus>'+
      SLA_ESCALATION.map(e=>'<option>'+esc(e.to)+'</option>').join('')+'</select></div>'+
      '<div class="field"><label for="teWhy">Why now</label>'+
      '<textarea class="inp" id="teWhy" rows="2" placeholder="What the next person needs to know"></textarea></div>',
    impact:['The escalation target is notified immediately.',
            '<strong>The requester is told they have been escalated.</strong> An escalation the customer does not know about only helps us.',
            'The SLA clock keeps running — escalation is not a reset.',
            'It stays escalated until resolved, and appears on the daily review.'],
    onConfirm:(v)=>{
      t.state='escalated';
      t.escalatedTo=(v&&v.teTo)||'Team lead';
      t.escalatedAt=TODAY+' '+(CLOCK?CLOCK.hhmm:'');
      t.thread.push({who:'—', side:'system', when:t.escalatedAt,
        text:'Escalated to '+t.escalatedTo+((v&&v.teWhy)?' — '+v.teWhy:'')+'. The requester has been notified.'});
      audit('dispute.resolved',{object:t.id+' '+t.subject,
        detail:'Escalated to '+t.escalatedTo, before:'open', after:'escalated', sev:'high'});
      App.go(App.view);
      toast(t.id+' escalated to '+t.escalatedTo+' — the requester has been told');
    }
  });
}
function resolveTicket(id){
  const t=TICKETS.find(x=>x.id===id); if(!t) return;
  closeInspector();
  confirmAction({
    title:'Resolve '+t.id, subtitle:t.subject, confirmLabel:'Resolve',
    body:'<div class="field"><label for="trWhat">What fixed it</label>'+
      '<textarea class="inp" id="trWhat" rows="3" data-autofocus '+
      'placeholder="The requester sees this, and so does the next person who hits the same problem."></textarea>'+
      '<div class="err" id="trWhatErr" hidden>'+ICO('alert',12)+
        'A resolution with no explanation teaches nobody anything.</div></div>',
    impact:['The requester is notified and can reopen within 14 days.',
            'The resolution text is kept against the ticket and is searchable.',
            t.resolveBreached
              ? '<strong>This ticket missed its target.</strong> Resolving it does not remove the breach from the record.'
              : 'It resolved inside the target.'],
    onConfirm:(v)=>{
      const why=((v&&v.trWhat)||'').trim();
      if(why.length<10){ toast('Say what fixed it — a blank resolution teaches nobody anything','warn'); return; }
      t.state='resolved';
      t.resolution=why;
      t.resolved=TODAY+' '+(CLOCK?CLOCK.hhmm:'');
      t.thread.push({who:'—', side:'system', when:t.resolved, text:'Resolved: '+why});
      audit('dispute.resolved',{object:t.id+' '+t.subject, detail:why, before:'open', after:'resolved'});
      App.go(App.view);
      toast(t.id+' resolved — the requester can reopen it within 14 days');
    }
  });
}
function newTicketDialog(ctx){
  const cats=TICKET_CATEGORIES;
  openModal('<div class="modal-head">'+ICO('support',18)+'<div class="grow"><h3 class="t-sub">Raise a ticket</h3>'+
    '<div class="t-small muted">The category sets the response target, so pick the closest one.</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="field"><label for="ntSubject">Subject</label>'+
        '<input class="inp" id="ntSubject" data-autofocus placeholder="One line — what is wrong">'+
        '<div class="err" id="ntSubjectErr" hidden>'+ICO('alert',12)+'A subject is required.</div></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="ntCat">Category</label>'+
          '<select class="inp" id="ntCat" onchange="ntTargets()">'+
          cats.map(c=>'<option value="'+c.id+'">'+esc(c.label)+'</option>').join('')+'</select></div>'+
        '<div class="field"><label for="ntPri">Priority</label>'+
          '<select class="inp" id="ntPri" onchange="ntTargets()">'+
          TICKET_PRIORITIES.map(p=>'<option value="'+p.id+'"'+(p.id==='P3'?' selected':'')+'>'+
            esc(p.label)+'</option>').join('')+'</select></div>'+
      '</div>'+
      '<div class="hint" id="ntTargetHint"></div>'+
      '<div class="field"><label for="ntBody">What is happening</label>'+
        '<textarea class="inp" id="ntBody" rows="4" '+
        'placeholder="What you did, what happened, and what you expected. A reference number saves a round trip."></textarea>'+
        '<div class="err" id="ntBodyErr" hidden>'+ICO('alert',12)+
          'Describe the problem. A one-word ticket costs a day in back-and-forth.</div></div>'+
      '<div class="field"><label for="ntRef">Reference (optional)</label>'+
        '<input class="inp" id="ntRef" placeholder="Order, statement, listing or endpoint"></div>'+
      banner('info','Priority sets urgency, not importance. <strong>P1 means something is down and cannot be '+
        'worked around.</strong> Raising everything as P1 does not make anything faster — it makes the queue useless.')+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">You can reply and add detail after it is raised.</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="submitTicket(\''+ctx+'\')">Raise it</button></div>',
    {wide:true,label:'Raise a ticket'});
  ntTargets();
}
function ntTargets(){
  const c=TCATMAP[($('#ntCat')||{}).value], p=TPRIMAP[($('#ntPri')||{}).value];
  const h=$('#ntTargetHint'); if(!h||!c||!p) return;
  h.innerHTML='Target: first response in <strong>'+Math.round(c.firstMin*p.mult)+' minutes</strong>, resolution in '+
    '<strong>'+Math.round(c.resolveHr*p.mult)+' hours</strong>. Owned by '+esc(c.owner)+'. '+
    'Time spent waiting on you does not count against it.';
}
function submitTicket(ctx){
  const g=k=>document.getElementById(k);
  const subject=(g('ntSubject').value||'').trim();
  const body=(g('ntBody').value||'').trim();
  const badS=!subject, badB=body.length<12;
  g('ntSubjectErr').hidden=!badS; g('ntBodyErr').hidden=!badB;
  if(badS||badB){ (badS?g('ntSubject'):g('ntBody')).focus(); return; }
  const cat=g('ntCat').value, pri=g('ntPri').value;
  const ref=(g('ntRef').value||'').trim();
  closeModal();
  const t=addTicket(ctx,{subject:subject, body:body, cat:cat, pri:pri, ref:ref});
  App.go(App.view);
  toast(t.id+' raised — first response within '+t.firstTargetMin+' minutes');
}
function addTicket(ctx,spec){
  const c=TCATMAP[spec.cat], p=TPRIMAP[spec.pri];
  const me=(typeof orgUsers==='function') ? (orgUsers(ctx).filter(u=>u.you)[0]||{}) : {};
  const org = ctx==='partner' ? (typeof ME_P!=='undefined'?ME_P.name:'Seller')
            : ctx==='buyer'   ? (typeof BUYER!=='undefined'?BUYER.company:'Buyer')
            : ctx==='consumer'? 'Personal account' : (typeof MP!=='undefined'?MP.operator:'Operator');
  SEQ.ticket=(SEQ.ticket||0)+1;
  const t={
    id:'TKT-N'+SEQ.ticket, ctx:ctx, cat:spec.cat, pri:spec.pri, state:'new',
    subject:spec.subject, raisedBy:me.name||'You', org:org,
    raised:TODAY+' '+(CLOCK?CLOCK.hhmm:''),
    assignee:null, assigneeRole:null,
    ageHr:0, workedHr:0, waitedHr:0, firstReplyMin:null,
    firstTargetMin:Math.round(c.firstMin*p.mult), resolveTargetHr:Math.round(c.resolveHr*p.mult),
    firstBreached:false, resolveBreached:false,
    escalatedTo:null, escalatedAt:null, ref:spec.ref||null,
    thread:[{who:me.name||'You', side:'requester', when:TODAY+' '+(CLOCK?CLOCK.hhmm:''), text:spec.body}],
    internal:[], watchers:[], isNew:true
  };
  TICKETS.unshift(t);
  logAudit(ctx,'dispute.raised',{object:t.id+' '+t.subject,
    detail:(c.label||spec.cat)+' · '+spec.pri+' · target '+t.resolveTargetHr+' h'});
  return t;
}
function slaPolicyDialog(){
  openModal('<div class="modal-head">'+ICO('clock',18)+'<div class="grow"><h3 class="t-sub">SLA policy</h3>'+
    '<div class="t-small muted">Targets by category, multiplied by priority</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>Priority multiplies the category target rather than replacing it.</strong> A P1 billing '+
        'query is still slower than a P1 outage, which is correct — the two are not comparable emergencies.')+
      '<div class="tablewrap"><table class="tbl"><thead><tr><th>Category</th><th>Owned by</th>'+
        TICKET_PRIORITIES.map(p=>'<th class="num">'+p.id+'</th>').join('')+'</tr></thead><tbody>'+
      TICKET_CATEGORIES.map(c=>'<tr><td><div class="cellmain">'+esc(c.label)+'</div>'+
        '<div class="cellsub">first response '+c.firstMin+' min · resolve '+c.resolveHr+' h</div></td>'+
        '<td class="t-small">'+esc(c.owner)+'</td>'+
        TICKET_PRIORITIES.map(p=>'<td class="num t-num">'+Math.round(c.resolveHr*p.mult)+' h</td>').join('')+
        '</tr>').join('')+'</tbody></table></div>'+
      '<div class="impact"><strong>How the clock works</strong><ul>'+
        '<li>It runs from the moment the ticket is raised, assigned or not.</li>'+
        '<li><strong>It pauses while the ticket is waiting on the requester</strong> and resumes when they reply. '+
          'Without that, the metric measures how quickly customers answer us.</li>'+
        '<li>Reassignment does not restart it. Escalation does not restart it.</li>'+
        '<li>Resolving a breached ticket does not remove the breach from the record.</li></ul></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-primary" onclick="closeModal()">Close</button></div>',
    {wide:true,label:'SLA policy'});
}

/* ===========================================================================
   REVIEWS  (CAT-BE-001-08, CAT-FE-001-03)
   =========================================================================== */
function reviewsFor(sku,state){
  return REVIEWS.filter(r=>r.sku===sku && (!state || r.state===state));
}
/* You may review what you bought. The check is against orders, not honour. */
function canReview(sku){
  if(typeof MY_ORDERS==='undefined') return {ok:false, why:'Only buyers can review a listing.'};
  const bought=MY_ORDERS.filter(o=>o.sku===sku);
  if(!bought.length) return {ok:false, why:'You can review this once you have bought it.'};
  const mine=REVIEWS.filter(r=>r.sku===sku && r.author===(typeof SHOPPER!=='undefined'?SHOPPER.name:''));
  if(mine.length) return {ok:false, why:'You have already reviewed this.', existing:mine[0]};
  return {ok:true, order:bought[0]};
}
function starPicker(n){
  let out='<div class="starpick" role="radiogroup" aria-label="Rating out of five">';
  for(let i=1;i<=5;i++){
    out+='<button type="button" role="radio" aria-checked="'+(n===i)+'" aria-label="'+i+' star'+(i===1?'':'s')+'" '+
      'class="starbtn'+(i<=n?' is-on':'')+'" onclick="setReviewStars('+i+')">'+SH(i<=n?'star':'starO',20)+'</button>';
  }
  return out+'<span class="t-small muted" style="margin-left:8px">'+
    (n?['','Poor','Below par','Fine','Good','Excellent'][n]:'Pick a rating')+'</span></div>';
}
let NR = {sku:null, stars:0, title:'', body:''};
function setReviewStars(n){
  NR.stars=n;
  const host=$('#nrStars'); if(host) host.innerHTML=starPicker(n);
}
function writeReviewDialog(sku){
  const p=SKUMAP[sku]; if(!p) return;
  const gate=canReview(sku);
  if(!gate.ok){
    toast(gate.why,'warn');
    return;
  }
  NR={sku:sku, stars:0, title:'', body:''};
  closeInspector();
  openModal('<div class="modal-head">'+ICO('star',18)+'<div class="grow"><h3 class="t-sub">Review '+esc(p.name)+'</h3>'+
    '<div class="t-small muted">Bought '+esc(gate.order.placed)+' · '+esc(gate.order.id)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="field"><label>Your rating</label><div id="nrStars">'+starPicker(0)+'</div>'+
        '<div class="err" id="nrStarsErr" hidden>'+ICO('alert',12)+'Pick a rating from one to five.</div></div>'+
      '<div class="field"><label for="nrTitle">Headline</label>'+
        '<input class="inp" id="nrTitle" maxlength="60" placeholder="Sum it up in a few words" '+
        'oninput="NR.title=this.value">'+
        '<div class="err" id="nrTitleErr" hidden>'+ICO('alert',12)+'A headline is required.</div></div>'+
      '<div class="field"><label for="nrBody">Your review</label>'+
        '<textarea class="inp" id="nrBody" rows="4" oninput="NR.body=this.value" '+
        'placeholder="What you used it for, what worked, what did not."></textarea>'+
        '<div class="hint">At least 20 characters. Say what you actually did with it — that is what helps the '+
        'next buyer.</div>'+
        '<div class="err" id="nrBodyErr" hidden>'+ICO('alert',12)+
          'Write at least a sentence. A one-word review helps nobody.</div></div>'+
      banner('info','<strong>Reviews are checked before they appear.</strong> Not for how positive they are — a '+
        'one-star review that describes a real problem is published. They are checked for personal data, abuse, '+
        'and reviews about something other than the product. '+
        '<strong>Do not include your phone number or address.</strong>')+
      '<div class="t-tiny muted">Published as <strong>'+esc(typeof SHOPPER!=='undefined'?SHOPPER.name:'you')+
        '</strong>, marked as a verified purchase. The seller can reply publicly.</div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">You can edit it for 24 hours after it is published.</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="submitReview()">Submit for checking</button></div>',
    {wide:true,label:'Write a review'});
}
function submitReview(){
  const g=k=>document.getElementById(k);
  const title=(g('nrTitle').value||'').trim();
  const body=(g('nrBody').value||'').trim();
  const badStars=!NR.stars, badTitle=!title, badBody=body.length<20;
  g('nrStarsErr').hidden=!badStars; g('nrTitleErr').hidden=!badTitle; g('nrBodyErr').hidden=!badBody;
  if(badStars||badTitle||badBody) return;
  /* A light check before a human sees it, so the obvious cases are caught. */
  const phone=/(\+?\d[\d\s-]{8,})/.test(body+' '+title);
  closeModal();
  const r=addReview({sku:NR.sku, stars:NR.stars, title:title, body:body, flagged:phone});
  App.go(App.view);
  toast(phone
    ? 'Submitted — it looks like it contains a phone number, so a person will check it before it appears'
    : 'Submitted — it will appear once it has been checked, usually within a day');
}
function addReview(spec){
  SEQ.review=(SEQ.review||0)+1;
  const bought=(typeof MY_ORDERS!=='undefined')?MY_ORDERS.filter(o=>o.sku===spec.sku)[0]:null;
  const r={
    id:'REV-N'+SEQ.review, sku:spec.sku, stars:spec.stars, title:spec.title, body:spec.body,
    author:(typeof SHOPPER!=='undefined'?SHOPPER.name:'A buyer'), when:TODAY, state:'pending',
    response:null, verified:true, orderRef:bought?bought.id:null, helpful:0,
    flagged:!!spec.flagged, moderatedBy:null, moderatedOn:null, rejectReason:null, isNew:true
  };
  REVIEWS.unshift(r);
  audit('listing.queried',{object:spec.sku+' review', detail:spec.stars+' stars · awaiting moderation'});
  return r;
}
/* Rendering ---------------------------------------------------------------- */
function starRow(n,size){
  let st=''; for(let i=1;i<=5;i++) st+=SH(i<=n?'star':'starO',size||11);
  return '<span class="stars" aria-label="'+n+' out of 5">'+st+'</span>';
}
function reviewCard(r,opts){
  opts=opts||{};
  /* Bare drops the border so the card can be nested inside a container that
     already has one. A box inside a box reads as a rendering fault. */
  return '<div class="reviewcard'+(opts.bare?' is-bare':'')+'">'+
    '<div class="row" style="gap:8px">'+starRow(r.stars,12)+
      '<span class="t-small strong grow">'+esc(r.title)+'</span>'+
      (r.verified?pill('active','Verified purchase'):'')+
      (opts.showState&&r.state!=='published'?(r.state==='pending'?pill('pending','Awaiting check'):pill('rejected','Not published')):'')+
    '</div>'+
    '<div class="t-tiny muted" style="margin-top:3px">'+esc(r.author)+' · '+esc(r.when)+'</div>'+
    '<p class="t-small" style="margin:6px 0 0;line-height:1.55">'+esc(r.body)+'</p>'+
    (r.rejectReason?'<div class="t-tiny" style="color:var(--nim-danger-fg);margin-top:5px">Not published — '+
      esc(r.rejectReason)+'</div>':'')+
    (r.response
      ? '<div class="reviewreply"><div class="t-tiny strong">'+esc(r.response.by)+' replied · '+
        esc(r.response.when)+'</div><div class="t-small" style="margin-top:3px;line-height:1.5">'+
        esc(r.response.text)+'</div></div>'
      : '')+
    (opts.canRespond && !r.response && r.state==='published'
      ? '<div class="row" style="margin-top:8px"><button class="btn btn-sm btn-quiet" '+
        'onclick="respondReview(\''+r.id+'\')">Reply publicly</button></div>'
      : '')+
  '</div>';
}
function reviewSummary(sku){
  const p=SKUMAP[sku]||{};
  const pub=reviewsFor(sku,'published');
  const total=p.reviews||pub.length;
  if(!total) return '<div class="t-small nodata">No reviews yet. The first one is usually the most useful.</div>';
  const avg = p.rating!=null ? p.rating
    : +(pub.reduce((a,r)=>a+r.stars,0)/pub.length).toFixed(1);
  const dist=[5,4,3,2,1].map(n=>({n:n, c:pub.filter(r=>r.stars===n).length}));
  const older=Math.max(0,total-pub.length);
  return '<div class="grid g2" style="gap:16px;align-items:center">'+
    '<div style="text-align:center">'+
      '<div style="font-size:30px;font-weight:600;line-height:1">'+avg+'</div>'+
      starRow(Math.round(avg),14)+
      '<div class="t-tiny muted" style="margin-top:4px">'+FMT.num(total)+' review'+(total===1?'':'s')+
      ' · all verified purchases</div>'+
      (older?'<div class="t-tiny muted">'+pub.length+' shown below; '+FMT.num(older)+
        ' older ones are counted but not reproduced here</div>':'')+'</div>'+
    '<div class="stack" style="gap:4px">'+dist.map(d=>
      '<div class="row" style="gap:7px"><span class="t-tiny muted" style="width:10px">'+d.n+'</span>'+
      '<div class="bar grow"><span style="width:'+(pub.length?d.c/pub.length*100:0)+'%"></span></div>'+
      '<span class="t-tiny muted" style="width:18px;text-align:right">'+d.c+'</span></div>').join('')+
      (pub.length?'<div class="t-tiny muted" style="margin-top:4px">Spread of the '+pub.length+
        ' review'+(pub.length===1?'':'s')+' shown below.</div>':'')+
    '</div></div>';
}
function respondReview(id){
  const r=REVIEWS.find(x=>x.id===id); if(!r) return;
  const p=SKUMAP[r.sku];
  closeInspector();
  confirmAction({
    title:'Reply to this review', subtitle:r.stars+' stars · '+r.title,
    confirmLabel:'Post the reply',
    body:'<div class="reviewcard" style="margin-bottom:11px">'+
      '<div class="row" style="gap:8px">'+starRow(r.stars,12)+
      '<span class="t-small strong">'+esc(r.title)+'</span></div>'+
      '<p class="t-small" style="margin:6px 0 0">'+esc(r.body)+'</p></div>'+
      '<div class="field"><label for="rrText">Your reply</label>'+
      '<textarea class="inp" id="rrText" rows="3" data-autofocus '+
      'placeholder="Answer the point. A reply that argues with the customer is read by everyone who comes after."></textarea></div>',
    impact:['Published under your seller name, beneath the review, visible to everyone.',
            'You cannot edit it afterwards, and you cannot delete the review.',
            r.stars<=2
              ? 'A measured reply to a poor review is read as competence. An argumentative one is read by every future buyer.'
              : 'Replying to a good review is optional but it does get noticed.'],
    onConfirm:(v)=>{
      const text=((v&&v.rrText)||'').trim();
      if(text.length<10){ toast('Write a proper reply — a one-line brush-off reads worse than silence','warn'); return; }
      r.response={by:(typeof ME_P!=='undefined'?ME_P.name:(p?p.seller:'Seller')), when:TODAY, text:text};
      App.go(App.view);
      toast('Reply posted beneath the review');
    }
  });
}
/* Moderation (operator) ---------------------------------------------------- */
function moderateReview(id,publish){
  const r=REVIEWS.find(x=>x.id===id); if(!r) return;
  const p=SKUMAP[r.sku];
  closeInspector();
  confirmAction({
    title:(publish?'Publish ':'Reject ')+'this review',
    subtitle:(p?p.name:r.sku)+' · '+r.stars+' stars',
    risk:publish?'normal':'normal', confirmLabel:publish?'Publish it':'Reject it',
    body:'<div class="reviewcard" style="margin-bottom:11px">'+
      '<div class="row" style="gap:8px">'+starRow(r.stars,12)+
      '<span class="t-small strong">'+esc(r.title)+'</span></div>'+
      '<div class="t-tiny muted" style="margin-top:3px">'+esc(r.author)+'</div>'+
      '<p class="t-small" style="margin:6px 0 0">'+esc(r.body)+'</p></div>'+
      (publish ? ''
        : '<div class="field"><label for="mrWhy">Reason</label><select class="inp" id="mrWhy" data-autofocus>'+
          REVIEW_REASONS.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select>'+
          '<div class="hint">The reviewer is told which reason applied.</div></div>'),
    impact:publish
      ? ['It appears on the listing immediately and counts toward the aggregate rating.',
         'A low rating is published like any other — reviews are checked for content, not for sentiment.',
         'The seller can reply publicly but cannot remove it.']
      : ['It does not appear and does not affect the rating.',
         'The reviewer is told, with the reason, and may rewrite it.',
         '<strong>Rejecting for being negative is not a permitted reason</strong> and is itself audited.'],
    onConfirm:(v)=>{
      r.state=publish?'published':'rejected';
      r.moderatedBy=(typeof orgUsers==='function')?(orgUsers('operator').filter(u=>u.you)[0]||{}).name||'You':'You';
      r.moderatedOn=TODAY;
      r.rejectReason=publish?null:((v&&v.mrWhy)||REVIEW_REASONS[0]);
      recomputeRatings();
      audit(publish?'listing.approved':'listing.rejected',
        {object:(p?p.name:r.sku)+' · review '+r.id,
         detail:publish?'Review published':'Review rejected — '+r.rejectReason,
         before:'pending', after:r.state});
      App.go(App.view);
      toast(publish
        ? 'Published — '+(p?p.name:r.sku)+' now rates '+(p?p.rating:'—')
        : 'Rejected — the reviewer has been told why');
    }
  });
}
/* ==========================================================================
   SELLER REVIEWS (M38)
   --------------------------------------------------------------------------
   The seller previously saw a summary panel of invented percentages and a
   button that raised a toast. This reads the real records: what buyers said
   about their listings, what is still awaiting moderation, and which reviews
   are waiting on a reply they have not written.
   ========================================================================== */

function myReviews(pid){
  const skus = PRODUCTS.filter(p=>p.partner===pid).map(p=>p.id);
  return REVIEWS.filter(r=>skus.indexOf(r.sku)>=0);
}
function reviewDist(rows){
  return [5,4,3,2,1].map(n=>({n:n, c:rows.filter(r=>r.stars===n).length}));
}

function sellerReviewsView(pid){
  const all = myReviews(pid);
  const pub = all.filter(r=>r.state==='published');
  const pend = all.filter(r=>r.state==='pending');
  const rej = all.filter(r=>r.state==='rejected');
  const low = pub.filter(r=>r.stars<=2);
  const unanswered = low.filter(r=>!r.response);
  const avg = pub.length ? +(pub.reduce((a,r)=>a+r.stars,0)/pub.length).toFixed(1) : null;
  const dist = reviewDist(pub);
  const max = Math.max.apply(null, dist.map(d=>d.c).concat([1]));

  return pagehead('Reviews',
    pub.length? pub.length+' published across your listings'+
      (avg!=null?' · averaging '+avg.toFixed(1)+' out of 5':'')
      : 'Nothing published yet',
    exportBtn('Reviews','dtRev'))+
  '<div class="stack">'+

  (unanswered.length
    ? banner('warning','<strong>'+unanswered.length+' review'+(unanswered.length===1?'':'s')+
      ' at two stars or below '+(unanswered.length===1?'has':'have')+' no reply.</strong> '+
      'A measured answer is read by every buyer who comes after, and it is the only part of a bad review '+
      'you control. An argument is read by them too.')
    : low.length
    ? banner('success','<strong>Every poor review has been answered.</strong> That is more visible to a '+
      'prospective buyer than the rating itself.')
    : banner('info','<strong>Reviews are verified purchases only</strong> and are checked for content, '+
      'never for sentiment. A low rating is published like any other, and you cannot have one removed — '+
      'you can reply to it.'))+

  '<div class="grid g4">'+
    metric({icon:'star', label:'Average rating',
      value: avg!=null? avg.toFixed(1) : 'Not measured',
      foot: pub.length? pub.length+' published review'+(pub.length===1?'':'s') : 'No published reviews yet'})+
    metric({icon:'thumbsup', label:'Four stars and above',
      value: pub.length? Math.round(pub.filter(r=>r.stars>=4).length/pub.length*100)+'%' : 'Not measured',
      foot: pub.length? pub.filter(r=>r.stars>=4).length+' of '+pub.length : 'Nothing to measure yet'})+
    metric({icon:'message', label:'Replied to',
      value: pub.length? String(pub.filter(r=>r.response).length) : '0',
      foot: unanswered.length? unanswered.length+' poor review'+(unanswered.length===1?'':'s')+' still open'
          : 'Nothing outstanding'})+
    metric({icon:'clock', label:'Awaiting moderation',
      value: String(pend.length),
      foot: pend.length? 'With the marketplace, not with you' : 'None in the queue'})+
  '</div>'+

  panel('How the ratings fall',
    (pub.length
      ? '<div class="stack" style="gap:7px">'+dist.map(d=>
          '<div class="revbar">'+
            '<span class="revbar-n">'+d.n+'</span>'+SH('star',11)+
            '<div class="bar grow"><span style="width:'+(d.c/max*100).toFixed(1)+'%"></span></div>'+
            '<span class="revbar-c t-num">'+d.c+'</span>'+
          '</div>').join('')+'</div>'+
        '<p class="t-small muted" style="margin-top:9px">Bars are relative to your most common rating, not to '+
        'a hundred, so a small number of reviews does not read as a wall of nothing.</p>'
      : '<div class="t-small nodata">No published reviews yet. The first one is usually the most useful, '+
        'and it usually arrives after a fulfilment that went well.</div>'),
    {icon:'chart', sub: pub.length? 'Across '+new Set(pub.map(r=>r.sku)).size+' listings' : 'Nothing to plot yet'})+

  panel('By listing',
    '<div class="tablewrap"><table class="tbl"><thead><tr><th style="min-width:200px">Listing</th>'+
      '<th class="num">Rating</th><th class="num">Published</th><th class="num">Poor</th>'+
      '<th class="num">Unanswered</th><th>Where it stands</th></tr></thead><tbody>'+
    (function(){
      const skus=Array.from(new Set(all.map(r=>r.sku)));
      if(!skus.length) return '<tr><td colspan="6" class="t-small muted">No listing has a review yet.</td></tr>';
      return skus.map(sku=>{
        const p=SKUMAP[sku]||{name:sku};
        const rs=all.filter(r=>r.sku===sku), rp=rs.filter(r=>r.state==='published');
        const bad=rp.filter(r=>r.stars<=2), open=bad.filter(r=>!r.response);
        const a=rp.length? +(rp.reduce((x,r)=>x+r.stars,0)/rp.length).toFixed(1) : null;
        return '<tr onclick="openProduct(\''+sku+'\',{mode:\'seller\'})" style="cursor:pointer">'+
          '<td><div class="cellmain">'+esc(p.name)+'</div>'+
            '<div class="cellsub t-num">'+esc(sku)+'</div></td>'+
          '<td class="num t-num">'+(a!=null? a.toFixed(1) : '<span class="dim">Not measured</span>')+'</td>'+
          '<td class="num t-num">'+rp.length+'</td>'+
          '<td class="num t-num">'+(bad.length||'<span class="dim">None</span>')+'</td>'+
          '<td class="num t-num'+(open.length?' cellmain':'')+'">'+
            (open.length||'<span class="dim">None</span>')+'</td>'+
          '<td>'+(open.length? pill('warn','Reply outstanding')
                 : bad.length? pill('ok','All answered')
                 : rp.length? pill('ok','Nothing to answer') : pill('','Awaiting moderation'))+'</td>'+
        '</tr>';
      }).join('');
    })()+
    '</tbody></table></div>',
    {flush:true, icon:'checklist',
     sub:'A listing with an outstanding reply is losing sales it will never see reported'})+

  panel('What buyers said',
    (all.length
      ? '<div class="stack" style="gap:11px">'+
        all.slice().sort((a,b)=>{
          /* Unanswered poor reviews first: they are the ones costing money. */
          const wa=(a.state==='published'&&a.stars<=2&&!a.response)?0:1;
          const wb=(b.state==='published'&&b.stars<=2&&!b.response)?0:1;
          return wa-wb || b.stars-a.stars;
        }).slice(0,12).map(r=>{
          const p=SKUMAP[r.sku]||{name:r.sku};
          return '<div>'+
            '<div class="t-tiny muted" style="margin-bottom:4px">'+esc(p.name)+'</div>'+
            reviewCard(r,{canRespond:true, showState:true})+
          '</div>';
        }).join('')+'</div>'+
        (all.length>12? '<p class="t-tiny muted" style="margin-top:9px">Showing the twelve that most need '+
          'your attention, of '+all.length+'.</p>' : '')
      : '<div class="t-small nodata">Nothing yet.</div>'),
    {icon:'message',
     sub: pend.length? pend.length+' awaiting the marketplace’s check — you cannot reply until they clear'
        : 'Replies are public, permanent, and posted under your seller name'})+

  (rej.length? panel('Not published',
    banner('info','<strong>These were rejected by the marketplace for content, never for being critical.</strong> '+
      'Rejecting a review for being negative is not a permitted reason and is itself audited.')+
    '<div class="tablewrap"><table class="tbl"><thead><tr><th>Listing</th><th class="num">Stars</th>'+
      '<th>Reason</th><th>When</th></tr></thead><tbody>'+
    rej.map(r=>'<tr><td class="t-small">'+esc((SKUMAP[r.sku]||{name:r.sku}).name)+'</td>'+
      '<td class="num t-num">'+r.stars+'</td>'+
      '<td class="t-small">'+esc(r.rejectReason||'—')+'</td>'+
      '<td class="t-small">'+esc(r.moderatedOn||r.when)+'</td></tr>').join('')+
    '</tbody></table></div>', {icon:'ban', sub:rej.length+' rejected'}) : '')+
  '</div>';
}

/* ==========================================================================
   49. THE REVIEWER'S OWN REVIEWS (M40)
   --------------------------------------------------------------------------
   The operator moderates, the seller replies, and until now the person who
   wrote the thing could not see any of it. The moderation flow tells a
   reviewer their review was rejected and that they may rewrite it — this is
   where they are told, and where they rewrite it.
   ========================================================================== */

function myAuthoredReviews(who){
  return REVIEWS.filter(r=>r.author===who);
}
function myReviewablePurchases(who){
  /* Something they bought, that they have not already reviewed. A review with
     no purchase behind it is the thing verification exists to prevent. */
  const done={}; myAuthoredReviews(who).forEach(r=>done[r.sku]=1);
  const src=(typeof MY_ORDERS!=='undefined'&&MY_ORDERS.length)?MY_ORDERS:ORDERS.filter(o=>o.buyer===who);
  const seen={};
  return src.filter(o=>{
    if(done[o.sku]||seen[o.sku]) return false;
    seen[o.sku]=1; return !!SKUMAP[o.sku];
  });
}

function myReviewsPanel(who){
  const mine=myAuthoredReviews(who);
  const rej=mine.filter(r=>r.state==='rejected');
  const pend=mine.filter(r=>r.state==='pending');
  const replied=mine.filter(r=>r.response);
  const todo=myReviewablePurchases(who);

  return panel('Reviews you have written',
    (rej.length
      ? banner('warning','<strong>'+rej.length+' of your reviews '+(rej.length===1?'was':'were')+
        ' not published.</strong> The reason is below each one. Being critical is never a reason \\u2014 '+
        'if that is what happened, say so and it will be looked at again.')
      : pend.length
      ? banner('info','<strong>'+pend.length+' waiting to be checked.</strong> Reviews are read for content '+
        'before they appear, usually within a working day. A low rating is published like any other.')
      : replied.length
      ? banner('info','<strong>A seller has replied to '+replied.length+' of your reviews.</strong> '+
        'Their reply appears underneath yours, publicly.')
      : '')+

    (mine.length
      ? '<div class="stack" style="gap:11px">'+mine.map(r=>{
          const p=SKUMAP[r.sku]||{name:r.sku};
          return '<div>'+
            '<div class="t-tiny muted" style="margin-bottom:4px">'+esc(p.name)+'</div>'+
            reviewCard(r,{showState:true})+
            (r.state==='rejected'
              ? '<div class="row" style="gap:7px;margin-top:6px">'+
                '<button class="btn btn-sm" onclick="rewriteReview(\''+r.id+'\')">Rewrite it</button>'+
                '<button class="btn btn-sm btn-quiet" onclick="challengeRejection(\''+r.id+'\')">'+
                  'This was not the reason</button></div>'
              : r.state==='published'
              ? '<div class="row" style="gap:7px;margin-top:6px">'+
                '<button class="btn btn-sm btn-quiet" onclick="withdrawReview(\''+r.id+'\')">Take it down</button>'+
                '</div>'
              : '')+
          '</div>';
        }).join('')+'</div>'
      : '<div class="t-small nodata">You have not written one yet. They are the most useful thing a buyer '+
        'reads, and they only come from people who actually bought the thing.</div>')+

    (todo.length
      ? '<div class="divider"></div>'+
        '<h4 class="t-sub" style="margin-bottom:7px">Things you could review</h4>'+
        '<div class="stack" style="gap:6px">'+todo.slice(0,4).map(o=>{
          const p=SKUMAP[o.sku];
          return '<div class="row" style="gap:9px">'+
            '<span class="grow"><span class="t-small">'+esc(p.name)+'</span>'+
            '<span class="cellsub">'+esc(p.seller)+' \\u00b7 ordered '+esc(o.placed||o.when||'')+'</span></span>'+
            '<button class="btn btn-sm" onclick="writeReviewDialog(\''+p.id+'\')">Write one</button></div>';
        }).join('')+'</div>'
      : '')+

    '<p class="t-tiny muted" style="margin-top:10px">Only somebody who bought it can review it, which is why '+
      'every review carries a verified-purchase mark. A seller can reply to yours; they cannot remove it, and '+
      'nor can we for being unflattering.</p>',
    {icon:'star',
     sub: mine.length? mine.filter(r=>r.state==='published').length+' published \\u00b7 '+
            pend.length+' being checked'+(rej.length?' \\u00b7 '+rej.length+' not published':'')
        : 'Nothing written yet'});
}

function rewriteReview(id){
  const r=REVIEWS.filter(x=>x.id===id)[0]; if(!r) return;
  confirmAction({
    title:'Rewrite this review', subtitle:esc(r.rejectReason||'Not published'),
    confirmLabel:'Send it again',
    body:banner('info','<strong>It was not published because: '+esc(r.rejectReason||'no reason recorded')+
      '.</strong> Change what caused that and it goes back for a check. The rating itself is never the problem.')+
      '<div class="field"><label for="rwTitle">Headline</label>'+
      '<input class="inp" id="rwTitle" value="'+esc(r.title)+'" data-autofocus></div>'+
      '<div class="field"><label for="rwBody">Your review</label>'+
      '<textarea class="inp" id="rwBody" rows="4">'+esc(r.body)+'</textarea></div>',
    impact:['It goes back into the queue as a new submission',
            'Your star rating is unchanged unless you change it',
            'If it is rejected again the reason will say what is still wrong'],
    onConfirm:(v)=>{
      const t=((v&&v.rwTitle)||'').trim(), b=((v&&v.rwBody)||'').trim();
      if(b.length<15){ toast('Say a little more \\u2014 a one-line review helps nobody','warn'); return; }
      r.title=t||r.title; r.body=b;
      r.state='pending'; r.rejectReason=null; r.moderatedBy=null; r.moderatedOn=null;
      r.when=TODAY; r.isNew=true;
      toast('Sent for a check again');
      App.go(App.view);
    }
  });
}

function challengeRejection(id){
  const r=REVIEWS.filter(x=>x.id===id)[0]; if(!r) return;
  confirmAction({
    title:'Challenge this decision', subtitle:esc(r.rejectReason||'Not published'),
    confirmLabel:'Send the challenge',
    body:banner('info','<strong>Rejecting a review for being negative is not a permitted reason, and doing it '+
      'is itself recorded.</strong> If you think that is what happened, this goes to somebody who did not make '+
      'the original decision.')+
      '<div class="field"><label for="chWhy">What you think happened</label>'+
      '<textarea class="inp" id="chWhy" rows="3" data-autofocus></textarea></div>',
    impact:['It is reviewed by somebody other than the original moderator',
            'The original decision and its reason stay on the record either way',
            'You will be told the outcome whichever way it goes'],
    onConfirm:(v)=>{
      const why=((v&&v.chWhy)||'').trim();
      if(!why){ toast('Say what you think happened','warn'); return; }
      r.challenge={when:TODAY, text:why};
      r.state='pending'; r.rejectReason=null;
      if(typeof audit==='function') audit('listing.queried',{object:'Review '+r.id,
        detail:'Reviewer challenged the rejection', sev:'warn'});
      toast('Sent \\u2014 somebody else will look at it');
      App.go(App.view);
    }
  });
}

function withdrawReview(id){
  const r=REVIEWS.filter(x=>x.id===id)[0]; if(!r) return;
  confirmAction({
    title:'Take down your review?', subtitle:r.stars+' stars \\u00b7 '+esc(r.title),
    risk:'high', confirmLabel:'Take it down',
    body:banner('warning','<strong>It stops counting towards the rating.</strong> '+
      (r.response? 'The seller has replied to it; their reply comes down with it.' : '')),
    impact:['It disappears from the listing and from the average',
            'You can write a new one for the same purchase afterwards',
            r.response?'The seller’s public reply is removed too':'No seller reply is affected'],
    onConfirm:()=>{
      const i=REVIEWS.indexOf(r); if(i>-1) REVIEWS.splice(i,1);
      if(typeof recomputeRatings==='function') recomputeRatings();
      toast('Taken down');
      App.go(App.view);
    }
  });
}

function reviewQueueView(){
  const pending=REVIEWS.filter(r=>r.state==='pending');
  const flagged=pending.filter(r=>r.flagged);
  const pub=REVIEWS.filter(r=>r.state==='published');
  const rej=REVIEWS.filter(r=>r.state==='rejected');
  return pagehead('Reviews',
    pending.length+' awaiting a check · '+pub.length+' published · '+rej.length+' rejected',
    exportBtn('Reviews','dtRev'))+
  '<div class="stack">'+
  (flagged.length
    ? banner('warning','<strong>'+flagged.length+' review'+(flagged.length===1?'':'s')+
      ' tripped an automated check.</strong> Usually a phone number or a competitor mention. The check is a prompt '+
      'for a person, not a decision.')
    : banner('info','<strong>Reviews are checked for content, not for sentiment.</strong> A one-star review that '+
      'describes a real problem is published. Rejecting a review for being negative is not a permitted reason, and '+
      'the rejection reason is recorded against the moderator.'))+
  '<div class="grid g4">'+
    metric({icon:'inbox',label:'Awaiting a check',value:String(pending.length),
      foot:flagged.length?flagged.length+' auto-flagged':'None flagged'})+
    metric({icon:'star',label:'Published',value:String(pub.length),
      foot:'Average '+(pub.length?(pub.reduce((a,r)=>a+r.stars,0)/pub.length).toFixed(1):'—')+' stars'})+
    metric({icon:'ban',label:'Rejected',value:String(rej.length),
      foot:rej.length?'Each with a recorded reason':'None rejected'})+
    metric({icon:'message',label:'Seller replies',value:String(REVIEWS.filter(r=>r.response).length),
      foot:'Sellers can reply but cannot remove'})+
  '</div>'+
  (pending.length
    ? panel('Awaiting a check',
        /* One bordered unit per review: what it is about, the review itself,
           and the two decisions — so the buttons are visibly attached to the
           thing they act on rather than floating after it. */
        '<div class="stack" style="gap:10px">'+pending.map(r=>{
          const p=SKUMAP[r.sku];
          return '<article class="modcard'+(r.flagged?' is-flagged':'')+'">'+
            '<header class="modcard-head">'+
              (p?vBadge(p.v):'')+
              '<span class="t-small strong grow">'+esc(p?p.name:r.sku)+'</span>'+
              (r.flagged?pill('overdue','Auto-flagged'):'')+
            '</header>'+
            '<div class="modcard-body">'+reviewCard(r,{bare:true})+'</div>'+
            '<footer class="modcard-foot">'+
              '<span class="t-tiny muted grow">'+
                (r.flagged
                  ? 'An automated check flagged this. It is a prompt for a person, not a decision.'
                  : 'Checked for content, never for sentiment.')+'</span>'+
              '<button class="btn btn-sm btn-danger" onclick="moderateReview(\''+r.id+'\',false)">Reject</button>'+
              '<button class="btn btn-sm btn-primary" onclick="moderateReview(\''+r.id+'\',true)">Publish</button>'+
            '</footer>'+
          '</article>';
        }).join('')+'</div>',
        {icon:'inbox', sub:pending.length+' waiting'+
          (flagged.length?' · '+flagged.length+' auto-flagged':'')})
    : '')+
  panel('All reviews', dt('dtRev',{
    rows:REVIEWS, noun:'reviews', pageSize:12, sortKey:'when', sortDir:'desc', idKey:'id',
    searchFields:['id','sku','title','body','author'], searchPlaceholder:'Search review, product or author',
    chips:[{key:'state',options:REVIEW_STATES.map(s=>({label:s.charAt(0).toUpperCase()+s.slice(1),value:s}))},
           {key:'stars',options:[5,4,3,2,1].map(n=>({label:n+' star',value:n}))}],
    actions:exportBtn('Reviews','dtRev'),
    columns:[
      {key:'sku',label:'Listing',render:r=>{const p=SKUMAP[r.sku];
        return '<div class="cellmain">'+esc(p?p.name:r.sku)+'</div><div class="cellsub t-num">'+esc(r.sku)+'</div>';}},
      {key:'stars',label:'Rating',render:r=>starRow(r.stars,11)},
      {key:'title',label:'Review',render:r=>'<div class="cellmain">'+esc(r.title)+'</div>'+
        '<div class="cellsub">'+esc(r.body.slice(0,64))+(r.body.length>64?'…':'')+'</div>'},
      {key:'author',label:'By',render:r=>'<div class="t-small">'+esc(r.author)+'</div>'+
        (r.verified?'<div class="cellsub">Verified purchase</div>':'')},
      {key:'when',label:'When',render:r=>esc(r.when)},
      {key:'state',label:'State',render:r=>r.state==='published'?pill('active','Published')
        :r.state==='pending'?pill('pending','Awaiting check'):pill('rejected','Rejected')},
      {key:'__acts',label:'',sort:false,render:r=>r.state==='pending'
        ? '<button class="btn btn-sm btn-quiet" onclick="moderateReview(\''+r.id+'\',true)">Publish</button>'
        : (r.rejectReason?'<span class="t-tiny muted">'+esc(r.rejectReason)+'</span>':'')}
    ]}),
    {flush:true, icon:'star',
     sub:'Aggregate ratings are computed from published reviews only — a pending review does not move a rating, '+
         'otherwise moderation would be pointless. Reviews are checked for content, not sentiment: rejecting one '+
         'for being negative is not a permitted reason, and every rejection reason is recorded against the moderator.'})+
  '</div>';
}

/* ===========================================================================
   REVENUE PROJECTION
   Built from whichever trailing series belongs to the reader. A forecast that
   does not state its method and its past error is a number pretending to be
   a fact, so both travel with it everywhere it is shown.
   =========================================================================== */
function forecastFrom(series,opts){
  opts=opts||{};
  const s=(series||HISTORY).slice();
  const n=Math.min(6,s.length);
  const recent=s.slice(-n);
  /* Linear trend through the recent window, then a seasonal factor on top. */
  const xs=recent.map((_,i)=>i);
  const ys=recent.map(h=>h.gross);
  const mx=xs.reduce((a,b)=>a+b,0)/n, my=ys.reduce((a,b)=>a+b,0)/n;
  let num=0, den=0;
  xs.forEach((x,i)=>{ num+=(x-mx)*(ys[i]-my); den+=(x-mx)*(x-mx); });
  const slope=den?num/den:0;
  const base=my+slope*((n-1)/2+1);
  const months=opts.horizon||FORECAST_METHOD.horizon;
  const band=(opts.bandPct||FORECAST_METHOD.bandPct)/100;
  const out=[];
  for(let i=0;i<months;i++){
    const seas=SEASONALITY[i%SEASONALITY.length];
    const point=Math.max(0,+(base+slope*(i+1)).toFixed(2))*seas.f;
    out.push({month:seas.m, point:+point.toFixed(2),
              low:+(point*(1-band)).toFixed(2), high:+(point*(1+band)).toFixed(2),
              seasonal:seas.f});
  }
  const total=+out.reduce((a,p)=>a+p.point,0).toFixed(2);
  const lowT=+out.reduce((a,p)=>a+p.low,0).toFixed(2);
  const highT=+out.reduce((a,p)=>a+p.high,0).toFixed(2);
  const trailing=+s.slice(-months).reduce((a,h)=>a+h.gross,0).toFixed(2);
  return {points:out, total:total, low:lowT, high:highT, trailing:trailing,
          growth: trailing? +((total-trailing)/trailing*100).toFixed(1) : null,
          slope:slope, months:months, band:band};
}
/* Backtest: forecast the last three months from the nine before them, so the
   accuracy figure shown is measured rather than asserted. */
function forecastAccuracy(series){
  const s=(series||HISTORY).slice();
  if(s.length<9) return null;
  const train=s.slice(0,s.length-3), actualArr=s.slice(-3);
  const f=forecastFrom(train,{horizon:3});
  const predicted=+f.points.reduce((a,p)=>a+p.point,0).toFixed(2);
  const actual=+actualArr.reduce((a,h)=>a+h.gross,0).toFixed(2);
  if(!actual) return null;
  return {predicted:predicted, actual:actual,
          errPct:+((predicted-actual)/actual*100).toFixed(1)};
}
function forecastChart(f,opts){
  const pts=f.points.map(p=>({l:p.month, v:Math.round(p.point)}));
  return CH.bars(pts,Object.assign({h:180, fmt:n=>CUR0(n), tip:n=>CUR0(n),
    aria:(opts&&opts.aria)||'Projected value by month'},(opts&&opts.chart)||{}));
}
/* One shared panel so every persona explains its forecast the same way. */
function forecastPanel(cfg){
  const f=forecastFrom(cfg.series,cfg);
  const acc=forecastAccuracy(cfg.series);
  const money=cfg.money!==false;
  const fmt=v=>money?CUR0(v):FMT.num(Math.round(v));
  return panel(cfg.title||'Projection',
    '<div class="grid g-2-1">'+
      '<div>'+forecastChart(f,{aria:cfg.title||'Projection'})+
        '<div class="t-tiny muted" style="margin-top:6px">Next '+f.months+' months. '+
        'Shaded range is ±'+Math.round(f.band*100)+'%.</div></div>'+
      '<div class="stack" style="gap:11px">'+
        '<div><div class="t-tiny muted">'+esc(cfg.label||'Projected')+', next '+f.months+' months</div>'+
          '<div class="t-sub t-num" style="font-size:22px">'+fmt(f.total)+'</div>'+
          '<div class="t-tiny muted">'+fmt(f.low)+' to '+fmt(f.high)+'</div></div>'+
        '<div><div class="t-tiny muted">Against the trailing '+f.months+' months</div>'+
          '<div class="t-small strong">'+(f.growth==null
            ? '<span class="nodata">No comparable period</span>'
            : delta(f.growth)+' on '+fmt(f.trailing))+'</div></div>'+
        (acc
          ? '<div><div class="t-tiny muted">How wrong this method was last quarter</div>'+
            '<div class="t-small strong">'+(acc.errPct>0?'Over':'Under')+' by '+
            Math.abs(acc.errPct)+'%</div>'+
            '<div class="t-tiny muted">Predicted '+fmt(acc.predicted)+', actual '+fmt(acc.actual)+'</div></div>'
          : '<div class="t-tiny muted">Not enough history to measure the error.</div>')+
      '</div>'+
    '</div>'+
    '<div class="divider"></div>'+
    '<div class="t-small"><strong>Method.</strong> '+esc(FORECAST_METHOD.basis)+'. '+
      esc(FORECAST_METHOD.note)+'</div>'+
    (cfg.assumptions
      ? '<ul class="ticklist" style="margin-top:8px">'+cfg.assumptions.map(a=>
          '<li>'+SH('dot',10)+' '+a+'</li>').join('')+'</ul>'
      : '')+
    '<div class="t-tiny muted" style="margin-top:8px">A projection is a claim about the future. It is shown with '+
    'its method and its recent error so you can judge how much of it to believe — and it should not be pasted '+
    'into a board pack without both.</div>',
    {icon:'trendup', sub:cfg.sub});
}

/* ===========================================================================
   DUNNING  (ORD)
   =========================================================================== */
function dunState(d){
  return d.state==='suspended' ? pill('down','Suspended')
       : d.state==='restricted' ? pill('degraded','Purchases restricted')
       : d.promiseToPay ? pill('info','Promise to pay')
       : pill('pending','In dunning');
}
function dunStep(d){
  /* Read the ladder this case is actually on, not a single global one. */
  const l=ladderFor(d), st=ladderSteps(l);
  const s=st[Math.min(Math.max(d.step,1),st.length)-1]||{};
  return '<div class="t-small strong">Step '+d.step+' of '+st.length+'</div>'+
    '<div class="cellsub">'+esc(dunAction(s.action).label||'')+'</div>'+
    '<div class="cellsub t-tiny">'+esc(l.name)+'</div>';
}
/* What the marketplace does that the seller cannot change. Shown to a seller
   in full rather than summarised, because the thing they most need to predict
   is when a bundled customer of theirs loses service. */
function overrideLaddersPanel(){
  const ops=operatorLadders().filter(l=>l.status==='active');
  return panel('Marketplace ladders that override yours',
    banner('info','<strong>'+esc(DUN_GOVERNANCE.bundled)+'</strong>')+
    '<div class="tablewrap"><table class="tbl"><thead><tr><th style="min-width:170px">Ladder</th>'+
      '<th>Customer type</th><th class="num">Steps</th><th class="num">Suspends</th><th>Pacing</th>'+
      '<th style="width:96px"></th></tr></thead><tbody>'+
    ops.map(l=>{
      const susp=ladderSuspendDay(l);
      return '<tr><td><div class="cellmain">'+esc(l.name)+'</div>'+
        '<div class="cellsub">'+esc(l.why||'')+'</div></td>'+
        '<td class="t-small">'+(l.segment==null?'Any customer type'
          :esc((DUN_SEGMENTS.filter(x=>x.id===l.segment)[0]||{}).label||l.segment))+'</td>'+
        '<td class="num t-num">'+ladderSteps(l).length+'</td>'+
        '<td class="num t-num">'+(susp==null?'<span class="dim">Never</span>':'Day '+susp)+'</td>'+
        '<td style="min-width:150px">'+ladderTimeline(l)+'</td>'+
        '<td class="rowend"><button class="btn btn-sm btn-quiet" onclick="ladderDialog(\''+l.id+'\')">View</button></td>'+
      '</tr>';
    }).join('')+'</tbody></table></div>'+
    '<p class="t-tiny muted">Read-only. If a pacing here is wrong for your customers, raise it with the '+
      'marketplace rather than working around it — a second ladder on the same balance produces two '+
      'suspension dates and the customer believes whichever arrived first.',
    {icon:'shield', sub:ops.length+' marketplace ladders'});
}

/* ==========================================================================
   46. CREDIT AND DEBIT NOTES (M37)
   --------------------------------------------------------------------------
   Between the marketplace and a seller only. It corrects a settlement that
   has already been struck. No customer, no card, no money moving on its own —
   it changes the balance the next run pays or collects.
   ========================================================================== */

function noteType(id){ return NTMAP[id] || NOTE_TYPES[0]; }
function noteReason(id){ return NOTE_REASONS.filter(r=>r.id===id)[0] || {label:id, note:''}; }
function noteState(s){ return NOTE_STATES.filter(x=>x.s===s)[0] || {label:s, note:''}; }
function noteStatePill(n){
  const k = n.state==='applied'?'ok' : n.state==='issued'?'' :
            n.state==='disputed'?'danger' : n.state==='void'?'' : 'warn';
  return pill(k, noteState(n.state).label);
}
function notesFor(pid){ return CREDIT_NOTES.filter(n=>n.partnerId===pid); }
/* What a note does to a seller's balance: a credit reduces what they owe us. */
function noteSigned(n){ return noteType(n.type).sign * n.amount; }
function noteNetFor(pid){
  return +notesFor(pid).filter(n=>n.state==='issued'||n.state==='applied')
    .reduce((a,n)=>a+noteSigned(n),0).toFixed(2);
}

function notesView(cfg){
  cfg=cfg||{};
  const pid=cfg.partnerId||null;
  const isOp=!pid;
  const rows = pid? notesFor(pid) : CREDIT_NOTES.slice();
  const pend = rows.filter(n=>n.state==='pending');
  const disp = rows.filter(n=>n.state==='disputed');
  const credits=+rows.filter(n=>n.type==='credit'&&n.state!=='void'&&n.state!=='draft')
    .reduce((a,n)=>a+n.amount,0).toFixed(2);
  const debits =+rows.filter(n=>n.type==='debit' &&n.state!=='void'&&n.state!=='draft')
    .reduce((a,n)=>a+n.amount,0).toFixed(2);

  return pagehead(cfg.title||'Credit and debit notes',
    isOp? 'Corrections to a settlement that has already been struck. No customer is involved.'
        : 'Adjustments the marketplace has raised against your account. Each one lands on a statement.',
    exportBtn('Credit and debit notes','dtNotes')+
    (isOp?'<button class="btn btn-primary" onclick="noteDialog(null)">'+ICO('plus',13)+'Raise a note</button>':''))+
  '<div class="stack">'+

  banner('info','<strong>A note is between the marketplace and a seller. A refund is between a customer and '+
    'whoever sold to them.</strong> They are kept apart because a note never touches a card, and a refund '+
    'never changes a commission rate. '+esc(NOTE_POLICY.note))+

  (pend.length? banner('warning','<strong>'+pend.length+' note'+(pend.length===1?'':'s')+
    ' above '+CUR0(NOTE_POLICY.secondApprovalAbove)+' '+(pend.length===1?'is':'are')+
    ' waiting on a second approver.</strong> Nothing above that value settles on one signature.'):'')+
  (disp.length? banner('danger','<strong>'+disp.length+' note'+(disp.length===1?' is':'s are')+
    ' disputed.</strong> A disputed note does not settle while it is open, so it cannot be quietly '+
    'deducted while the argument continues.'):'')+

  '<div class="grid g4">'+
    metric({icon:'minus',label:'Credits raised',value:CUR0(credits),
      foot:'Reduces what sellers owe us'})+
    metric({icon:'plus',label:'Debits raised',value:CUR0(debits),
      foot:'Increases what sellers owe us'})+
    metric({icon:'clock',label:'Awaiting approval',value:String(pend.length),
      foot:pend.length?'Above '+CUR0(NOTE_POLICY.secondApprovalAbove):'None outstanding'})+
    metric({icon:'warning',label:'Disputed',value:String(disp.length),
      foot:disp.length?'Held out of settlement':'None disputed'})+
  '</div>'+

  (isOp? notePolicyPanel() : '')+

  panel('Notes', dt('dtNotes',{
    rows:rows, noun:'notes', pageSize:10, sortKey:'raised', sortDir:'desc', idKey:'id',
    onRow:"openNote('$ID')",
    searchFields:['id','ref','detail'], searchPlaceholder:'Search reference, note or detail',
    chips:[{key:'type',options:[{label:'Credit',value:'credit'},{label:'Debit',value:'debit'}]},
           {key:'state',options:NOTE_STATES.map(x=>({label:x.label,value:x.s}))}],
    columns:[
      {key:'id',label:'Note',render:r=>'<div class="cellmain t-num">'+esc(r.id)+'</div>'+
        '<div class="cellsub">'+esc(noteType(r.type).label)+'</div>'},
      (isOp? {key:'partnerId',label:'Seller',render:r=>esc((PMAP[r.partnerId]||{name:r.partnerId}).name)} : null),
      {key:'reason',label:'Why',render:r=>'<div class="cellmain">'+esc(noteReason(r.reason).label)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.ref||'')+'</div>'},
      {key:'amount',label:'Amount',align:'right',render:r=>'<span class="t-num cellmain">'+
        (r.type==='credit'?'less ':'plus ')+CUR(r.amount)+'</span>'+
        '<div class="cellsub t-num">tax '+CUR(r.tax||0)+'</div>'},
      {key:'period',label:'Period',render:r=>esc(r.period)},
      {key:'raised',label:'Raised',render:r=>'<div class="t-small">'+esc(r.raised)+'</div>'+
        '<div class="cellsub">'+esc(r.by||'')+'</div>'},
      {key:'state',label:'State',render:r=>noteStatePill(r)},
      {key:'_act',label:'',align:'right',render:r=>actionCell(
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();openNote(\''+r.id+
          '\')">Open</button>',
        (isOp && r.state==='pending')
          ? '<button class="btn btn-sm" onclick="event.stopPropagation();approveNote(\''+r.id+
            '\')">Approve</button>'
        : (!isOp && r.state==='issued')
          ? '<button class="btn btn-sm" onclick="event.stopPropagation();disputeNote(\''+r.id+
            '\')">Dispute</button>'
        : r.state==='disputed' ? actionHeld('Disputed','')
        : r.state==='applied'  ? actionDone('Applied', r.period||'')
        : r.state==='issued'   ? actionDone('Issued','')
        : actionHeld('With the marketplace',''),
        {width:'104px'})}
    ].filter(Boolean)}),
    {flush:true, icon:'file',
     sub: pid? 'Net effect on your account: '+(noteNetFor(pid)<0
            ? CUR(Math.abs(noteNetFor(pid)))+' in your favour'
            : CUR(noteNetFor(pid))+' owed to the marketplace')
        : CREDIT_NOTES.length+' notes across '+new Set(CREDIT_NOTES.map(n=>n.partnerId)).size+' sellers'})+
  '</div>';
}

function notePolicyPanel(){
  return panel('How notes are controlled',
    '<div class="grid g2">'+
      dl([['Auto-approved below', CUR0(NOTE_POLICY.autoApproveBelow)],
          ['Second approver above', CUR0(NOTE_POLICY.secondApprovalAbove)],
          ['Evidence required above', CUR0(NOTE_POLICY.requireEvidenceAbove)],
          ['Reason mandatory', NOTE_POLICY.requireReason?'Yes':'No']])+
      dl([['Settles on', NOTE_POLICY.settleOn],
          ['Can be voided within', NOTE_POLICY.voidWindowDays+' days of issue'],
          ['Credit posts to', NOTE_POLICY.glCredit+' via clearing '+NOTE_POLICY.glClearing],
          ['Debit posts to', NOTE_POLICY.glDebit+' via clearing '+NOTE_POLICY.glClearing]])+
    '</div>'+
    '<p class="t-small muted">'+esc(NOTE_POLICY.taxTreatment)+'</p>',
    {icon:'shield', sub:'Numbering '+NOTE_POLICY.prefixCredit+'nnnn and '+NOTE_POLICY.prefixDebit+'nnnn',
     acts:'<button class="btn btn-sm" onclick="notePolicyDialog()">Configure</button>'});
}

function notePolicyDialog(){
  openModal('<div class="modal-head">'+ICO('shield',18)+'<div class="grow">'+
    '<h3 class="t-sub">Note policy</h3><div class="t-small muted">Who may raise one, and at what value it '+
    'needs a second pair of eyes</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>A debit note is the only adjustment on the platform that increases our own revenue.</strong> '+
        'That is why the thresholds matter more here than anywhere else in settlement.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="npAuto">Auto-approve below</label>'+
          '<input class="inp" id="npAuto" type="number" min="0" value="'+NOTE_POLICY.autoApproveBelow+'">'+
          '<p class="t-tiny muted">Small corrections are noise. Making somebody sign for a $12 rounding '+
          'difference teaches them to sign without reading.</p></div>'+
        '<div class="field"><label for="npSecond">Second approver above</label>'+
          '<input class="inp" id="npSecond" type="number" min="0" value="'+NOTE_POLICY.secondApprovalAbove+'">'+
          '<p class="t-tiny muted">Above this, one person cannot both raise and issue.</p></div>'+
        '<div class="field"><label for="npEvid">Evidence required above</label>'+
          '<input class="inp" id="npEvid" type="number" min="0" value="'+NOTE_POLICY.requireEvidenceAbove+'">'+
          '<p class="t-tiny muted">A reference to the report, contract clause or ticket it comes from.</p></div>'+
        '<div class="field"><label for="npVoid">Void window (days)</label>'+
          '<input class="inp" id="npVoid" type="number" min="0" value="'+NOTE_POLICY.voidWindowDays+'">'+
          '<p class="t-tiny muted">After this it can only be reversed by an opposing note, which leaves both '+
          'on the record.</p></div>'+
      '</div>'+
      '<label class="chk"><input type="checkbox" id="npReason"'+(NOTE_POLICY.requireReason?' checked':'')+
        '> A reason is mandatory on every note</label>'+
      '<div id="npWarn"></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="saveNotePolicy()">Save</button></div>',
    {wide:true, label:'Note policy'});
}
function saveNotePolicy(){
  const n=k=>parseFloat((document.getElementById(k)||{}).value||'0')||0;
  const auto=n('npAuto'), second=n('npSecond'), evid=n('npEvid'), vd=n('npVoid');
  const w=document.getElementById('npWarn');
  if(second<=auto){ if(w) w.innerHTML=banner('danger','<strong>The second-approval threshold must be above '+
    'the auto-approval one.</strong> Otherwise every note is both automatic and escalated, and the platform '+
    'has to pick one for you.'); return; }
  const before=NOTE_POLICY.secondApprovalAbove;
  NOTE_POLICY.autoApproveBelow=auto; NOTE_POLICY.secondApprovalAbove=second;
  NOTE_POLICY.requireEvidenceAbove=evid; NOTE_POLICY.voidWindowDays=vd;
  NOTE_POLICY.requireReason=!!(document.getElementById('npReason')||{}).checked;
  if(typeof audit==='function') audit('note.policy',{object:'Credit and debit note policy',
    before:CUR0(before), after:CUR0(second),
    detail:'Auto-approve below '+CUR0(auto)+', second approver above '+CUR0(second)});
  closeModal(); toast('Note policy saved'); App.go(App.view);
}

function noteDialog(id){
  const n = id? CNMAP[id] : null;
  openModal('<div class="modal-head">'+ICO('file',18)+'<div class="grow">'+
    '<h3 class="t-sub">'+(n?'Note '+esc(n.id):'Raise a credit or debit note')+'</h3>'+
    '<div class="t-small muted">Between the marketplace and a seller. It changes what the next run pays '+
    'or collects.</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="grid g2">'+
        '<div class="field"><label for="cnPtr">Seller</label><select class="inp" id="cnPtr">'+
          PARTNERS.filter(p=>p.status==='live').map(p=>'<option value="'+p.id+'">'+esc(p.name)+'</option>').join('')+
          '</select></div>'+
        '<div class="field"><label for="cnType">Type</label>'+
          '<select class="inp" id="cnType" onchange="cnReasons()">'+
          NOTE_TYPES.map(t=>'<option value="'+t.id+'">'+esc(t.label)+'</option>').join('')+'</select>'+
          '<p class="t-tiny muted" id="cnTypeNote"></p></div>'+
      '</div>'+
      '<div class="field"><label for="cnReason">Reason</label><select class="inp" id="cnReason" '+
        'onchange="cnPreview()"></select><p class="t-tiny muted" id="cnReasonNote"></p></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="cnAmt">Amount (excluding tax)</label>'+
          '<input class="inp" id="cnAmt" type="number" min="0" step="0.01" value="" onchange="cnPreview()" '+
          'data-autofocus></div>'+
        '<div class="field"><label for="cnPeriod">Period it corrects</label>'+
          '<input class="inp" id="cnPeriod" value="Jul 2026"></div>'+
      '</div>'+
      '<div class="field"><label for="cnRef">Reference</label>'+
        '<input class="inp" id="cnRef" placeholder="Settlement run, contract clause or ticket"></div>'+
      '<div class="field"><label for="cnDetail">What happened</label>'+
        '<textarea class="inp" id="cnDetail" rows="2" placeholder="Enough that somebody reading the statement '+
        'in six months understands it"></textarea></div>'+
      '<div id="cnWarn"></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow" id="cnRoute"></span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="saveNote()">Raise it</button></div>',
    {wide:true, label:'Credit or debit note'});
  cnReasons();
}
function cnReasons(){
  const t=(document.getElementById('cnType')||{}).value||'credit';
  const sel=document.getElementById('cnReason'); if(!sel) return;
  sel.innerHTML=NOTE_REASONS.filter(r=>r.type===t)
    .map(r=>'<option value="'+r.id+'">'+esc(r.label)+'</option>').join('');
  const tn=document.getElementById('cnTypeNote');
  if(tn) tn.textContent=noteType(t).effect+' '+noteType(t).note;
  cnPreview();
}
function cnPreview(){
  const t=(document.getElementById('cnType')||{}).value||'credit';
  const amt=parseFloat((document.getElementById('cnAmt')||{}).value||'0')||0;
  const rid=(document.getElementById('cnReason')||{}).value||'';
  const rn=document.getElementById('cnReasonNote'); if(rn) rn.textContent=noteReason(rid).note;
  const route=document.getElementById('cnRoute');
  if(route) route.textContent = !amt ? 'Enter an amount to see how it will be routed'
    : amt < NOTE_POLICY.autoApproveBelow ? 'Below '+CUR0(NOTE_POLICY.autoApproveBelow)+' — issued immediately'
    : amt > NOTE_POLICY.secondApprovalAbove ? 'Above '+CUR0(NOTE_POLICY.secondApprovalAbove)+
        ' — held for a second approver'
    : 'Issued on your signature';
  const w=document.getElementById('cnWarn'); if(!w) return;
  const msgs=[];
  if(t==='debit' && amt>0)
    msgs.push(banner('warning','<strong>A debit note takes money from a seller.</strong> It has to be '+
      'supportable from a contract clause or a measured breach, because it is the one adjustment that '+
      'increases our own revenue.'));
  if(amt>NOTE_POLICY.requireEvidenceAbove)
    msgs.push(banner('info','<strong>Above '+CUR0(NOTE_POLICY.requireEvidenceAbove)+', a reference is required.</strong> '+
      'Name the report, clause or ticket it comes from.'));
  w.innerHTML=msgs.join('');
}
function saveNote(){
  const g=k=>((document.getElementById(k)||{}).value||'').trim();
  const amt=parseFloat(g('cnAmt'))||0, type=g('cnType'), pid=g('cnPtr');
  const w=document.getElementById('cnWarn');
  const fail=m=>{ if(w) w.innerHTML=banner('danger',m); };
  if(!amt||amt<=0) return fail('A note needs an amount.');
  if(NOTE_POLICY.requireReason && !g('cnReason')) return fail('A note needs a reason.');
  if(amt>NOTE_POLICY.requireEvidenceAbove && !g('cnRef'))
    return fail('<strong>A reference is required above '+CUR0(NOTE_POLICY.requireEvidenceAbove)+'.</strong> '+
      'Name the settlement run, contract clause or ticket this comes from.');
  if(!g('cnDetail')) return fail('Say what happened. A statement line nobody can explain gets disputed.');

  const auto = amt < NOTE_POLICY.autoApproveBelow;
  const needs2 = amt > NOTE_POLICY.secondApprovalAbove;
  const seq = NOTE_POLICY.nextSeq++;
  const id = (type==='credit'?NOTE_POLICY.prefixCredit:NOTE_POLICY.prefixDebit)+String(seq).padStart(4,'0');
  const n = {id:id, type:type, partnerId:pid, amount:+amt.toFixed(2),
             tax:+(amt*0.18).toFixed(2), reason:g('cnReason'), period:g('cnPeriod')||'Jul 2026',
             raised:TODAY, by:'You', approver:auto?'Auto':null,
             state: needs2?'pending':'issued', ref:g('cnRef')||null, evidence:g('cnRef')||null,
             detail:g('cnDetail'), isNew:true};
  CREDIT_NOTES.push(n); CNMAP[id]=n;
  if(typeof audit==='function') audit('note.raised',{object:id, after:n.state, amount:n.amount,
    detail:noteType(type).label+' for '+(PMAP[pid]||{name:pid}).name+' — '+noteReason(n.reason).label,
    sev:type==='debit'?'high':'warn'});
  closeModal();
  toast(id+(needs2?' raised — held for a second approver':' issued'), needs2?'warn':'');
  App.go(App.view);
}

function openNote(id){
  const n=CNMAP[id]; if(!n) return;
  const isOp = authCtx()==='operator';
  const p=PMAP[n.partnerId]||{name:n.partnerId};
  openInspector('<div class="insp-head">'+ICO('file',18)+'<div class="grow">'+
    '<h3 class="t-sub">'+esc(n.id)+'</h3><div class="t-small muted">'+esc(noteType(n.type).label)+
    ' · '+esc(p.name)+'</div></div>'+noteStatePill(n)+'</div>'+
  '<div class="insp-body stack">'+
    banner(n.type==='debit'?'warning':'info','<strong>'+esc(noteType(n.type).effect)+'</strong> '+
      esc(noteState(n.state).note))+
    dl([['Amount', (n.type==='credit'?'less ':'plus ')+CUR(n.amount)],
        ['Tax restated', CUR(n.tax||0)],
        ['Reason', noteReason(n.reason).label],
        ['Period corrected', n.period],
        ['Reference', n.ref||'—'],
        ['Evidence', n.evidence||'Not required at this value'],
        ['Raised', n.raised+' by '+(n.by||'—')],
        ['Approved by', n.approver||'Not yet approved'],
        ['Settles', NOTE_POLICY.settleOn]])+
    '<p class="t-small">'+esc(n.detail||'')+'</p>'+
    '<div class="divider"></div><h4 class="t-sub">How it posts</h4>'+
    (function(){ const m=GL_MAPPING[n.type==='credit'?'note.credit':'note.debit']||{};
      return dl([['Debit', (m.dr||'—')+' '+((GLMAP[m.dr]||{}).name||'')],
                 ['Credit',(m.cr||'—')+' '+((GLMAP[m.cr]||{}).name||'')]])+
             '<p class="t-tiny muted">'+esc(m.why||'')+'</p>'; })()+
  '</div>'+
  '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
    '<div class="spacer"></div>'+
    (isOp && n.state==='pending'?'<button class="btn btn-primary" onclick="approveNote(\''+n.id+'\')">Approve</button>':'')+
    (isOp && (n.state==='issued'||n.state==='pending')
      ?'<button class="btn" onclick="voidNote(\''+n.id+'\')">Void</button>':'')+
    (!isOp && n.state==='issued'?'<button class="btn" onclick="disputeNote(\''+n.id+'\')">Dispute it</button>':'')+
    (isOp && n.state==='disputed'?'<button class="btn btn-primary" onclick="resolveNote(\''+n.id+'\')">Resolve</button>':'')+
  '</div>', 'Note '+n.id);
}
function approveNote(id){
  const n=CNMAP[id]; if(!n||n.state!=='pending') return;
  n.state='issued'; n.approver='You';
  if(typeof audit==='function') audit('note.state',{object:id, before:'pending', after:'issued',
    amount:n.amount, detail:'Second approval given'});
  closeInspector(); toast(id+' issued'); App.go(App.view);
}
function voidNote(id){
  const n=CNMAP[id]; if(!n) return;
  confirmAction({title:'Void '+id+'?', subtitle:CUR(n.amount)+' '+noteType(n.type).label.toLowerCase(),
    risk:'high', confirmLabel:'Void it',
    body:banner('warning','<strong>Voiding is only available for '+NOTE_POLICY.voidWindowDays+
      ' days from issue.</strong> After that the only correction is an opposing note, which leaves both '+
      'on the record — which is usually the more honest outcome anyway.'),
    impact:['The note is removed from the next settlement run',
            'It stays visible with its reason, rather than disappearing',
            'The seller sees the void as well as the original'],
    onConfirm:()=>{ n.state='void';
      if(typeof audit==='function') audit('note.state',{object:id, before:'issued', after:'void',
        amount:n.amount, detail:'Voided before settlement', sev:'high'});
      closeInspector(); toast(id+' voided','warn'); App.go(App.view); }});
}
function disputeNote(id){
  const n=CNMAP[id]; if(!n) return;
  confirmAction({title:'Dispute '+id+'?', subtitle:CUR(n.amount)+' on your '+esc(n.period)+' statement',
    confirmLabel:'Raise the dispute',
    body:banner('info','<strong>A disputed note does not settle while it is open.</strong> It will not be '+
      'deducted from your next payout while the marketplace looks at it.')+
      '<div class="field"><label for="dnWhy">Why you disagree</label>'+
      '<textarea class="inp" id="dnWhy" rows="2"></textarea></div>',
    impact:['The amount is held out of the next settlement run',
            'The marketplace has to respond before it can be applied',
            'Your reason is recorded against the note'],
    onConfirm:(vals)=>{ n.state='disputed'; n.dispute=(vals&&vals.dnWhy)||'No reason given';
      if(typeof audit==='function') audit('note.state',{object:id, before:'issued', after:'disputed',
        amount:n.amount, detail:'Disputed by the seller'});
      closeInspector(); toast(id+' disputed — it will not settle while open','warn'); App.go(App.view); }});
}
function resolveNote(id){
  const n=CNMAP[id]; if(!n) return;
  confirmAction({title:'Resolve the dispute on '+id+'?', subtitle:CUR(n.amount),
    confirmLabel:'Uphold the note',
    body:banner('warning','<strong>Upholding puts it back into the next run.</strong> If the seller is right, '+
      'void it instead — a note upheld and then quietly reversed is worse than one withdrawn.'),
    impact:['The note settles on the next run','The dispute and its outcome stay on the record'],
    onConfirm:()=>{ n.state='issued';
      if(typeof audit==='function') audit('note.state',{object:id, before:'disputed', after:'issued',
        amount:n.amount, detail:'Dispute resolved in the marketplace’s favour', sev:'high'});
      closeInspector(); toast(id+' upheld'); App.go(App.view); }});
}

/* ==========================================================================
   47. CUSTOMER REFUNDS (M37)
   --------------------------------------------------------------------------
   Between a customer and whoever sold to them. Who decides is not ours to
   choose for a third-party product — it is the seller's revenue being handed
   back. The marketplace decides only what it sold itself, what it bundled,
   and what a seller has failed to answer.
   ========================================================================== */

function refundReason(id){ return REFUND_REASONS.filter(r=>r.id===id)[0] || {label:id, evidence:''}; }
function refundStatePill(r){
  const k = r.state==='refunded'?'ok' : r.state==='partial'?'ok' :
            r.state==='declined'?'danger' : r.state==='escalated'?'danger' :
            r.state==='approved'?'' : 'warn';
  return pill(k, (RFMAP[r.state]||{label:r.state}).label);
}
/* The same shape as dunning governance, and deliberately so: one rule about
   who owns a commercial decision, applied consistently in both directions. */
function refundApprover(r){
  if(r.firstParty)
    return {owner:'operator', why:'A first-party product. The marketplace sold it, so the marketplace decides '+
      'and the marketplace funds it.'};
  if(r.bundleId)
    return {owner:'operator', why:'Sold inside a bundle the marketplace assembled. One merchant of record, '+
      'one decision — the seller cannot refund a third of a bundle the customer bought as one thing.'};
  if(r.state==='escalated')
    return {owner:'operator', why:'The response SLA escalated it. The marketplace now decides, '+
      'and can overrule the seller.'};
  if(r.slaBreached)
    return {owner:'operator', why:'The seller did not answer within '+REFUND_POLICY.sellerSlaHours+' hours. '+
      'The marketplace answers so the customer is not left waiting on a silent third party.'};
  return {owner:'partner', ownerId:r.sellerId,
    why:'The seller’s own product, sold direct. It is their revenue being handed back, so it is their '+
        'decision — and it is recovered from their settlement either way.'};
}
function refundOverdue(r){
  return r.state==='requested' && r.slaHours!=null && r.slaHours>REFUND_POLICY.sellerSlaHours;
}
function refundsFor(cfg){
  if(cfg.partnerId) return REFUNDS.filter(r=>r.sellerId===cfg.partnerId);
  if(cfg.ctx==='operator') return REFUNDS.slice();
  return REFUNDS.filter(r=>r.ctx===cfg.ctx);
}

function refundsView(cfg){
  cfg=cfg||{};
  const pid=cfg.partnerId||null;
  const isOp=cfg.ctx==='operator';
  const isCustomer = cfg.ctx==='consumer' || cfg.ctx==='buyer';
  /* The clock runs whether or not anyone is looking, so settle it before we
     draw a state that a human would otherwise have to chase. */
  refundSlaSweep();
  const rows=refundsFor(cfg);
  const waiting=rows.filter(r=>r.state==='requested');
  const mine = pid? waiting.filter(r=>refundApprover(r).owner==='partner') : [];
  const notMine = pid? rows.filter(r=>refundApprover(r).owner==='operator') : [];
  const esc_=rows.filter(r=>r.state==='escalated');
  const value=+rows.filter(r=>r.state==='refunded'||r.state==='partial')
    .reduce((a,r)=>a+r.amount,0).toFixed(2);

  return pagehead(cfg.title||'Refunds',
    isCustomer? 'Money back to the card or account that paid. The seller decides, and the marketplace steps '+
                'in if they do not.'
    : pid? 'Requests against what you sold. Approving one gives back your revenue, so it is your call.'
    : 'Every refund on the platform, and who is responsible for deciding it.',
    exportBtn('Refunds','dtRfn')+
    (isCustomer?'<button class="btn btn-primary" onclick="refundRequestDialog()">'+ICO('plus',13)+
      'Request a refund</button>':'')+
    (isOp?'<button class="btn" onclick="refundPolicyDialog()">'+ICO('shield',13)+'Refund policy</button>':''))+
  '<div class="stack">'+

  (pid? banner('info','<strong>You decide refunds on what you sold directly. The marketplace decides on '+
    'bundles, on its own products, and on anything you leave unanswered for '+REFUND_POLICY.sellerSlaHours+
    ' hours.</strong> '+esc(REFUND_POLICY.fundedBy)) : '')+
  (isCustomer? banner('info','<strong>'+esc(REFUND_POLICY.note)+'</strong> The seller has '+
    REFUND_POLICY.sellerSlaHours+' hours to answer. '+esc(REFUND_POLICY.escalationRule)) : '')+
  (isOp? banner('info','<strong>The marketplace decides only what it is responsible for.</strong> '+
    esc(REFUND_POLICY.marketplaceDecidesWhen)) : '')+

  (mine.length? banner('warning','<strong>'+mine.length+' request'+(mine.length===1?'':'s')+
    ' '+(mine.length===1?'is':'are')+' waiting on you.</strong> Past '+REFUND_POLICY.sellerSlaHours+
    ' hours the marketplace answers on your behalf and still recovers the money from your settlement, so '+
    'silence costs you the decision rather than the money.'):'')+
  (esc_.length? banner('danger','<strong>'+esc_.length+' request'+(esc_.length===1?' has':'s have')+
    ' been escalated by the response SLA.</strong> The clock ran out, or a decline had no evidence behind '+
    'it. The marketplace decides these and can overrule the seller. No customer had to ask.'):'')+

  '<div class="grid g4">'+
    metric({icon:'wallet',label:'Refunded',value:CUR0(value),
      foot:rows.filter(r=>r.state==='refunded'||r.state==='partial').length+' of '+rows.length+' requests'})+
    metric({icon:'clock',label:'Awaiting a decision',value:String(waiting.length),
      foot:waiting.length?'SLA is '+REFUND_POLICY.sellerSlaHours+' hours':'Nothing outstanding'})+
    metric({icon:'warning',label:'Escalated',value:String(esc_.length),
      foot:esc_.length?'Marketplace decides':'None escalated'})+
    metric({icon:'ban',label:'Declined',value:String(rows.filter(r=>r.state==='declined').length),
      foot:'Each with a written reason'})+
  '</div>'+

  (isOp? refundPolicyPanel() : '')+

  panel('Requests', dt('dtRfn',{
    rows:rows, noun:'requests', pageSize:10, sortKey:'requested', sortDir:'desc', idKey:'id',
    onRow:"openRefund('$ID')",
    searchFields:['id','order','customer','item'], searchPlaceholder:'Search request, order, customer or item',
    chips:[{key:'state',options:REFUND_STATES.map(x=>({label:x.label,value:x.s}))}],
    columns:[
      {key:'id',label:'Request',render:r=>'<div class="cellmain t-num">'+esc(r.id)+'</div>'+
        '<div class="cellsub t-num">'+esc(r.order)+'</div>'},
      (isCustomer? null : {key:'customer',label:'Customer',render:r=>esc(r.customer)}),
      {key:'item',label:'What',render:r=>'<div class="cellmain">'+esc(r.item)+'</div>'+
        '<div class="cellsub">'+esc(refundReason(r.reason).label)+'</div>'},
      {key:'amount',label:'Amount',align:'right',render:r=>'<span class="t-num cellmain">'+CUR(r.amount)+'</span>'},
      (pid||isOp? {key:'sellerName',label:'Whose decision',render:r=>{
        const a=refundApprover(r);
        return '<div class="cellmain">'+(a.owner==='partner'?'Seller':'Marketplace')+'</div>'+
          '<div class="cellsub t-tiny">'+esc(r.bundleId? 'Bundle — '+(r.bundleName||r.bundleId)
            : r.firstParty? 'First-party' : (r.sellerName||''))+'</div>'; }} : null),
      {key:'requested',label:'Requested',render:r=>esc(r.requested)+
        (refundOverdue(r)?'<div class="cellsub warntext">Past SLA</div>':'')},
      {key:'state',label:'State',render:r=>refundStatePill(r)},
      {key:'_act',label:'',align:'right',render:r=>{
        const a=refundApprover(r);
        const canDecide = (pid && a.owner==='partner' && a.ownerId===pid && r.state==='requested') ||
                          (isOp && a.owner==='operator' && (r.state==='requested'||r.state==='escalated'));
        return actionCell(
          '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();openRefund(\''+r.id+
            '\')">Open</button>',
          canDecide
            ? '<button class="btn btn-sm" onclick="event.stopPropagation();refundDecide(\''+r.id+
              '\')">Decide</button>'
            : (RFMAP[r.state]||{}).final
              ? actionDone((RFMAP[r.state]||{}).label||r.state, r.decided||'')
              : actionHeld(a.owner==='partner' ? 'With the seller' : 'With the marketplace',''),
          {width:'112px'}); }}
    ].filter(Boolean)}),
    {flush:true, icon:'refresh',
     sub: pid? mine.length+' waiting on you · '+notMine.length+' decided by the marketplace'
         : rows.length+' requests'})+

  (pid && notMine.length? panel('Decided by the marketplace, funded by you',
    banner('warning','<strong>These are recovered from your settlement even though you did not decide them.</strong> '+
      esc(REFUND_POLICY.fundedBy))+
    '<div class="tablewrap"><table class="tbl"><thead><tr><th>Request</th><th>What</th>'+
      '<th class="num">Amount</th><th>Why it is not yours</th><th>State</th></tr></thead><tbody>'+
    notMine.map(r=>'<tr><td class="t-num t-small">'+esc(r.id)+'</td>'+
      '<td class="t-small">'+esc(r.item)+'</td>'+
      '<td class="num t-num">'+CUR(r.amount)+'</td>'+
      '<td class="t-small">'+esc(refundApprover(r).why)+'</td>'+
      '<td>'+refundStatePill(r)+'</td></tr>').join('')+
    '</tbody></table></div>', {icon:'shield', sub:notMine.length+' requests'}) : '')+

  (isCustomer? refundWindowsPanel() : '')+
  '</div>';
}

function refundWindowsPanel(){
  return panel('How long you have',
    '<div class="tablewrap"><table class="tbl"><thead><tr><th>Category</th>'+
      '<th class="num">Window</th><th>What it covers</th></tr></thead><tbody>'+
    REFUND_WINDOWS.map(w=>'<tr><td class="cellmain">'+
      esc((VMAP[w.vertical]||{name:w.vertical}).name)+'</td>'+
      '<td class="num t-num">'+w.days+' days</td>'+
      '<td class="t-small">'+esc(w.note)+'</td></tr>').join('')+
    '</tbody></table></div>'+
    '<p class="t-small muted">A fault does not expire with the window. If something is broken or was never '+
    'delivered, ask whenever you notice.</p>',
    {icon:'clock', sub:'From the date you were charged'});
}

function refundPolicyPanel(){
  return panel('Refund policy',
    '<div class="grid g2">'+
      dl([['Seller response SLA', REFUND_POLICY.sellerSlaHours+' hours'],
          ['Auto-approved below', CUR0(REFUND_POLICY.autoApproveBelow)],
          ['Always auto-approved', REFUND_POLICY.autoApproveReasons.map(r=>refundReason(r).label).join(', ')],
          ['Marketplace takes over after', REFUND_POLICY.escalateAfterHours+' hours']])+
      dl([['Marketplace decides when', REFUND_POLICY.marketplaceDecidesWhen],
          ['Funded by', REFUND_POLICY.fundedBy]])+
    '</div>',
    {icon:'shield', sub:'Applies to every seller',
     acts:'<button class="btn btn-sm" onclick="refundPolicyDialog()">Configure</button>'});
}
function refundPolicyDialog(){
  openModal('<div class="modal-head">'+ICO('shield',18)+'<div class="grow">'+
    '<h3 class="t-sub">Refund policy</h3><div class="t-small muted">How long a seller has, and what never '+
    'needs a human</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>A customer waiting on a silent seller is our problem, not theirs.</strong> '+
        'The SLA exists so the marketplace can answer rather than explaining that a third party has not replied.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="rpSla">Seller response SLA (hours)</label>'+
          '<input class="inp" id="rpSla" type="number" min="1" value="'+REFUND_POLICY.sellerSlaHours+'"></div>'+
        '<div class="field"><label for="rpTake">Marketplace takes over after (hours)</label>'+
          '<input class="inp" id="rpTake" type="number" min="1" value="'+REFUND_POLICY.escalateAfterHours+'"></div>'+
        '<div class="field"><label for="rpAuto">Auto-approve below</label>'+
          '<input class="inp" id="rpAuto" type="number" min="0" value="'+REFUND_POLICY.autoApproveBelow+'">'+
          '<p class="t-tiny muted">Below this, arguing costs more than refunding.</p></div>'+
      '</div>'+
      '<div id="rpWarn"></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="saveRefundPolicy()">Save</button></div>',
    {wide:true, label:'Refund policy'});
}
function saveRefundPolicy(){
  const n=k=>parseFloat((document.getElementById(k)||{}).value||'0')||0;
  const sla=n('rpSla'), take=n('rpTake'), auto=n('rpAuto');
  const w=document.getElementById('rpWarn');
  if(take<sla){ if(w) w.innerHTML=banner('danger','<strong>The marketplace cannot take over before the '+
    'seller’s SLA has run out.</strong> That would remove a decision the seller was still entitled to make.');
    return; }
  const before=REFUND_POLICY.sellerSlaHours;
  REFUND_POLICY.sellerSlaHours=sla; REFUND_POLICY.escalateAfterHours=take; REFUND_POLICY.autoApproveBelow=auto;
  if(typeof audit==='function') audit('note.policy',{object:'Refund policy',
    before:before+'h', after:sla+'h',
    detail:'Seller SLA '+sla+'h, marketplace takes over at '+take+'h, auto-approve below '+CUR0(auto)});
  closeModal(); toast('Refund policy saved'); App.go(App.view);
}

function openRefund(id){
  const r=RFNMAP[id]; if(!r) return;
  const a=refundApprover(r);
  const ctx=authCtx();
  const canDecide = (ctx==='partner' && a.owner==='partner' && a.ownerId===ownerOfMe() && r.state==='requested') ||
                    (ctx==='operator' && a.owner==='operator' && (r.state==='requested'||r.state==='escalated'));
  openInspector('<div class="insp-head">'+ICO('refresh',18)+'<div class="grow">'+
    '<h3 class="t-sub">'+esc(r.id)+'</h3><div class="t-small muted">'+esc(r.item)+' · '+CUR(r.amount)+
    '</div></div>'+refundStatePill(r)+'</div>'+
  '<div class="insp-body stack">'+
    banner(a.owner==='operator'?'warning':'info',
      '<strong>'+(a.owner==='partner'?'The seller decides this one.':'The marketplace decides this one.')+
      '</strong> '+esc(a.why))+
    (refundOverdue(r)? banner('danger','<strong>Past the '+REFUND_POLICY.sellerSlaHours+
      '-hour response SLA.</strong> The marketplace may answer it, and the money still comes off the '+
      'seller’s settlement.'):'')+
    refundClockNote(r)+
    dl([['Order', r.order],
        ['Customer', r.customer],
        ['Sold by', r.firstParty?'The marketplace (first-party)':(r.sellerName||'—')],
        ['Part of a bundle', r.bundleId? (r.bundleName||r.bundleId) : 'No'],
        ['Reason given', refundReason(r.reason).label],
        ['Evidence expected', refundReason(r.reason).evidence],
        ['Evidence supplied', r.evidence||'None'],
        ['Requested', r.requested],
        ['Decided', r.decided? r.decided+' by '+(r.decidedBy||'—') : 'Not yet'],
        ['Escalated', r.state==='escalated'
          ? (r.escalatedAt||'—')+' by the platform — '+(r.escalatedWhy||'the response SLA')
          : 'No — the clock has not run out'],
        ['Recovered from', r.firstParty?'The marketplace':'The seller’s next settlement']])+
    '<p class="t-small">'+esc(r.note||'')+'</p>'+
  '</div>'+
  '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
    '<div class="spacer"></div>'+
    (canDecide?'<button class="btn" onclick="refundDecide(\''+r.id+'\',\'decline\')">Decline</button>'+
      '<button class="btn btn-primary" onclick="refundDecide(\''+r.id+'\',\'approve\')">Approve</button>':'')+
    ((ctx==='consumer'||ctx==='buyer') && !RFMAP[r.state].final && r.state!=='escalated'
      ?'<button class="btn" onclick="toast(\'Support request opened against '+esc(r.id)+'\')">Get help</button>':'')+
  '</div>', 'Refund '+r.id);
}

function refundDecide(id, pre){
  const r=RFNMAP[id]; if(!r) return;
  const a=refundApprover(r);
  openModal('<div class="modal-head">'+ICO('refresh',18)+'<div class="grow">'+
    '<h3 class="t-sub">Decide '+esc(r.id)+'</h3><div class="t-small muted">'+esc(r.item)+' · '+
    CUR(r.amount)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>'+esc(a.why)+'</strong>')+
      dl([['Reason given', refundReason(r.reason).label],
          ['Evidence', r.evidence||'None supplied'],
          ['Recovered from', r.firstParty?'The marketplace':(r.sellerName||'the seller')+'’s settlement']])+
      '<div class="field"><label for="rdWhat">Decision</label><select class="inp" id="rdWhat" '+
        'onchange="rdAmt()">'+
        '<option value="approve"'+(pre==='approve'?' selected':'')+'>Refund in full</option>'+
        '<option value="partial">Refund part of it</option>'+
        '<option value="decline"'+(pre==='decline'?' selected':'')+'>Decline</option>'+
        '</select></div>'+
      '<div class="field" id="rdAmtF" style="display:none"><label for="rdAmount">Amount to refund</label>'+
        '<input class="inp" id="rdAmount" type="number" min="0" step="0.01" max="'+r.amount+'" '+
        'value="'+(r.amount/2).toFixed(2)+'"></div>'+
      '<div class="field"><label for="rdWhy">What the customer will be told</label>'+
        '<textarea class="inp" id="rdWhy" rows="2" placeholder="A decline without a reason gets escalated, '+
        'and then decided by somebody else"></textarea></div>'+
      '<div id="rdWarn"></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="saveRefundDecision(\''+r.id+'\')">Record it</button></div>',
    {label:'Decide refund'});
  rdAmt();
}
function rdAmt(){
  const v=(document.getElementById('rdWhat')||{}).value;
  const f=document.getElementById('rdAmtF'); if(f) f.style.display = v==='partial'?'':'none';
  const w=document.getElementById('rdWarn'); if(!w) return;
  w.innerHTML = v==='decline'
    ? banner('warning','<strong>A decline can be escalated.</strong> If the marketplace overturns it, the '+
      'refund happens anyway and the reason you gave is on the record next to the reversal.')
    : v==='partial'
    ? banner('info','<strong>Say what the difference is for.</strong> A part refund with no explanation reads '+
      'as an arbitrary one.')
    : '';
}
function saveRefundDecision(id){
  const r=RFNMAP[id]; if(!r) return;
  const what=(document.getElementById('rdWhat')||{}).value||'approve';
  const why=((document.getElementById('rdWhy')||{}).value||'').trim();
  const w=document.getElementById('rdWarn');
  if(what==='decline' && !why){ if(w) w.innerHTML=banner('danger','<strong>A decline needs a reason.</strong> '+
    'Without one the customer escalates and somebody else decides it with less information than you have.');
    return; }
  let amt=r.amount;
  if(what==='partial'){
    amt=parseFloat((document.getElementById('rdAmount')||{}).value||'0')||0;
    if(amt<=0||amt>=r.amount){ if(w) w.innerHTML=banner('danger','A part refund must be above zero and '+
      'below the full amount.'); return; }
    if(!why){ if(w) w.innerHTML=banner('danger','Say what the difference is for.'); return; }
  }
  const who = authCtx()==='operator' ? 'Marketplace' : ((typeof ME_P!=='undefined'&&ME_P)?ME_P.name:'Seller');
  r.state = what==='approve'?'refunded' : what==='partial'?'partial' : 'declined';
  r.decided=TODAY; r.decidedBy='You ('+who+')';
  r.refundedAmount = what==='decline'? 0 : amt;
  r.decisionNote=why||null;
  if(typeof audit==='function') audit('refund.decided',{object:r.id, before:'requested', after:r.state,
    amount: what==='decline'?0:amt,
    detail:(what==='decline'?'Declined':what==='partial'?'Part refunded '+CUR(amt):'Refunded '+CUR(amt))+
      ' — '+(why||'no note')+'. Recovered from '+(r.firstParty?'the marketplace':(r.sellerName||'the seller')),
    sev: what==='decline'?'warn':'high'});
  closeModal(); closeInspector();
  toast(r.id+' '+(what==='decline'?'declined':what==='partial'?'part refunded':'refunded'),
        what==='decline'?'warn':'');
  App.go(App.view);
}
/* Escalation is a clock, not a button. A customer who has to know to press
   something in order to get a fair hearing is a customer we have quietly
   failed, so the platform escalates on the SLA and tells them it has. */
function refundHours(r){
  if(r.slaHours!=null) return r.slaHours;
  /* Never answered, so the clock is still running from when it was raised. */
  if(!r.requested) return null;
  const from=Date.parse(r.requested), now=Date.parse(TODAY);
  if(isNaN(from)||isNaN(now)) return null;
  return Math.max(0, Math.round((now-from)/36e5));
}
function refundEscalationDue(r){
  if(!r || r.state==='escalated') return false;
  if(r.state!=='requested' && r.state!=='declined') return false;
  /* A decline the seller could not evidence does not get to stand on the
     seller's say-so alone. */
  if(r.state==='declined' && !r.evidence) return true;
  const h=refundHours(r);
  return h!=null && h > REFUND_POLICY.escalateAfterHours;
}
function refundEscalationIn(r){
  const h=refundHours(r);
  if(h==null) return null;
  const left=REFUND_POLICY.escalateAfterHours-h;
  return left>0? left : 0;
}
/* Run wherever refunds are shown, so the state a person sees is the state the
   clock has actually produced rather than the last one a human touched. */
function refundSlaSweep(){
  const hit=REFUNDS.filter(refundEscalationDue);
  hit.forEach(r=>{
    const was=r.state;
    r.state='escalated'; r.decided=null; r.decidedBy=null;
    r.escalatedAt=TODAY+(typeof CLOCK!=='undefined'&&CLOCK?' '+CLOCK.hhmm:'');
    r.escalatedWhy = (was==='declined' && !r.evidence)
      ? 'Declined without evidence on file'
      : 'Unresolved '+refundHours(r)+' hours after it was raised, past the '+
        REFUND_POLICY.escalateAfterHours+'-hour clock';
    if(typeof audit==='function') audit('refund.decided',{object:r.id, before:was, after:'escalated',
      amount:r.amount, detail:'Escalated by the response SLA — no customer action'});
  });
  return hit;
}
/* What the customer is told instead of being handed an Escalate button. */
function refundClockNote(r){
  if(r.state==='escalated')
    return banner('info','<strong>This is with the marketplace now.</strong> '+
      esc(r.escalatedWhy||'The response SLA ran out.')+
      (r.escalatedAt?' — '+esc(r.escalatedAt):'')+'. Nobody had to ask for that.');
  if(RFMAP[r.state] && RFMAP[r.state].final && r.state!=='declined') return '';
  const left=refundEscalationIn(r);
  if(r.state==='declined')
    return banner('info','<strong>Declined by the seller, with a reason on record.</strong> '+
      'If the decline cannot be evidenced, or the request is still unresolved '+
      REFUND_POLICY.escalateAfterHours+' hours after it was raised, it comes to the marketplace '+
      'automatically. There is nothing for you to press.');
  if(left==null) return '';
  return banner(left<=12?'warning':'info','<strong>'+
    (left===0? 'The escalation clock has run out.'
             : 'Escalates to the marketplace in about '+Math.round(left)+' hours')+
    '</strong> if the seller has not answered by then. This happens on its own.');
}

function refundRequestDialog(){
  const mine=(typeof MY_ORDERS!=='undefined'?MY_ORDERS:ORDERS).slice(0,12);
  openModal('<div class="modal-head">'+ICO('refresh',18)+'<div class="grow">'+
    '<h3 class="t-sub">Request a refund</h3><div class="t-small muted">It goes to whoever sold it to you</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>'+esc(REFUND_POLICY.note)+'</strong> The seller has '+
        REFUND_POLICY.sellerSlaHours+' hours to answer. If they do not, we answer for them.')+
      '<div class="field"><label for="rqOrder">Which order</label><select class="inp" id="rqOrder" '+
        'onchange="rqPreview()">'+
        mine.map(o=>'<option value="'+o.id+'">'+esc(o.id)+' \u2014 '+esc(o.name||'Order')+
          ' \u00b7 '+CUR(o.gross||0)+'</option>').join('')+'</select></div>'+
      '<div class="field"><label for="rqReason">Why</label><select class="inp" id="rqReason" '+
        'onchange="rqPreview()">'+
        REFUND_REASONS.map(x=>'<option value="'+x.id+'">'+esc(x.label)+'</option>').join('')+'</select>'+
        '<p class="t-tiny muted" id="rqEvid"></p></div>'+
      '<div class="field"><label for="rqNote">Anything that would help</label>'+
        '<textarea class="inp" id="rqNote" rows="2"></textarea></div>'+
      '<div id="rqWarn"></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow" id="rqWho"></span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="submitRefundRequest()">Send it</button></div>',
    {label:'Request a refund'});
  rqPreview();
}
function rqPreview(){
  const oid=(document.getElementById('rqOrder')||{}).value;
  const o=ORDERS.filter(x=>x.id===oid)[0] || (typeof MY_ORDERS!=='undefined'?MY_ORDERS.filter(x=>x.id===oid)[0]:null) || {};
  const rid=(document.getElementById('rqReason')||{}).value||'';
  const e=document.getElementById('rqEvid');
  if(e) e.textContent='Usually supported by: '+refundReason(rid).evidence;
  const who=document.getElementById('rqWho');
  const seller=o.partnerId? (PMAP[o.partnerId]||{name:o.partnerId}).name : 'the marketplace';
  if(who) who.textContent='This goes to '+seller+', who has '+REFUND_POLICY.sellerSlaHours+' hours to answer';
}
function submitRefundRequest(){
  const oid=(document.getElementById('rqOrder')||{}).value;
  const o=ORDERS.filter(x=>x.id===oid)[0] || (typeof MY_ORDERS!=='undefined'?MY_ORDERS.filter(x=>x.id===oid)[0]:null);
  if(!o){ toast('Pick an order','warn'); return; }
  const rid=(document.getElementById('rqReason')||{}).value||'faulty';
  const note=((document.getElementById('rqNote')||{}).value||'').trim();
  const amt=o.gross||0;
  const why=[];
  if(amt < REFUND_POLICY.autoApproveBelow) why.push('below '+CUR0(REFUND_POLICY.autoApproveBelow)+
    ', where arguing costs more than refunding');
  if(REFUND_POLICY.autoApproveReasons.indexOf(rid)>=0)
    why.push(refundReason(rid).label.toLowerCase()+' is never a judgement call');
  const auto = why.length>0;
  const id='RFN-'+(3211+REFUNDS.length);
  const r={id:id, order:o.id, ctx:authCtx(), customer:o.buyer||'You',
    sellerId:o.partnerId||null,
    sellerName:o.partnerId?(PMAP[o.partnerId]||{name:o.partnerId}).name:'Marketplace',
    bundleId:null, firstParty:!o.partnerId, item:o.name||('Order '+o.id),
    amount:+(+amt).toFixed(2), currency:'USD', reason:rid, requested:TODAY,
    state: auto?'refunded':'requested', decidedBy: auto?'Auto':null, decided: auto?TODAY:null,
    slaHours: auto?0:null, evidence:note||null, isNew:true,
    note: auto? 'Auto-approved \u2014 '+why.join(', and ')+'.'
        : note||'Awaiting the seller\u2019s decision.'};
  REFUNDS.push(r); RFNMAP[id]=r;
  if(typeof audit==='function') audit('refund.requested',{object:id, after:r.state, amount:r.amount,
    detail:refundReason(rid).label+' on '+o.id+' — '+(auto?'auto-approved':'sent to '+r.sellerName)});
  closeModal();
  toast(auto? id+' refunded — that reason never needs a decision'
            : id+' sent to '+r.sellerName+', who has '+REFUND_POLICY.sellerSlaHours+' hours to answer');
  App.go(App.view);
}

/* What sellers are doing with the policy we handed them. Drift is the useful
   signal here: a seller who has doubled every interval is telling us their
   customers are not like the ones the default was written for. */
function sellerLaddersPanel(){
  const rows=DUNNING_LADDERS.filter(l=>l.owner==='partner');
  const edited=rows.filter(l=>l.edited);
  const noLadder=PARTNERS.filter(p=>p.status==='live' && !partnerLadders(p.id).length);
  return panel('Seller ladders',
    banner('info','<strong>Every seller is given a ladder at onboarding, chosen from the category they sell in.</strong> '+
      'They may run it as it stands, edit it, or add more. Whatever they end up with appears here, because a '+
      'marketplace that cannot see how its sellers chase a shared customer cannot answer a complaint about it.')+
    (noLadder.length? banner('warning','<strong>'+noLadder.map(p=>esc(p.name)).join(', ')+
      ' '+(noLadder.length===1?'has':'have')+' no ladder of their own.</strong> Their direct receivables run '+
      'on the marketplace default, which is safe but not tailored.'):'')+
    '<div class="tablewrap"><table class="tbl"><thead><tr><th style="min-width:150px">Seller</th>'+
      '<th style="min-width:150px">Ladder</th><th>From profile</th><th>Customer type</th>'+
      '<th class="num">Suspends</th><th class="num">Cases</th><th>State</th>'+
      '<th style="width:86px"></th></tr></thead><tbody>'+
    (rows.length? rows.map(l=>{
      const p=PMAP[l.ownerId]||{name:l.ownerId}, susp=ladderSuspendDay(l);
      const prof=LPMAP[l.fromProfile];
      const base=prof?(prof.ladders.filter(t=>l.id.slice(-3)===t.suffix)[0]||null):null;
      const baseSusp=base?(base.steps.filter(x=>x.action==='suspend')[0]||{}).at:null;
      const drift=(baseSusp!=null && susp!=null && susp!==baseSusp)?(susp-baseSusp):null;
      return '<tr><td><div class="cellmain">'+esc(p.name)+'</div>'+
        '<div class="cellsub">'+esc((p.verticals&&VMAP[p.verticals[0]]?VMAP[p.verticals[0]].name:'—'))+'</div></td>'+
        '<td class="t-small">'+esc(l.name)+'</td>'+
        '<td class="t-small">'+(prof?esc(prof.name):'<span class="dim">Written from scratch</span>')+'</td>'+
        '<td class="t-small">'+(l.segment==null?'Any'
          :esc((DUN_SEGMENTS.filter(x=>x.id===l.segment)[0]||{}).label||l.segment))+'</td>'+
        '<td class="num t-num">'+(susp==null?'<span class="dim">Never</span>':'Day '+susp)+
          (drift?'<div class="cellsub t-tiny">'+(drift>0?'+':'')+drift+' vs default</div>':'')+'</td>'+
        '<td class="num t-num">'+(ladderCases(l.id).length||'<span class="dim">None</span>')+'</td>'+
        '<td>'+(l.edited?pill('warn','Edited'):pill('ok','As provided'))+'</td>'+
        '<td class="rowend"><button class="btn btn-sm btn-quiet" onclick="ladderDialog(\''+l.id+'\')">View</button></td>'+
      '</tr>';
    }).join('')
      : '<tr><td colspan="8" class="t-small muted">No seller has published a ladder yet.</td></tr>')+
    '</tbody></table></div>',
    {icon:'group', sub:rows.length+' seller ladders · '+edited.length+' edited from the default',
     acts:'<button class="btn btn-sm" onclick="ladderProfilesDialog()">Default profiles</button>'});
}

