/* ==========================================================================
   50. BUYER INTEGRATION (M40)
   --------------------------------------------------------------------------
   AP-PTY was published to "sellers and enterprise buyers" while the buyer
   console had no door to it at all. A procurement team does not browse a
   storefront: a requisition starts in their ERP and has to reach us without
   somebody re-keying it.

   The constraint worth building rather than assuming: an order raised through
   the API is subject to the same approval policy as one raised in the portal.
   An integration that could bypass the threshold would be a way to route
   around the buyer's own finance function, using our API to do it.
   ========================================================================== */

function buyerApis(){
  return API_PRODUCTS.filter(p=>/buyer/i.test(p.audience));
}

function buyerIntegrationView(){
  const apis=buyerApis();
  const thr=(typeof APPROVAL_POLICY!=='undefined')?APPROVAL_POLICY.threshold:0;
  return pagehead('Integration',
    'Reach the marketplace from your own systems · '+apis.length+' APIs · sandbox before production',
    exportBtn('APIs','dtBApi')+
    '<button class="btn btn-primary" onclick="buyerKeyDialog()">'+ICO('key',13)+'Request credentials</button>')+
  '<div class="stack">'+

  banner('warning','<strong>An order raised through the API follows your approval policy exactly as one raised '+
    'here does.</strong> Above '+CUR0(thr)+' it returns an approval reference rather than an order, and it waits '+
    'for the same person. The API is not a route around your own threshold, and an attempt to use it as one is '+
    'refused and recorded on your audit log.')+

  '<div class="grid g4">'+
    metric({icon:'plug',label:'APIs available to you',value:String(apis.length),
      foot:'All generally available'})+
    metric({icon:'shield',label:'Approval threshold',value:CUR0(thr),
      foot:'Applies to API orders identically'})+
    metric({icon:'wallet',label:'Contract pricing',value:'Applied',
      foot:'Your rates, resolved per call'})+
    metric({icon:'lock',label:'Credentials',value:'Not issued',
      foot:'Request them to start in sandbox'})+
  '</div>'+

  panel('What you can integrate', dt('dtBApi',{
    rows:apis, noun:'APIs', pageSize:10, idKey:'id', toolbar:false,
    columns:[
      {key:'name',label:'API',render:r=>'<div class="cellmain">'+esc(r.name)+'</div>'+
        '<div class="cellsub">'+esc(r.blurb)+'</div>'},
      {key:'spec',label:'Standard',render:r=>'<span class="t-small t-num">'+esc(r.spec)+'</span>'},
      {key:'version',label:'Version',render:r=>'<span class="t-num">'+esc(r.version)+'</span>'},
      {key:'methods',label:'Operations',align:'right',render:r=>'<span class="t-num">'+r.methods+'</span>'},
      {key:'status',label:'State',render:r=>r.status==='ga'?pill('ok','Generally available')
        :pill('warn',r.status)},
      {key:'_a',label:'',align:'right',render:r=>'<span class="rowend">'+
        '<button class="btn btn-sm btn-quiet" onclick="buyerApiDetail(\''+r.id+'\')">Detail</button></span>'}
    ]}),
    {flush:true, icon:'plug',
     sub:'Built to TMForum Open API specifications, so an ERP connector written against the standard '+
         'mostly works without modification'})+

  panel('Environments',
    '<div class="tablewrap"><table class="tbl"><thead><tr><th>Environment</th><th>Base URL</th>'+
      '<th>What the data is</th><th>What we commit to</th></tr></thead><tbody>'+
    API_ENVS.map(e=>'<tr><td class="cellmain">'+esc(e.label)+'</td>'+
      '<td class="t-small t-num">'+esc(e.base)+'</td>'+
      '<td class="t-small">'+esc(e.data)+'</td>'+
      '<td class="t-small">'+esc(e.commitment)+'</td></tr>').join('')+
    '</tbody></table></div>'+
    '<p class="t-tiny muted" style="margin-top:9px">Sandbox first, always. It carries your contract prices so '+
      'a connector can be proved against the numbers you will actually see, rather than against list.</p>',
    {icon:'server', sub:'Sandbox has no availability commitment'})+

  panel('Before you build',
    '<div class="stack" style="gap:9px">'+
    [['Your prices are yours','The catalogue API resolves contract pricing per account. Caching a response '+
      'across accounts will show one customer another customer’s rate, which is a contractual problem '+
      'rather than a bug.'],
     ['An approval is not a failure','An order above your threshold returns an approval reference, not an '+
      'order id. Treating that as an error is the most common mistake we see, and it makes a buyer think the '+
      'integration is broken when it is working correctly.'],
     ['Orders are idempotent on your reference','Send your own purchase order number. A retry with the same '+
      'reference returns the original order rather than raising a second one.'],
     ['We do not push into your ERP','You poll, or you subscribe to events. We will not hold credentials to '+
      'a customer’s finance system.']].map(x=>
      '<div><div class="t-small strong">'+esc(x[0])+'</div>'+
      '<div class="t-small muted">'+esc(x[1])+'</div></div>').join('')+
    '</div>',
    {icon:'info', sub:'The four things that cause most integration tickets'})+
  '</div>';
}

