/* ==========================================================================
   37. TECHNICAL READINESS AS A TESTED MILESTONE
   --------------------------------------------------------------------------
   API registration belongs inside onboarding, not beside it. The technical
   gate is not "did they say they have an endpoint" — it is four things the
   marketplace can verify for itself:

     1. an endpoint registered for every event their fulfilment model requires
     2. authentication that is not "none"
     3. a signed test call acknowledged, per endpoint
     4. one sandbox order carried end to end

   Until all four hold, the gate cannot be cleared. A seller who goes live
   with an unproven integration produces a customer-facing failure on day one,
   and the person who cleared the gate is the one who caused it.
   ========================================================================== */

const TECH_CHECKS = [
  {id:'registered', label:'Endpoints registered for every required event',
   why:'A required event with nowhere to go is not queued and not retried. It does not arrive.'},
  {id:'auth',       label:'Every endpoint authenticates',
   why:'Order payloads carry buyer data. An unauthenticated endpoint is a data leak with a URL.'},
  {id:'tested',     label:'A signed test call acknowledged on each endpoint',
   why:'Registration proves intent. An acknowledgement proves it works.'},
  {id:'sandbox',    label:'One sandbox order completed end to end',
   why:'The single requirement that removes most go-live failures.'}
];

/* Sandbox orders run during onboarding, per partner. */
const SANDBOX_RUNS = {};

function techStatus(pid){
  const eps=pepFor(pid).filter(e=>e.enabled);
  const required=pepRequiredFor(pid);
  const handled=pepHandled(pid);
  const missing=required.filter(e=>!handled[e.id]);
  const noAuth=eps.filter(e=>!e.auth || e.auth==='None');
  const untested=eps.filter(e=>!CALLBACK_LOG.some(c=>c.endpoint===e.id && c.status==='acknowledged'));
  const run=SANDBOX_RUNS[pid];
  return {
    eps:eps, required:required, missing:missing, noAuth:noAuth, untested:untested, run:run,
    checks:{
      registered: eps.length>0 && missing.length===0,
      auth:       eps.length>0 && noAuth.length===0,
      tested:     eps.length>0 && untested.length===0,
      sandbox:    !!(run && run.state==='passed')
    }
  };
}
function techReady(pid){
  const c=techStatus(pid).checks;
  return TECH_CHECKS.every(x=>c[x.id]);
}

/* The gate panel, shown inside the onboarding record. */
function techGatePanel(pid){
  const p=PMAP[pid]||{name:pid};
  const t=techStatus(pid);
  const done=TECH_CHECKS.filter(c=>t.checks[c.id]).length;
  return panel('Integration milestone',
    (techReady(pid)
      ? banner('success','<strong>All four checks pass.</strong> The integration has been proved against a real '+
        'flow, so the technical gate can be cleared.')
      : banner('warning','<strong>'+done+' of '+TECH_CHECKS.length+' checks pass.</strong> The technical gate '+
        'cannot be cleared until all four do. This is not paperwork — each one is verified by the marketplace, '+
        'not asserted by the seller.'))+
    '<ul class="ticklist">'+TECH_CHECKS.map(c=>{
      const okc=t.checks[c.id];
      let detail=c.why;
      if(c.id==='registered'&&!okc) detail = t.eps.length
        ? 'Missing: '+t.missing.map(m=>esc(m.label)).join(', ')+'. '+c.why
        : 'Nothing registered yet. '+c.why;
      if(c.id==='auth'&&!okc)    detail = t.noAuth.length+' endpoint'+(t.noAuth.length===1?'':'s')+
        ' with no authentication. '+c.why;
      if(c.id==='tested'&&!okc)  detail = t.untested.length+' endpoint'+(t.untested.length===1?'':'s')+
        ' never acknowledged a test call. '+c.why;
      if(c.id==='sandbox'&&!okc) detail = (t.run? 'Last run '+esc(t.run.state)+'. ' : 'Not run yet. ')+c.why;
      return '<li>'+ICO(okc?'check':'circle',15)+'<div class="grow">'+
        '<strong'+(okc?'':' class="warntext"')+'>'+esc(c.label)+'</strong> '+
        (okc?pill('ok','Passed'):pill('warn','Outstanding'))+
        '<div class="t-small muted">'+detail+'</div></div></li>';
    }).join('')+'</ul>'+
    (t.eps.length
      ? '<div class="divider"></div><h4 class="t-sub">Registered endpoints</h4>'+
        '<ul class="ticklist">'+t.eps.map(e=>
          '<li>'+ICO('plug',14)+'<div class="grow"><strong>'+esc(e.name)+'</strong> '+pepHealth(e)+
          '<div class="t-tiny muted t-num">'+esc(e.url)+'</div>'+
          '<div class="t-tiny muted">'+esc(e.auth)+' · '+e.events.length+' events</div></div>'+
          '<button class="btn btn-sm" onclick="pepTest(\''+e.id+'\')">Test</button></li>').join('')+'</ul>'
      : banner('info','No endpoints registered. The seller adds them in their own console under Integrations, '+
        'or the onboarding desk can register them on their behalf.'))+
    '<div class="rowend">'+
      '<button class="btn btn-sm" onclick="registerPartnerEndpoint(\''+pid+'\')">Register an endpoint</button>'+
      '<button class="btn btn-sm'+(t.checks.registered&&t.checks.auth?' btn-primary':'')+
        '" onclick="runSandboxOrder(\''+pid+'\')">Run the sandbox order</button>'+
    '</div>',
    {icon:'plug', sub:done+' of '+TECH_CHECKS.length+' verified · '+esc(p.name)});
}

/* Register an endpoint on the partner's behalf, from the onboarding desk. */
function registerPartnerEndpoint(pid){
  const p=PMAP[pid]||{name:pid};
  const need=pepRequiredFor(pid);
  const handled=pepHandled(pid);
  const missing=need.filter(e=>!handled[e.id]);
  openModal('<div class="modal-head">'+ICO('plug',18)+'<div class="grow"><h3 class="t-sub">Register an endpoint</h3>'+
    '<div class="t-small muted">'+esc(p.name)+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','The marketplace calls this URL. The seller never polls us. Register it here only when the '+
        'seller has given you the detail in writing — an endpoint typed from a phone call is a support case.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="peName">Name</label>'+
          '<input class="inp" id="peName" placeholder="Order and fulfilment" data-autofocus></div>'+
        '<div class="field"><label for="peEnv">Environment</label><select class="inp" id="peEnv">'+
          API_ENVS.map(e=>'<option>'+esc(e.label)+'</option>').join('')+'</select></div>'+
      '</div>'+
      '<div class="field"><label for="peUrl">URL</label>'+
        '<input class="inp" id="peUrl" placeholder="https://api.seller.example/marketplace/orders"></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="peAuth">Authentication</label><select class="inp" id="peAuth">'+
          API_AUTH.filter(a=>a!=='None').map(a=>'<option>'+esc(a)+'</option>').join('')+
          '<option>None</option></select>'+
          '<p class="t-tiny muted">Unauthenticated endpoints are accepted here but fail the integration '+
          'milestone, so the gate will not clear.</p></div>'+
        '<div class="field"><label for="peRetry">Retry policy</label><select class="inp" id="peRetry">'+
          API_RETRY.map(a=>'<option>'+esc(a)+'</option>').join('')+'</select></div>'+
      '</div>'+
      '<div class="field"><label>Events routed here</label>'+
        (missing.length?'<p class="t-tiny warntext">Still unhandled and required: '+
          missing.map(m=>esc(m.label)).join(', ')+'</p>':'')+
        '<div class="checkgrid">'+API_EVENTS.map(e=>
          '<label class="checkline"><input type="checkbox" class="peEv" value="'+e.id+'"'+
          (missing.some(m=>m.id===e.id)?' checked':'')+'>'+
          '<span>'+esc(e.label)+(e.required?' <span class="t-tiny muted">required</span>':'')+'</span></label>').join('')+
        '</div></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">Recorded against your name in the onboarding trail</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="savePartnerEndpoint(\''+pid+'\')">Register it</button></div>',
    {wide:true,label:'Register an endpoint'});
}
function savePartnerEndpoint(pid){
  const g=k=>(document.getElementById(k)||{}).value||'';
  const evs=Array.prototype.slice.call(document.querySelectorAll('.peEv'))
    .filter(c=>c.checked).map(c=>c.value);
  const name=g('peName').trim(), url=g('peUrl').trim();
  if(!name||!url){ toast('An endpoint needs a name and a URL','warn'); return; }
  if(!/^https:\/\//.test(url)){ toast('The URL must be https — order payloads carry buyer data','warn'); return; }
  if(!evs.length){ toast('Route at least one event to it','warn'); return; }
  const p=PMAP[pid]||{name:pid};
  closeModal();
  PARTNER_ENDPOINTS.push({
    id:'PEP-'+(300+PARTNER_ENDPOINTS.length), partnerId:pid, partner:p.name,
    name:name, url:url, method:'POST', events:evs,
    auth:g('peAuth'), retry:g('peRetry'), timeoutMs:5000,
    env:g('peEnv'), enabled:true, health:'unknown', lastCall:'Never', successRate:null, p95:0,
    registered:TODAY, verifiedBy:((typeof orgUsers==='function'&&
      (orgUsers('operator').filter(u=>u.you)[0]||{}).name)||'Onboarding desk'),
    note:'Registered by the onboarding desk on the seller’s behalf.', isNew:true
  });
  if(typeof audit==='function') audit('api.endpoint',{object:p.name+' · '+name,
    detail:'Endpoint registered during onboarding · '+evs.length+' events'});
  toast(name+' registered — it must acknowledge a test call before the gate can clear');
  App.go(App.view);
}

/* The sandbox order. It runs against whatever is registered, and it fails
   honestly when the integration is not ready. */
function runSandboxOrder(pid){
  const p=PMAP[pid]||{name:pid};
  const t=techStatus(pid);
  confirmAction({
    title:'Run the sandbox order', subtitle:p.name,
    confirmLabel:'Run it',
    body:banner('info','A test order is placed in the sandbox and driven to completion: created, '+
      'acknowledged, fulfilled, settled. Every registered endpoint is called in sequence with a signed payload.'),
    impact:['It runs against sandbox records. No customer and no money are involved.',
            'Each endpoint must acknowledge within its stated timeout.',
            'The result is recorded against the technical gate and cannot be edited afterwards.',
            t.checks.registered ? 'All required events have an endpoint.'
                                : 'Required events are still unhandled, so this run will fail on those steps.'],
    onConfirm:()=>{
      const steps=[
        {id:'order.created',        label:'Order placed in the sandbox'},
        {id:'fulfilment.requested', label:'Fulfilment requested'},
        {id:'subscription.activated',label:'Entitlement started'},
        {id:'settlement.ready',     label:'Statement issued'}
      ];
      const handled=pepHandled(pid);
      const results=steps.map(s=>{
        const applies = pepRequiredFor(pid).some(x=>x.id===s.id) || s.id==='order.created';
        if(!applies) return Object.assign({}, s, {state:'skipped', why:'Not applicable to this seller.'});
        if(!handled[s.id]) return Object.assign({}, s, {state:'failed', why:'No endpoint handles this event.'});
        const ep=pepFor(pid).filter(e=>e.enabled && e.events.indexOf(s.id)>-1)[0];
        if(ep && ep.health==='failing')
          return Object.assign({}, s, {state:'failed', why:esc(ep.name)+' did not acknowledge.'});
        if(ep && (!ep.auth || ep.auth==='None'))
          return Object.assign({}, s, {state:'failed', why:'Endpoint is unauthenticated.'});
        return Object.assign({}, s, {state:'passed', why:'Acknowledged in '+(120+Math.round(Math.random()*400))+' ms.'});
      });
      const failed=results.filter(x=>x.state==='failed');
      SANDBOX_RUNS[pid]={when:TODAY, state:failed.length?'failed':'passed', steps:results,
        by:((typeof orgUsers==='function'&&(orgUsers('operator').filter(u=>u.you)[0]||{}).name)||'Onboarding desk')};
      /* A passing run counts as an acknowledgement for the endpoints it touched. */
      if(!failed.length){
        pepFor(pid).filter(e=>e.enabled).forEach(e=>{
          CALLBACK_LOG.unshift({id:'CB-'+(70400+CALLBACK_LOG.length), endpoint:e.id, partner:p.name,
            partnerId:pid, event:e.events[0], ref:'SANDBOX', when:'Just now', attempts:1,
            status:'acknowledged', code:200, ms:180, outcome:'Acknowledged during the sandbox order.'});
          if(e.health==='unknown'){ e.health='healthy'; e.successRate=100; e.lastCall='Just now'; }
        });
      }
      if(typeof audit==='function') audit('api.test',{object:p.name,
        detail:'Sandbox order '+(failed.length?'failed at '+failed.length+' step(s)':'completed end to end'),
        sev:failed.length?'warn':'notice'});
      toast(failed.length? 'Sandbox order failed at '+failed.length+' step'+(failed.length===1?'':'s')
                         : 'Sandbox order completed end to end');
      App.go(App.view);
    }
  });
}

function sandboxRunPanel(pid){
  const run=SANDBOX_RUNS[pid];
  if(!run) return '';
  return panel('Sandbox order — '+run.state,
    (run.state==='passed'
      ? banner('success','<strong>Completed end to end on '+esc(run.when)+'.</strong> Run by '+esc(run.by)+'.')
      : banner('danger','<strong>Failed on '+esc(run.when)+'.</strong> The steps below say where. Fix the cause '+
        'and run it again — the gate reads the latest run, not the best one.'))+
    '<ul class="ticklist">'+run.steps.map(s=>
      '<li>'+ICO(s.state==='passed'?'check':s.state==='skipped'?'dash':'warning',14)+
      '<div class="grow"><strong>'+esc(s.label)+'</strong> '+
      (s.state==='passed'?pill('ok','Passed'):s.state==='skipped'?pill('','Not applicable'):pill('down','Failed'))+
      '<div class="t-small muted">'+esc(s.why)+'</div></div></li>').join('')+'</ul>',
    {icon:'play', sub:'Latest run'});
}

/* ==========================================================================
   38. OPERATOR-LED ONBOARDING
   --------------------------------------------------------------------------
   Not every seller self-serves. A large one negotiated in a meeting room, an
   acquisition, or a partner without the appetite to fill in a portal — the
   desk captures the same detail on their behalf.

   The same detail, and the same gates. Capturing it here skips the typing,
   never the verification: KYC, agreements, bank and the integration milestone
   all still have to clear. An onboarding path that also skipped the checks
   would be a way round the controls rather than a convenience.
   ========================================================================== */

/* Operator-led onboarding.

   The desk is capturing what the seller would otherwise have typed, which means
   it has to be able to capture all of it — including the settlement instruction
   and the documents each gate expects. A form that collects a company name and
   a free-text "Bank" leaves the finance gate with nothing to verify, and the
   desk discovers that a week later.

   Five steps, mirroring the gates. Capturing detail never clears a gate: the
   evidence still has to be checked by whoever owns it. */
const OO = {step:0, docs:[]};
const OO_STEPS = ['Company','Contacts and categories','Settlement','Documents','Reason and review'];
function ooReset(){
  OO.step=0; OO.docs=[]; OO.files={};
}
function operatorOnboardDialog(){
  ooReset();
  openModal(ooShell(), {wide:true, label:'Onboard a partner'});
}
function ooGo(n){
  const el=document.getElementById('modalHost');
  OO.step=Math.max(0,Math.min(n,OO_STEPS.length-1));
  if(el){ ooCapture(); el.innerHTML=ooShell(); ooRestore();
    const f=el.querySelector('[data-autofocus]'); if(f) f.focus(); }
}
/* Values survive a step change because they live on OO, not in the DOM. */
function ooCapture(){
  ['ooName','ooType','ooCountry','ooReg','ooContact','ooEmail','ooPhone','ooVol','ooPlan',
   'ooHolder','ooBank','ooBranch','ooAcct','ooAcct2','ooLocal','ooSwift','ooIban','ooCur',
   'ooTaxId','ooTaxRes','ooTreaty','ooEp','ooWhy'].forEach(k=>{
    const el=document.getElementById(k); if(el) OO[k]=el.value;
  });
  const vs=Array.prototype.slice.call(document.querySelectorAll('.ooV'));
  if(vs.length) OO.verticals=vs.filter(c=>c.checked).map(c=>c.value);
  const tc=document.getElementById('ooTreatyOn'); if(tc) OO.treatyOn=tc.checked;
  /* Attached files live on OO already — a step change must not drop them. */
}
function ooRestore(){ /* values are written straight into the markup */ }
function ooV(k, d){ return OO[k]!=null ? OO[k] : (d||''); }
function ooShell(){
  const step=OO.step;
  return '<div class="modal-head">'+ICO('userplus',18)+
    '<div class="grow"><h3 class="t-sub">Onboard a partner yourself</h3>'+
    '<div class="t-small muted">Step '+(step+1)+' of '+OO_STEPS.length+' · '+esc(OO_STEPS[step])+
    '</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
  '<div class="modal-body stack">'+
    '<div class="pipe">'+OO_STEPS.map((n,i)=>
      '<div class="step '+(i<step?'done':i===step?'now':'todo')+'">'+
      '<div class="dot" aria-hidden="true">'+(i<step?SH('check',11):(i+1))+'</div>'+
      '<div class="lbl">'+esc(n)+'</div></div>').join('')+'</div>'+
    '<div class="divider"></div>'+
    ooBody(step)+
  '</div>'+
  '<div class="modal-foot">'+
    '<span class="t-tiny muted grow">Capturing detail never clears a gate — every one still has to be '+
      'verified by whoever owns it</span>'+
    (step>0?'<button class="btn btn-quiet" onclick="ooGo('+(step-1)+')">'+ICO('chevleft',13)+
      'Back</button>':'<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>')+
    (step<OO_STEPS.length-1
      ? '<button class="btn btn-primary" onclick="ooGo('+(step+1)+')">Continue'+ICO('chevright',13)+'</button>'
      : '<button class="btn btn-primary" onclick="saveOperatorOnboard()">Create the application</button>')+
  '</div>';
}
function ooBody(step){
  const types=['Content provider','Device OEM','Security ISV','IoT hardware','Insurance','Reseller','MVNO'];
  const country=ooV('ooCountry');
  const c=(typeof bankCodeFor==='function')? bankCodeFor(country) : {local:'Local clearing code',
    localEg:'—', tax:'Tax identifier', taxEg:'—', iban:true};

  if(step===0) return ''+
    banner('info','<strong>This records the application on the seller’s behalf. It clears nothing.</strong> '+
      'KYC, agreements, bank and tax, and the technical milestone all still have to be verified. Use it '+
      'when the detail arrived in a meeting or a contract rather than through the portal.')+
    '<div class="grid g2">'+
      '<div class="field"><label for="ooName">Legal entity name</label>'+
        '<input class="inp" id="ooName" data-autofocus value="'+esc(ooV('ooName'))+
        '" placeholder="As it appears on the register"></div>'+
      '<div class="field"><label for="ooType">Type</label><select class="inp" id="ooType">'+
        types.map(t=>'<option'+(ooV('ooType')===t?' selected':'')+'>'+esc(t)+'</option>').join('')+
        '</select></div>'+
      '<div class="field"><label for="ooCountry">Country of registration</label>'+
        '<select class="inp" id="ooCountry" onchange="ooGo('+OO.step+')">'+
        ['','India','UAE','Kenya','Singapore','Germany','Poland','Brazil','Vietnam',
         'United Kingdom','United States'].map(k=>'<option value="'+esc(k)+'"'+
          (ooV('ooCountry')===k?' selected':'')+'>'+esc(k||'Select a country')+'</option>').join('')+
        '</select><div class="hint">It decides which clearing code and tax identifier we ask for.</div></div>'+
      '<div class="field"><label for="ooReg">Registration number</label>'+
        '<input class="inp" id="ooReg" value="'+esc(ooV('ooReg'))+
        '" placeholder="CIN, company number or equivalent"></div>'+
    '</div>';

  if(step===1) return ''+
    '<h4 class="t-sub">Who we deal with</h4>'+
    '<div class="grid g3">'+
      '<div class="field"><label for="ooContact">Primary contact</label>'+
        '<input class="inp" id="ooContact" data-autofocus value="'+esc(ooV('ooContact'))+
        '" placeholder="Someone who can sign"></div>'+
      '<div class="field"><label for="ooEmail">Email</label>'+
        '<input class="inp" id="ooEmail" type="email" value="'+esc(ooV('ooEmail'))+
        '" placeholder="name@6dtech.co.in"></div>'+
      '<div class="field"><label for="ooPhone">Telephone</label>'+
        '<input class="inp" id="ooPhone" value="'+esc(ooV('ooPhone'))+'" placeholder="+91 80 4111 2200"></div>'+
    '</div>'+
    '<div class="divider"></div>'+
    '<h4 class="t-sub">What they will sell</h4>'+
    '<div class="field"><label>Marketplace categories</label>'+
      '<div class="checkgrid">'+VERTICALS.map(v=>
        '<label class="checkline"><input type="checkbox" class="ooV" value="'+v.id+'"'+
        (((OO.verticals||[]).indexOf(v.id)>-1)?' checked':'')+'>'+
        '<span>'+esc(v.name)+'</span></label>').join('')+'</div></div>'+
    '<div class="grid g2">'+
      '<div class="field"><label for="ooVol">Expected orders a month</label>'+
        '<input class="inp" id="ooVol" type="number" min="0" value="'+esc(ooV('ooVol'))+
        '" placeholder="500"></div>'+
      '<div class="field"><label for="ooPlan">Commission plan</label><select class="inp" id="ooPlan">'+
        '<option value="">Decide at the commercial gate</option>'+
        COMM_PLANS.map(x=>'<option value="'+x.id+'"'+(ooV('ooPlan')===x.id?' selected':'')+'>'+
          esc(x.name)+'</option>').join('')+'</select></div>'+
    '</div>'+
    '<div class="divider"></div>'+
    '<div class="field"><label for="ooEp">Fulfilment endpoint, if they already have one</label>'+
      '<input class="inp" id="ooEp" value="'+esc(ooV('ooEp'))+
      '" placeholder="https://api.seller.example/marketplace/orders">'+
      '<div class="hint">Optional. Whatever is entered still has to acknowledge a test call and pass a '+
      'sandbox order before the technical gate clears.</div></div>';

  if(step===2) return ''+
    banner('warning','<strong>This is where the money goes, so it is captured properly and shown masked '+
      'afterwards.</strong> Recording it does not verify it — two micro-deposits still have to be matched '+
      'before a settlement run will pay to this account.')+
    '<div class="grid g2">'+
      '<div class="field"><label for="ooHolder">Account holder, exactly as the bank has it</label>'+
        '<input class="inp" id="ooHolder" data-autofocus value="'+esc(ooV('ooHolder'))+
        '" placeholder="'+esc(ooV('ooName')||'Legal entity name')+'">'+
        '<div class="hint">A mismatch against the registered name is the most common reason a first '+
        'payout bounces.</div></div>'+
      '<div class="field"><label for="ooBank">Bank</label>'+
        '<input class="inp" id="ooBank" value="'+esc(ooV('ooBank'))+'" placeholder="HDFC Bank"></div>'+
      '<div class="field"><label for="ooBranch">Branch</label>'+
        '<input class="inp" id="ooBranch" value="'+esc(ooV('ooBranch'))+
        '" placeholder="Bengaluru — Residency Road"></div>'+
      '<div class="field"><label for="ooCur">Settlement currency</label>'+
        '<select class="inp" id="ooCur">'+['USD','EUR','GBP','INR','AED','KES','SGD']
          .map(x=>'<option'+(ooV('ooCur','USD')===x?' selected':'')+'>'+x+'</option>').join('')+
        '</select></div>'+
    '</div>'+
    '<div class="grid g2">'+
      '<div class="field"><label for="ooAcct">Account number</label>'+
        '<input class="inp" id="ooAcct" value="'+esc(ooV('ooAcct'))+'" placeholder="Digits only"></div>'+
      '<div class="field"><label for="ooAcct2">Confirm the account number</label>'+
        '<input class="inp" id="ooAcct2" value="'+esc(ooV('ooAcct2'))+'" placeholder="Type it again">'+
        '<div class="hint">Typed twice on purpose. Nobody proof-reads a number they pasted.</div></div>'+
    '</div>'+
    '<div class="grid g3">'+
      '<div class="field"><label for="ooLocal">'+esc(c.local)+'</label>'+
        '<input class="inp" id="ooLocal" value="'+esc(ooV('ooLocal'))+'" placeholder="'+esc(c.localEg)+'"></div>'+
      '<div class="field"><label for="ooSwift">SWIFT / BIC</label>'+
        '<input class="inp" id="ooSwift" value="'+esc(ooV('ooSwift'))+'" placeholder="HDFCINBB"></div>'+
      (c.iban
        ? '<div class="field"><label for="ooIban">IBAN</label>'+
          '<input class="inp" id="ooIban" value="'+esc(ooV('ooIban'))+'" placeholder="AE07 0331 2345 6789 0123 456"></div>'
        : '<div class="field"><label>IBAN</label><input class="inp" disabled value="Not used in '+
          esc(country||'this country')+'"></div>')+
    '</div>'+
    '<div class="divider"></div>'+
    '<h4 class="t-sub">Tax</h4>'+
    '<div class="grid g3">'+
      '<div class="field"><label for="ooTaxRes">Tax residency</label>'+
        '<input class="inp" id="ooTaxRes" value="'+esc(ooV('ooTaxRes')||country)+
        '" placeholder="Jurisdiction for withholding"></div>'+
      '<div class="field"><label for="ooTaxId">'+esc(c.tax)+'</label>'+
        '<input class="inp" id="ooTaxId" value="'+esc(ooV('ooTaxId'))+'" placeholder="'+esc(c.taxEg)+'"></div>'+
      '<div class="field"><label for="ooTreaty">Treaty certificate valid to</label>'+
        '<input class="inp" id="ooTreaty" value="'+esc(ooV('ooTreaty'))+'" placeholder="31 Mar 2027">'+
        '<div class="hint">Blank means the statutory rate is withheld at source.</div></div>'+
    '</div>';

  if(step===3){
    const need=[['Certificate of incorporation','kyc'],['Beneficial ownership declaration','kyc'],
                ['Director identification','kyc'],['Marketplace terms — countersigned','agree'],
                ['Data processing agreement','agree'],['Bank verification letter','finance'],
                ['Tax residency certificate','finance'],['Security questionnaire','assure']];
    const held=OO.files||{};
    return ''+
      banner('info','<strong>Attach what the desk already holds.</strong> A tick without a file only '+
        'records a claim; the gate that needs the document still has nothing to read. Anything not '+
        'attached stays as an open task against the gate that needs it.')+
      '<div class="stack" style="gap:8px">'+need.map(dd=>{
        const f=held[dd[0]];
        return '<div class="docrow'+(f?' is-held':'')+'">'+
          '<span class="docico">'+ICO(f?'checkcircle':'file',16)+'</span>'+
          '<div class="grow"><div class="t-small strong">'+esc(dd[0])+'</div>'+
          '<div class="t-tiny muted">'+esc((ONB_STEPS.find(g=>g.id===dd[1])||{}).name||dd[1])+' gate'+
          (f? ' · '+esc(f.name)+' · '+esc(f.size)+' · attached '+esc(f.at) : ' · nothing attached yet')+
          '</div></div>'+
          (f
            ? '<span class="rowend">'+
              '<button class="btn btn-sm btn-quiet" onclick="viewGateDoc('+
                JSON.stringify(dd[0]).replace(/"/g,'&quot;')+','+
                JSON.stringify(ooV('ooName')||'the applicant').replace(/"/g,'&quot;')+')">View</button>'+
              '<button class="btn btn-sm" onclick="ooDropFile('+
                JSON.stringify(dd[0]).replace(/"/g,'&quot;')+')">Remove</button></span>'
            : '<label class="btn btn-sm btn-primary" style="cursor:pointer;margin:0">'+
              ICO('upload',13)+'Attach'+
              '<input type="file" class="ooFile" accept=".pdf,.png,.jpg,.jpeg,.xlsx,.docx" '+
              'data-doc="'+esc(dd[0])+'" data-gate="'+dd[1]+'" '+
              'onchange="ooTakeFile(this)" style="display:none"></label>')+
        '</div>';
      }).join('')+'</div>'+
      '<p class="t-tiny muted">Files stay on the desk’s record. Attaching one closes the task that would '+
      'otherwise have chased the seller for it — it does not clear the gate, because somebody still has '+
      'to read what was attached.</p>';
  }

  /* Review */
  const docs=(OO.docs||[]);
  return ''+
    '<div class="field"><label for="ooWhy">Why the desk is doing this rather than the seller</label>'+
      '<textarea class="inp" id="ooWhy" rows="2" data-autofocus placeholder="Negotiated at the enterprise '+
      'desk; contract signed 22 Jul">'+esc(ooV('ooWhy'))+'</textarea>'+
      '<div class="hint">Written to the onboarding trail. An operator-created application should be '+
      'explicable a year later.</div></div>'+
    '<div class="divider"></div>'+
    '<h4 class="t-sub">What will be recorded</h4>'+
    dl([['Legal entity', ooV('ooName')||'*Not supplied*'],
        ['Country', ooV('ooCountry')||'*Not supplied*'],
        ['Contact', esc(ooV('ooContact')||'—')+(ooV('ooEmail')?' &lt;'+esc(ooV('ooEmail'))+'&gt;':'')],
        ['Categories', (OO.verticals||[]).map(v=>vName(v)).join(', ')||'*None picked*'],
        ['Settlement account', ooV('ooAcct')? maskAcct(ooV('ooAcct'))+' at '+(ooV('ooBank')||'—')
                                            : '*Not supplied — the finance gate will ask for it*'],
        ['Tax identifier', ooV('ooTaxId')? maskTaxId(ooV('ooTaxId')) : '*Not supplied*'],
        ['Documents attached', docs.length? docs.length+' of 8 — '+
          docs.map(d=>((OO.files||{})[d]||{}).name||d).join(', ') : 'None attached'],
        ['Endpoint', ooV('ooEp')||'None yet']])+
    banner('warning','<strong>The application gate is the only one this clears.</strong> Everything else '+
      'lands as an open task against the gate that owns it, and the seller starts at KYC exactly where a '+
      'self-served one would.');
}
/* A tick is a claim; a file is evidence. The wizard keeps the file's name, type
   and size so the record says what was actually attached rather than that
   somebody said it existed. Nothing is uploaded anywhere — this is a local
   record of what the desk holds. */
function ooTakeFile(input){
  const f=(input.files&&input.files[0])||null;
  const doc=input.getAttribute('data-doc');
  if(!doc) return;
  if(!f){ toast('No file was chosen','warn'); return; }
  const kb=f.size/1024;
  OO.files=OO.files||{};
  OO.files[doc]={
    name:f.name,
    type:(f.name.split('.').pop()||'file').toUpperCase(),
    size: kb>1024 ? (kb/1024).toFixed(1)+' MB' : Math.max(1,Math.round(kb))+' KB',
    at:TODAY,
    gate:input.getAttribute('data-gate')
  };
  OO.docs=OO.docs||[];
  if(OO.docs.indexOf(doc)<0) OO.docs.push(doc);
  toast(doc+' attached');
  ooGo(OO.step);
}
function ooDropFile(doc){
  if(OO.files) delete OO.files[doc];
  const i=(OO.docs||[]).indexOf(doc);
  if(i>-1) OO.docs.splice(i,1);
  toast(doc+' removed — the gate that needs it will ask the seller for it');
  ooGo(OO.step);
}
/* Kept so an older call site cannot break; a tick alone no longer counts. */
function ooDocToggle(el){
  if(el && el.checked) toast('Attach the file rather than ticking it — a tick is not evidence','warn');
  if(el) el.checked=false;
}

function saveOperatorOnboard(){
  ooCapture();
  const g=k=>String(OO[k]||'').trim();
  const vs=(OO.verticals||[]).slice();
  const name=g('ooName'), contact=g('ooContact'), email=g('ooEmail'), why=g('ooWhy');
  if(!name){ toast('A legal entity name is required','warn'); ooGo(0); return; }
  if(!g('ooCountry')){ toast('Pick a country — it decides which bank and tax details we ask for','warn');
    ooGo(0); return; }
  if(!contact||!email){ toast('Name the person we deal with, and their email','warn'); ooGo(1); return; }
  if(!vs.length){ toast('Pick at least one marketplace category','warn'); ooGo(1); return; }
  const ep=g('ooEp');
  if(ep && !/^https:\/\//.test(ep)){ toast('The endpoint must be https','warn'); ooGo(1); return; }
  /* A settlement account is optional here — the desk may not have it yet — but
     a half-entered one is worse than none, and a mistyped one is worst of all. */
  const acct=g('ooAcct').replace(/\s+/g,''), acct2=g('ooAcct2').replace(/\s+/g,'');
  if(acct && acct!==acct2){
    toast('The two account numbers do not match — check both before saving','warn'); ooGo(2); return; }
  if(acct && !g('ooBank')){ toast('An account number with no bank cannot be paid to','warn'); ooGo(2); return; }
  if(!why){ toast('Say why the desk is creating this rather than the seller','warn'); ooGo(4); return; }

  const me=((typeof orgUsers==='function'&&(orgUsers('operator').filter(u=>u.you)[0]||{}).name)||'Onboarding desk');
  closeModal();

  const p=invitePartner({name:name, type:g('ooType')||'Reseller', verticals:vs,
    country:g('ooCountry'), contact:contact, email:email,
    plan:g('ooPlan')||null, invitedBy:me});
  const pid=p&&p.id ? p.id : PARTNERS[PARTNERS.length-1].id;
  const rec=PMAP[pid];
  if(rec){ rec.createdByOperator=true; rec.createdReason=why; rec.regNo=g('ooReg')||null;
           rec.phone=g('ooPhone')||null; }

  const c=bankCodeFor(g('ooCountry'));
  if(acct){
    PARTNER_BANK[pid]={
      partnerId:pid, holder:g('ooHolder')||name, bank:g('ooBank'), branch:g('ooBranch')||'—',
      account:acct, localLabel:c.local, localCode:g('ooLocal')||'—',
      swift:g('ooSwift')||'—', iban:c.iban ? (g('ooIban')||null) : null,
      currency:g('ooCur')||'USD',
      taxLabel:c.tax, taxId:g('ooTaxId')||'—', residency:g('ooTaxRes')||g('ooCountry'),
      treaty:{onFile:!!g('ooTreaty'), expires:g('ooTreaty')||null,
              withholding:g('ooTreaty')? 'Nil under treaty' : 'Statutory rate — no certificate on file'},
      /* Captured is not verified. The micro-deposits still have to be matched. */
      verified:false, verifiedOn:null, verifiedBy:null,
      method:'Recorded by the desk during operator-led onboarding — not yet verified'
    };
    if(typeof audit==='function') audit('bank.recorded',{object:name,
      detail:'Captured by the desk · '+maskAcct(acct)+' at '+g('ooBank')+' · not verified'});
  }

  /* The application gate is satisfied — the desk has the detail. Nothing else is. */
  const st=ONB_STATE[pid];
  if(st){ st.apply='done'; st.kyc='now'; st.owner='Marketplace onboarding desk'; }
  if(typeof closeTasksForGate==='function') closeTasksForGate(pid,'apply',me);
  if(typeof openTasksForGate==='function') openTasksForGate(pid,'kyc');

  /* A ticked document closes the task that would have chased it. Everything
     unticked stays open against the gate that needs it. */
  const docs=(OO.docs||[]).slice();
  const docTask={'Certificate of incorporation':['kyc','inc'],
                 'Beneficial ownership declaration':['kyc','ubo'],
                 'Director identification':['kyc','ubo'],
                 'Marketplace terms — countersigned':['agree','terms'],
                 'Data processing agreement':['agree','dpa'],
                 'Bank verification letter':['finance','bank'],
                 'Tax residency certificate':['finance','tax'],
                 'Security questionnaire':['assure','sec']};
  docs.forEach(d=>{
    const m=docTask[d]; if(!m) return;
    onbTasksFor(pid,m[0]).filter(t=>t.key===m[1]).forEach(t=>{
      const f=(OO.files||{})[d]||{};
      t.status='done'; t.due='—';
      t.closedBy=me+' (attached '+(f.name||'a document')+')'; t.closedOn=TODAY;
    });
  });

  ONB_SUBMISSIONS[pid]=ONB_SUBMISSIONS[pid]||{};
  ONB_SUBMISSIONS[pid].apply={
    gate:'apply', state:'done',
    submittedOn:TODAY, submittedBy:me+' (on behalf of '+contact+')',
    fields:[
      ['Legal entity', name],
      ['Type', g('ooType')||'—'],
      ['Country of registration', g('ooCountry')],
      ['Registration number', g('ooReg')||'Not supplied'],
      ['Primary contact', contact+' <'+email+'>'],   /* escaped where it renders */
      ['Telephone', g('ooPhone')||'Not supplied'],
      ['Categories', vs.map(v=>vName(v)).join(', ')],
      ['Expected orders a month', g('ooVol')||'Not stated'],
      ['Commission plan', g('ooPlan')? (CPMAP[g('ooPlan')]||{}).name||g('ooPlan')
                                     : 'To be set at the commercial gate'],
      ['Fulfilment endpoint', ep||'None yet'],
      ['Captured by the desk because', why]
    ],
    docs:docs.map(d=>{
      const f=(OO.files||{})[d]||{};
      return [d, f.type||'PDF', (f.size||'On file')+(f.name?' · '+f.name:'')];
    })
  };
  /* The settlement detail is recorded against the finance gate, masked, and
     left explicitly unverified — the gate is not cleared by having typed it. */
  if(acct){
    ONB_SUBMISSIONS[pid].finance={
      gate:'finance', state:'todo',
      submittedOn:TODAY, submittedBy:me+' (captured by the desk)',
      fields:[
        ['Account holder', g('ooHolder')||name],
        ['Bank', g('ooBank')+(g('ooBranch')?' — '+g('ooBranch'):'')],
        ['Account (masked)', maskAcct(acct)],
        [c.local, maskTail(g('ooLocal')||'—',3)],
        ['SWIFT / BIC', g('ooSwift')||'—'],
        ['Settlement currency', g('ooCur')||'USD'],
        ['Tax residency', g('ooTaxRes')||g('ooCountry')],
        [c.tax, maskTaxId(g('ooTaxId')||'—')],
        ['Treaty certificate', g('ooTreaty')? 'Valid to '+g('ooTreaty') : 'Not supplied'],
        ['Verification', 'Not started — micro-deposits still to be matched']
      ],
      docs:docs.filter(d=>d==='Bank verification letter'||d==='Tax residency certificate')
        .map(d=>{ const f=(OO.files||{})[d]||{};
          return [d, f.type||'PDF', (f.size||'On file')+(f.name?' · '+f.name:'')]; })
    };
  }

  if(ep){
    PARTNER_ENDPOINTS.push({
      id:'PEP-'+(400+PARTNER_ENDPOINTS.length), partnerId:pid, partner:name,
      name:'Order and fulfilment', url:ep, method:'POST',
      events:API_EVENTS.filter(e=>e.required&&e.group==='Order').map(e=>e.id),
      auth:'OAuth 2.0 client credentials', retry:'3 attempts, exponential backoff', timeoutMs:5000,
      env:'Sandbox', enabled:true, health:'unknown', lastCall:'Never', successRate:null, p95:0,
      registered:TODAY, verifiedBy:me,
      note:'Supplied during operator-led onboarding. Untested.', isNew:true
    });
  }

  if(typeof audit==='function') audit('partner.invited',{object:name,
    detail:'Application created by the desk on the seller’s behalf · '+why+
      (acct?' · settlement instruction captured, unverified':'')});
  toast(name+' created at the KYC gate — the application is captured, nothing is cleared');
  App.go('onboardq');
}

/* ==========================================================================
   39. MARKETPLACE EVENT CATALOGUE — configuration
   --------------------------------------------------------------------------
   The events were readable and not editable, which made them look like a
   property of the platform rather than a decision somebody took.

   The decision that matters is `required`. Marking an event mandatory does
   not create work for the marketplace; it puts every seller without an
   endpoint for it out of compliance the moment it is saved. So the editor
   computes that blast radius and shows it before the save, not after.
   ========================================================================== */

function evStateName(e){ return e.status||'active'; }
function evSubscribers(id){
  return PARTNER_ENDPOINTS.filter(ep=>ep.enabled && ep.events.indexOf(id)>-1);
}
/* Which active partners would gain a gap if this event were required for
   these models. The whole point of the editor. */
function evImpact(id, required, models){
  if(!required) return [];
  const model = v => v==='device'?'logistics' : v==='iot'?'provisioning'
                   : v==='content'?'digital' : v==='security'?'seat' : 'activation';
  /* 'live' is the trading status. Filtering on 'active' silently matched
     nothing, so every gap count read zero. */
  return PARTNERS.filter(p=>p.status==='live').filter(p=>{
    const ms=(p.verticals||[]).map(model);
    if(!ms.some(m=>models.indexOf(m)>-1)) return false;      /* does not apply */
    return !pepHandled(p.id)[id];                             /* applies, unhandled */
  });
}

function eventDialog(id){
  const e = id ? EVMAP[id] : null;
  const isNew = !e;
  const subs = e ? evSubscribers(e.id) : [];
  openModal('<div class="modal-head">'+ICO('zap',18)+
    '<div class="grow"><h3 class="t-sub">'+(isNew?'New marketplace event':esc(e.label))+'</h3>'+
    '<div class="t-small muted">'+(isNew?'Published to partners once active'
      :'<span class="t-num">'+esc(e.id)+'</span> · published '+esc(e.since))+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      (e && e.status==='deprecated'
        ? banner('warning','<strong>Deprecated.</strong> Still delivered to the '+subs.length+
          ' endpoint'+(subs.length===1?'':'s')+' already subscribed, but offered to nobody new.'):'')+
      (e && e.status==='draft'
        ? banner('info','<strong>Draft.</strong> Not published and not delivered. Partners cannot subscribe '+
          'to it until it is activated.'):'')+

      '<div class="grid g2">'+
        '<div class="field"><label for="evId">Event id</label>'+
          '<input class="inp" id="evId" value="'+esc(e?e.id:'')+'"'+(e?' disabled':' data-autofocus')+
          ' placeholder="subscription.upgraded">'+
          '<p class="t-tiny muted">'+(e?'An id is never changed once published — an endpoint subscribes to the string.'
            :'Lower case, dot separated, noun then past-tense verb.')+'</p></div>'+
        '<div class="field"><label for="evLabel">Label</label>'+
          '<input class="inp" id="evLabel" value="'+esc(e?e.label:'')+'" placeholder="Subscription upgraded"></div>'+
      '</div>'+
      '<div class="field"><label for="evNote">What it means to the seller</label>'+
        '<textarea class="inp" id="evNote" rows="2">'+esc(e?e.note:'')+'</textarea>'+
        '<p class="t-tiny muted">Shown in the partner’s console and in the reference. Write what they should '+
        'do when it arrives, not what the platform did.</p></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="evGroup">Group</label><select class="inp" id="evGroup">'+
          EVENT_GROUPS.map(g=>'<option'+(e&&e.group===g?' selected':'')+'>'+esc(g)+'</option>').join('')+
          '</select></div>'+
        '<div class="field"><label for="evPayload">Payload fields</label>'+
          '<input class="inp" id="evPayload" value="'+esc(e?(e.payload||[]).join(', '):'id, occurredAt, idempotencyKey')+'">'+
          '<p class="t-tiny muted">Comma separated. Adding a field is safe; removing one breaks a consumer.</p></div>'+
      '</div>'+

      '<div class="divider"></div>'+
      '<h4 class="t-sub" style="margin:0">Who must handle it</h4>'+
      '<label class="toggle"><input type="checkbox" id="evReq" '+(e&&e.required?'checked':'')+
        ' onchange="evPreviewImpact()"><span class="track"></span>'+
        'Mandatory — a seller using one of the models below must have an endpoint for it</label>'+
      '<div class="field"><label>Fulfilment models it applies to</label>'+
        '<div class="checkgrid">'+FULFIL_MODELS.map(m=>
          '<label class="checkline"><input type="checkbox" class="evM" value="'+m.id+'"'+
          (e&&(e.models||[]).indexOf(m.id)>-1?' checked':'')+' onchange="evPreviewImpact()">'+
          '<span>'+esc(m.label)+' <span class="t-tiny muted">'+esc(m.note)+'</span></span></label>').join('')+
        '</div></div>'+
      '<div id="evImpact"></div>'+

      '<div class="divider"></div>'+
      '<label class="toggle"><input type="checkbox" id="evPii" '+(e&&e.pii?'checked':'')+
        '><span class="track"></span>Payload carries personal data</label>'+
      '<p class="t-tiny muted">Marks it for redaction in the call log and forces https on any endpoint '+
        'subscribing to it.</p>'+

      (e? '<div class="divider"></div><h4 class="t-sub">Who subscribes today</h4>'+
        (subs.length
          ? '<ul class="ticklist">'+subs.slice(0,8).map(x=>
              '<li>'+ICO('plug',14)+'<div class="grow"><strong>'+esc(x.partner)+'</strong>'+
              '<div class="t-tiny muted">'+esc(x.name)+' · '+esc(x.env)+'</div></div>'+
              pepHealth(x)+'</li>').join('')+'</ul>'+
            (subs.length>8?'<p class="t-tiny muted">And '+(subs.length-8)+' more.</p>':'')
          : banner('info','No endpoint subscribes to this event. If it is optional that is fine; if it is '+
            'mandatory, every applicable seller is out of compliance.')) : '')+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">'+
      (isNew?'Created as a draft — it is published to nobody until activated'
            :'Changes take effect on the next event of this type')+'</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      (e&&e.status==='active'?'<button class="btn" onclick="deprecateEvent(\''+e.id+'\')">Deprecate</button>':'')+
      (e&&e.status==='draft'?'<button class="btn" onclick="activateEvent(\''+e.id+'\')">Activate</button>':'')+
      '<button class="btn btn-primary" onclick="saveEvent('+(e?'\''+e.id+'\'':'null')+')">'+
        (isNew?'Create as draft':'Save')+'</button></div>',
    {wide:true,label:'Marketplace event'});
  evPreviewImpact();
}

/* The blast radius, recomputed live as the operator ticks boxes. */
function evPreviewImpact(){
  const host=document.getElementById('evImpact'); if(!host) return;
  const req=(document.getElementById('evReq')||{}).checked;
  const models=Array.prototype.slice.call(document.querySelectorAll('.evM'))
    .filter(c=>c.checked).map(c=>c.value);
  const id=((document.getElementById('evId')||{}).value||'').trim();
  if(!req){
    host.innerHTML=banner('info','Optional. A seller may subscribe to it, and nothing is out of compliance '+
      'if they do not.');
    return;
  }
  if(!models.length){
    host.innerHTML=banner('warning','Mandatory but applying to no fulfilment model, which means it is '+
      'mandatory for nobody. Pick the models it applies to, or make it optional.');
    return;
  }
  const hit=evImpact(id, true, models);
  host.innerHTML = hit.length
    ? banner('danger','<strong>'+hit.length+' live seller'+(hit.length===1?'':'s')+
      ' would be out of compliance the moment this is saved:</strong> '+
      hit.slice(0,6).map(p=>esc(p.name)).join(', ')+(hit.length>6?' and '+(hit.length-6)+' more':'')+
      '. They have no endpoint for this event, and an unhandled required event is not queued — it does not '+
      'arrive. Tell them before you save, not after.')
    : banner('success','Every live seller using these models already has an endpoint for it. Making it '+
      'mandatory changes nothing today and closes the gap for new sellers.');
}

function saveEvent(id){
  const g=k=>((document.getElementById(k)||{}).value||'').trim();
  const ck=k=>!!(document.getElementById(k)||{}).checked;
  const models=Array.prototype.slice.call(document.querySelectorAll('.evM'))
    .filter(c=>c.checked).map(c=>c.value);
  const label=g('evLabel'), note=g('evNote');
  if(!label||!note){ toast('An event needs a label and a description','warn'); return; }
  const payload=g('evPayload').split(',').map(x=>x.trim()).filter(Boolean);
  const spec={label:label, note:note, group:g('evGroup'), required:ck('evReq'),
              models:models, pii:ck('evPii'), payload:payload};

  if(id){
    const e=EVMAP[id];
    const wasReq=e.required;
    const newly = spec.required ? evImpact(id, true, models).length : 0;
    Object.assign(e, spec);
    if(typeof audit==='function') audit('api.event',{object:e.label,
      before:wasReq?'required':'optional', after:spec.required?'required':'optional',
      detail:'Event definition changed'+(newly?' · '+newly+' sellers now non-compliant':''),
      sev:newly?'warn':'notice'});
    closeModal();
    toast(newly? e.label+' saved — '+newly+' seller'+(newly===1?' is':'s are')+' now out of compliance'
               : e.label+' saved');
  } else {
    const nid=g('evId').toLowerCase();
    if(!/^[a-z][a-z0-9]*(\.[a-z][a-z0-9]*)+$/.test(nid)){
      toast('An id looks like subscription.upgraded — lower case, dot separated','warn'); return; }
    if(EVMAP[nid]){ toast('That id already exists','warn'); return; }
    const e=Object.assign({id:nid, status:'draft', since:TODAY}, spec);
    API_EVENTS.push(e); EVMAP[nid]=e;
    if(typeof audit==='function') audit('api.event',{object:e.label, after:'draft',
      detail:'Event created as a draft · '+nid});
    closeModal();
    toast(e.label+' created as a draft — partners cannot subscribe until it is activated');
  }
  App.go(App.view);
}

function activateEvent(id){
  const e=EVMAP[id]; if(!e) return;
  const hit=e.required? evImpact(id,true,e.models||[]) : [];
  closeModal();
  confirmAction({
    title:'Publish '+e.label, subtitle:e.id, confirmLabel:'Publish it',
    impact:['Partners can subscribe to it from now on.',
            'It begins firing on the next matching change.',
            hit.length? hit.length+' live seller'+(hit.length===1?' is':'s are')+
              ' immediately non-compliant because it is mandatory and they have no endpoint.'
            : 'No seller is put out of compliance by publishing it.'],
    risk:hit.length?'high':undefined,
    onConfirm:()=>{
      e.status='active'; e.since=TODAY;
      if(typeof audit==='function') audit('api.event',{object:e.label, before:'draft', after:'active',
        detail:'Event published'+(hit.length?' · '+hit.length+' sellers non-compliant':'')});
      toast(e.label+' published'); App.go(App.view);
    }
  });
}
function deprecateEvent(id){
  const e=EVMAP[id]; if(!e) return;
  const subs=evSubscribers(id);
  closeModal();
  confirmAction({
    title:'Deprecate '+e.label, subtitle:e.id, confirmLabel:'Deprecate it', risk:'high',
    body:banner('info','<strong>Deprecated, not deleted.</strong> '+subs.length+' endpoint'+
      (subs.length===1?'':'s')+' subscribe to this id today. Removing it would leave a subscription '+
      'pointing at a string nobody can look up, which cannot be diagnosed.'),
    impact:['It stops being offered to new subscribers.',
            subs.length? 'It keeps being delivered to the '+subs.length+' endpoint'+
              (subs.length===1?'':'s')+' already subscribed, so nothing breaks today.'
            : 'Nobody subscribes to it, so nothing changes.',
            'It stops being mandatory, so no seller is non-compliant because of it.',
            'Give partners a replacement and a date before you withdraw it entirely.'],
    onConfirm:()=>{
      e.status='deprecated'; e.required=false;
      if(typeof audit==='function') audit('api.event',{object:e.label, before:'active', after:'deprecated',
        detail:'Event deprecated · '+subs.length+' endpoints still subscribed', sev:'warn'});
      toast(e.label+' deprecated'); App.go(App.view);
    }
  });
}

/* The configurable catalogue, on the Partner APIs screen. */
function eventCataloguePanel(){
  const active=API_EVENTS.filter(e=>evStateName(e)==='active');
  const drafts=API_EVENTS.filter(e=>evStateName(e)==='draft');
  const dep=API_EVENTS.filter(e=>evStateName(e)==='deprecated');
  const orphan=active.filter(e=>e.required && !evSubscribers(e.id).length);
  const reqNoModel=active.filter(e=>e.required && !(e.models||[]).length);

  return panel('Marketplace events',
    banner('info','<strong>These are the events the marketplace publishes, and they are a decision rather than '+
      'a property of the platform.</strong> Marking one mandatory does not create work here — it puts every '+
      'seller without an endpoint for it out of compliance the moment it is saved, so the editor shows that '+
      'count before you commit.')+
    (orphan.length? banner('warning','<strong>'+orphan.length+' mandatory event'+(orphan.length===1?'':'s')+
      ' with no subscriber at all:</strong> '+orphan.map(e=>esc(e.label)).join(', ')+
      '. Either nobody has integrated it yet, or it should not be mandatory.'):'')+
    (reqNoModel.length? banner('warning','<strong>'+reqNoModel.length+' event'+(reqNoModel.length===1?' is':'s are')+
      ' mandatory but apply to no fulfilment model,</strong> which makes them mandatory for nobody.'):'')+
    '<div class="tablewrap"><table class="tbl"><thead><tr>'+
      '<th style="min-width:200px">Event</th><th>Group</th><th>Applies to</th>'+
      '<th class="num">Subscribers</th><th>Personal data</th><th>Handling</th><th>State</th><th></th>'+
      '</tr></thead><tbody>'+
    EVENT_GROUPS.map(g=>API_EVENTS.filter(e=>e.group===g).map(e=>{
      const subs=evSubscribers(e.id).length;
      return '<tr>'+
        '<td><div class="cellmain">'+esc(e.label)+'</div>'+
          '<div class="cellsub t-num">'+esc(e.id)+'</div></td>'+
        '<td class="t-small">'+esc(e.group)+'</td>'+
        '<td class="t-small">'+((e.models||[]).length
          ? e.models.map(m=>esc((FULFIL_MODELS.filter(x=>x.id===m)[0]||{}).label||m)).join(', ')
          : '<span class="dim">Any</span>')+'</td>'+
        '<td class="num t-num'+(e.required&&!subs?' cellmain':'')+'">'+(subs||'<span class="dim">None</span>')+'</td>'+
        '<td>'+(e.pii?pill('warn','Yes'):'<span class="dim">No</span>')+'</td>'+
        '<td>'+(e.required?pill('ok','Mandatory'):pill('','Optional'))+'</td>'+
        '<td>'+(evStateName(e)==='active'?pill('ok','Published')
               :evStateName(e)==='draft'?pill('warn','Draft'):pill('','Deprecated'))+'</td>'+
        '<td class="rowend"><button class="btn btn-sm btn-quiet" onclick="eventDialog(\''+e.id+'\')">'+
          'Configure</button></td></tr>';
    }).join('')).join('')+
    '</tbody></table></div>'+
    '<p class="t-tiny muted">An event is deprecated, never deleted. Registered endpoints subscribe to the id, '+
      'and a subscription pointing at a string nobody can look up cannot be diagnosed.</p>',
    {icon:'zap',
     sub:active.length+' published · '+drafts.length+' draft · '+dep.length+' deprecated',
     acts:'<button class="btn btn-sm btn-primary" onclick="eventDialog(null)">New event</button>'});
}

/* ==========================================================================
   40. API PRODUCTS — authoring, versions and subscribers
   --------------------------------------------------------------------------
   Same rule as everywhere else in this build: a published contract is not
   edited in place. A breaking change is a new major version, because the
   people already calling v2 did not agree to your correction.
   ========================================================================== */

function apiVersions(id){ return API_VERSIONS[id] || []; }
function apiCurrent(id){
  const v=apiVersions(id).filter(x=>x.status==='current')[0];
  return v ? v.version : (APIPMAP[id]||{}).version;
}
function apiSubs(id, version){
  return API_SUBSCRIPTIONS.filter(s=>s.api===id && (!version || s.version===version));
}
function apiVerState(v){
  return v.status==='current'   ? pill('ok','Current')
       : v.status==='supported' ? pill('','Supported')
       : v.status==='deprecated'? pill('warn','Deprecated')
       : pill('down','Sunset');
}

/* ---------------------------------------------------------- Authoring --- */
function apiDialog(id){
  const a = id ? APIPMAP[id] : null;
  const isNew = !a;
  const subs = a ? apiSubs(a.id) : [];
  openModal('<div class="modal-head">'+ICO('code',18)+
    '<div class="grow"><h3 class="t-sub">'+(isNew?'Publish an API':esc(a.name))+'</h3>'+
    '<div class="t-small muted">'+(isNew?'Extended to partners as integration access'
      :'<span class="t-num">'+esc(a.id)+'</span> · '+esc(apiCurrent(a.id))+' current · '+
       subs.length+' subscriber'+(subs.length===1?'':'s'))+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>This publishes a capability, not a product.</strong> An API here should mirror '+
        'something a partner can already do in their console. If it lets them do something the console does not, '+
        'that is a permissions decision before it is an API one.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="apId">Identifier</label>'+
          '<input class="inp" id="apId" value="'+esc(a?a.id:'')+'"'+(a?' disabled':' data-autofocus')+
          ' placeholder="AP-USG">'+
          '<p class="t-tiny muted">'+(a?'Fixed once published — it appears in every base URL.'
            :'Short, upper case, AP- prefixed.')+'</p></div>'+
        '<div class="field"><label for="apName">Name</label>'+
          '<input class="inp" id="apName" value="'+esc(a?a.name:'')+'" placeholder="Usage"></div>'+
      '</div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="apSpec">Standard it implements</label>'+
          '<input class="inp" id="apSpec" value="'+esc(a?a.spec:'')+'" placeholder="TMF635">'+
          '<p class="t-tiny muted">Name the specification. An API that follows none should say so rather than '+
          'leave the field blank.</p></div>'+
        '<div class="field"><label for="apAud">Who it is for</label>'+
          '<input class="inp" id="apAud" value="'+esc(a?(a.audience||'Sellers'):'Sellers')+'"></div>'+
      '</div>'+
      '<div class="field"><label for="apBlurb">What it does</label>'+
        '<textarea class="inp" id="apBlurb" rows="2">'+esc(a?a.blurb:'')+'</textarea></div>'+
      '<div class="field"><label for="apWhy">Why it exists</label>'+
        '<input class="inp" id="apWhy" value="'+esc(a?(a.why||''):'')+'" '+
        'placeholder="The alternative is a nightly file and a day of overselling.">'+
        '<p class="t-tiny muted">One line. If it cannot be answered, the API probably should not be published.</p></div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="apScopes">Scopes</label>'+
          '<input class="inp" id="apScopes" value="'+esc(a?(a.scopes||[]).join(', '):'')+'" '+
          'placeholder="usage:read"></div>'+
        '<div class="field"><label for="apMethods">Methods</label>'+
          '<input class="inp" id="apMethods" type="number" min="1" value="'+(a?a.methods:1)+'"></div>'+
      '</div>'+
      '<div class="field"><label>Environments</label><div class="checkgrid">'+
        API_ENVS.map(e=>'<label class="checkline"><input type="checkbox" class="apEnv" value="'+e.id+'"'+
          ((!a || (a.envs||[]).indexOf(e.id)>-1)?' checked':'')+'>'+
          '<span>'+esc(e.label)+' <span class="t-tiny muted">'+esc(e.commitment)+'</span></span></label>').join('')+
        '</div></div>'+
      '<div class="field"><label for="apStatus">Lifecycle</label><select class="inp" id="apStatus">'+
        ['preview','beta','ga'].map(x=>'<option value="'+x+'"'+(a&&a.status===x?' selected':'')+'>'+
          (x==='ga'?'General release':x==='beta'?'Beta':'Preview')+'</option>').join('')+'</select>'+
        '<p class="t-tiny muted">Beta and preview are labelled to partners rather than quietly published.</p></div>'+
      '<div class="field"><label for="apNote">Caveat shown to integrators</label>'+
        '<input class="inp" id="apNote" value="'+esc(a?(a.note||''):'')+'"></div>'+
      (a && subs.length
        ? banner('warning','<strong>'+subs.length+' consumer'+(subs.length===1?'':'s')+' already call this API.</strong> '+
          'Removing a scope or a method here breaks them. If the change is breaking, add a version instead.')
        : '')+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">'+
      (isNew?'Published with a v1 you can then version'
            :'Edits here are descriptive — behaviour changes belong in a version')+'</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      (a?'<button class="btn" onclick="closeModal();apiVersionsDialog(\''+a.id+'\')">Versions</button>':'')+
      '<button class="btn btn-primary" onclick="saveApi('+(a?'\''+a.id+'\'':'null')+')">'+
        (isNew?'Publish it':'Save')+'</button></div>',
    {wide:true,label:'API product'});
}

function saveApi(id){
  const g=k=>((document.getElementById(k)||{}).value||'').trim();
  const envs=Array.prototype.slice.call(document.querySelectorAll('.apEnv'))
    .filter(c=>c.checked).map(c=>c.value);
  const name=g('apName'), blurb=g('apBlurb');
  if(!name||!blurb){ toast('An API needs a name and a description','warn'); return; }
  if(!envs.length){ toast('Pick at least one environment','warn'); return; }
  const scopes=g('apScopes').split(',').map(x=>x.trim()).filter(Boolean);
  if(!scopes.length){ toast('An API needs at least one scope','warn'); return; }
  const spec={name:name, spec:g('apSpec')||'No published standard', audience:g('apAud')||'Sellers',
              blurb:blurb, why:g('apWhy')||'', scopes:scopes,
              methods:parseInt(g('apMethods'),10)||1, envs:envs,
              status:g('apStatus')||'preview', note:g('apNote')||null};
  if(id){
    const a=APIPMAP[id];
    Object.assign(a, spec);
    if(typeof audit==='function') audit('api.product',{object:a.name, detail:'API description updated'});
    closeModal(); toast(a.name+' saved');
  } else {
    const nid=g('apId').toUpperCase();
    if(!/^AP-[A-Z]{2,6}$/.test(nid)){ toast('An identifier looks like AP-USG','warn'); return; }
    if(APIPMAP[nid]){ toast('That identifier already exists','warn'); return; }
    const a=Object.assign({id:nid, version:'v1'}, spec);
    API_PRODUCTS.push(a); APIPMAP[nid]=a;
    API_VERSIONS[nid]=[{version:'v1', status:'current', released:TODAY, breaking:false,
      changes:['First release.'], sunset:null}];
    if(typeof audit==='function') audit('api.product',{object:a.name, after:'published',
      detail:'API published · '+nid+' v1 · '+spec.status});
    closeModal(); toast(a.name+' published at v1');
  }
  App.go(App.view);
}

/* ----------------------------------------------------------- Versions --- */
function apiVersionsDialog(id){
  const a=APIPMAP[id]; if(!a) return;
  const vers=apiVersions(id);
  openModal('<div class="modal-head">'+ICO('history',18)+
    '<div class="grow"><h3 class="t-sub">'+esc(a.name)+' — versions</h3>'+
    '<div class="t-small muted">'+vers.length+' version'+(vers.length===1?'':'s')+' · '+
    apiSubs(id).length+' subscriber'+(apiSubs(id).length===1?'':'s')+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('info','<strong>A breaking change is a new major version, never an edit.</strong> The consumers '+
        'already calling the current version did not agree to a correction landing underneath them.')+
      '<div class="tablewrap"><table class="tbl"><thead><tr><th>Version</th><th>Released</th>'+
        '<th class="num">On it</th><th>Sunset</th><th>State</th><th></th></tr></thead><tbody>'+
      vers.slice().reverse().map(v=>{
        const on=apiSubs(id,v.version).length;
        return '<tr><td><div class="cellmain t-num">'+esc(v.version)+'</div>'+
          (v.breaking?'<div class="cellsub">'+pill('warn','Breaking')+'</div>':'')+'</td>'+
          '<td class="t-small">'+esc(v.released)+'</td>'+
          '<td class="num t-num'+(v.status==='deprecated'&&on?' cellmain':'')+'">'+
            (on||'<span class="dim">None</span>')+'</td>'+
          '<td class="t-small">'+(v.sunset?esc(v.sunset):'<span class="dim">—</span>')+'</td>'+
          '<td>'+apiVerState(v)+'</td>'+
          '<td class="rowend">'+
            (v.status==='current'||v.status==='supported'
              ? '<button class="btn btn-sm btn-quiet" onclick="deprecateApiVersion(\''+id+'\',\''+v.version+'\')">Deprecate</button>'
              : '')+
          '</td></tr>'+
          '<tr><td colspan="6" class="t-tiny muted">'+v.changes.map(c=>esc(c)).join(' &nbsp;·&nbsp; ')+'</td></tr>';
      }).join('')+'</tbody></table></div>'+
      (function(){
        const dep=vers.filter(v=>v.status==='deprecated' && apiSubs(id,v.version).length);
        return dep.length
          ? banner('warning','<strong>'+dep.reduce((n,v)=>n+apiSubs(id,v.version).length,0)+
            ' consumer(s) are still on a deprecated version.</strong> They are named on the subscription matrix. '+
            'A sunset date nobody has been moved off is a date you will end up moving.')
          : '';
      })()+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">A version is deprecated, then sunset — never deleted</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Close</button>'+
      '<button class="btn btn-primary" onclick="newApiVersionDialog(\''+id+'\')">Add a version</button></div>',
    {wide:true,label:'API versions'});
}

function newApiVersionDialog(id){
  const a=APIPMAP[id]; if(!a) return;
  const vers=apiVersions(id);
  const last=vers[vers.length-1];
  const next='v'+(parseInt(String(last?last.version:'v0').replace(/\D/g,''),10)+1);
  const on=apiSubs(id, last?last.version:null).length;
  closeModal();
  openModal('<div class="modal-head">'+ICO('plus',18)+
    '<div class="grow"><h3 class="t-sub">Add a version to '+esc(a.name)+'</h3>'+
    '<div class="t-small muted">'+esc(next)+' · '+on+' consumer'+(on===1?'':'s')+' on '+
    esc(last?last.version:'—')+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      '<div class="field"><label for="avNum">Version</label>'+
        '<input class="inp" id="avNum" value="'+esc(next)+'" data-autofocus></div>'+
      '<label class="toggle"><input type="checkbox" id="avBreak" onchange="avPreview()">'+
        '<span class="track"></span>This version contains a breaking change</label>'+
      '<div id="avNote"></div>'+
      '<div class="field"><label for="avChanges">What changed</label>'+
        '<textarea class="inp" id="avChanges" rows="4" '+
        'placeholder="One change per line. Prefix a breaking one with BREAKING:"></textarea></div>'+
      '<div class="field"><label for="avPrev">What happens to '+esc(last?last.version:'the previous version')+'</label>'+
        '<select class="inp" id="avPrev" onchange="avPreview()">'+
          '<option value="supported">Stays supported — no sunset date yet</option>'+
          '<option value="deprecated">Deprecated with a sunset date</option>'+
        '</select></div>'+
      '<div class="field"><label for="avSunset">Sunset date, if deprecating</label>'+
        '<input class="inp" id="avSunset" placeholder="31 Dec 2026"></div>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">The new version becomes current; nothing is withdrawn today</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<button class="btn btn-primary" onclick="saveApiVersion(\''+id+'\')">Add it</button></div>',
    {wide:true,label:'Add a version'});
  avPreview();
}
function avPreview(){
  const host=document.getElementById('avNote'); if(!host) return;
  const brk=(document.getElementById('avBreak')||{}).checked;
  const prev=(document.getElementById('avPrev')||{}).value;
  /* Parenthesised deliberately: without it the ternary swallows the second
     banner, and the deprecation warning disappears on exactly the change most
     likely to need it. */
  const kind = brk
    ? banner('warning','<strong>A breaking change means consumers must migrate deliberately.</strong> They are '+
      'not moved for them. Give them the previous version as supported for long enough to do it, and a sunset '+
      'date they can plan against.')
    : banner('info','<strong>Additive only.</strong> Existing consumers keep working without changing anything, '+
      'which is why an additive change does not need a migration plan.');
  const clock = (prev==='deprecated')
    ? banner('warning','Deprecating the previous version starts the clock. Anybody still on it at the sunset '+
      'date stops working, so the date has to be one you will actually enforce.')
    : '';
  host.innerHTML = kind + clock;
}
function saveApiVersion(id){
  const g=k=>((document.getElementById(k)||{}).value||'').trim();
  const brk=!!(document.getElementById('avBreak')||{}).checked;
  const num=g('avNum');
  const changes=g('avChanges').split('\n').map(x=>x.trim()).filter(Boolean);
  const prev=g('avPrev'), sunset=g('avSunset');
  if(!num){ toast('Give the version a number','warn'); return; }
  if(!changes.length){ toast('Say what changed — a version with no changelog is not a version','warn'); return; }
  if(prev==='deprecated' && !sunset){ toast('A deprecated version needs a sunset date','warn'); return; }
  const vers=apiVersions(id);
  if(vers.some(v=>v.version===num)){ toast('That version already exists','warn'); return; }
  const a=APIPMAP[id];
  const last=vers[vers.length-1];
  if(last){
    last.status = prev==='deprecated' ? 'deprecated' : 'supported';
    if(prev==='deprecated') last.sunset=sunset;
  }
  vers.push({version:num, status:'current', released:TODAY, breaking:brk, changes:changes, sunset:null});
  a.version=num;
  const stranded = last ? apiSubs(id, last.version).length : 0;
  if(typeof audit==='function') audit('api.product',{object:a.name+' '+num,
    before:last?last.version:'—', after:num,
    detail:(brk?'Breaking':'Additive')+' version published'+
      (prev==='deprecated'?' · previous deprecated, sunset '+sunset:'')+
      (stranded?' · '+stranded+' consumers still on the previous version':''),
    sev:brk?'warn':'notice'});
  closeModal();
  toast(a.name+' '+num+' published'+(stranded?' — '+stranded+' consumer(s) still on '+last.version:''));
  App.go(App.view);
}
function deprecateApiVersion(id,ver){
  const a=APIPMAP[id]; const v=apiVersions(id).filter(x=>x.version===ver)[0];
  if(!a||!v) return;
  const on=apiSubs(id,ver);
  closeModal();
  confirmAction({
    title:'Deprecate '+a.name+' '+ver, subtitle:on.length+' consumer'+(on.length===1?'':'s')+' on it today',
    confirmLabel:'Deprecate it', risk:on.length?'high':undefined,
    body:'<div class="field"><label for="dvSunset">Sunset date</label>'+
      '<input class="inp" id="dvSunset" placeholder="31 Dec 2026" data-autofocus></div>'+
      (on.length? banner('warning','<strong>'+on.map(x=>esc(x.consumerName)).join(', ')+
        '</strong> call this version. They keep working until the sunset date and then stop.')
      : banner('info','Nobody is on this version, so deprecating it costs nothing.')),
    impact:['It stops being offered to new integrations.',
            'Existing consumers keep working until the sunset date.',
            'The date is published to them, so it has to be one you will enforce.'],
    onConfirm:()=>{
      const d=((document.getElementById('dvSunset')||{}).value||'').trim();
      v.status='deprecated'; v.sunset=d||'To be set';
      if(typeof audit==='function') audit('api.product',{object:a.name+' '+ver,
        before:'supported', after:'deprecated',
        detail:'Deprecated, sunset '+(d||'not set')+' · '+on.length+' consumers on it', sev:'warn'});
      toast(a.name+' '+ver+' deprecated');
      App.go(App.view);
    }
  });
}

/* ------------------------------------------------- Subscription matrix --- */
function apiSubMatrix(){
  const cons=API_CONSUMERS.slice(0,10);
  return '<div class="tablewrap"><table class="tbl"><thead><tr>'+
    '<th style="min-width:180px">API</th>'+
    cons.map(c=>'<th style="width:78px" title="'+esc(c.name)+' — '+esc(c.kind)+'">'+
      esc(c.name.split(' ')[0])+'</th>').join('')+
    '<th style="width:82px">On it</th></tr></thead><tbody>'+
  API_PRODUCTS.map(a=>{
    let n=0;
    const cells=cons.map(c=>{
      const s=API_SUBSCRIPTIONS.filter(x=>x.api===a.id && x.consumer===c.id)[0];
      if(!s) return '<td class="t-tiny dim" title="Not subscribed">-</td>';
      n++;
      const v=apiVersions(a.id).filter(x=>x.version===s.version)[0]||{};
      const stale = v.status==='deprecated' || v.status==='sunset';
      return '<td><span class="t-tiny t-num'+(stale?' warntext':'')+'" title="'+
        esc(c.name+' · '+s.version+' · '+s.env+' · '+(v.status||''))+'">'+esc(s.version)+'</span></td>';
    }).join('');
    return '<tr><td><div class="cellmain">'+esc(a.name)+'</div>'+
      '<div class="cellsub">current '+esc(apiCurrent(a.id))+' · '+esc(a.spec)+'</div></td>'+
      cells+'<td class="t-num'+(n?'':' dim')+'">'+(n||'None')+'</td></tr>';
  }).join('')+'</tbody></table></div>';
}

function apiVersionsPanel(){
  const stale=[];
  API_PRODUCTS.forEach(a=>apiVersions(a.id).forEach(v=>{
    if((v.status==='deprecated'||v.status==='sunset') && apiSubs(a.id,v.version).length)
      stale.push({api:a, v:v, n:apiSubs(a.id,v.version).length});
  }));
  const noSubs=API_PRODUCTS.filter(a=>!apiSubs(a.id).length);
  return panel('Versions and who is on them',
    (stale.length
      ? banner('warning','<strong>'+stale.reduce((n,x)=>n+x.n,0)+' subscription'+
        (stale.reduce((n,x)=>n+x.n,0)===1?' is':'s are')+' on a version past its prime:</strong> '+
        stale.map(x=>esc(x.api.name)+' '+esc(x.v.version)+' ('+x.n+')').join(', ')+
        '. A sunset date nobody has been moved off is a date you will end up moving.')
      : banner('success','Every subscription is on a current or supported version.'))+
    (noSubs.length? banner('info','<strong>'+noSubs.map(a=>esc(a.name)).join(', ')+
      '</strong> '+(noSubs.length===1?'has':'have')+' no subscribers. Either nobody needs it yet, or it was '+
      'published without a partner asking for it.'):'')+
    '<div class="tablewrap"><table class="tbl"><thead><tr><th style="min-width:170px">API</th>'+
      '<th>Versions</th><th>Current</th><th class="num">Subscribers</th><th></th></tr></thead><tbody>'+
    API_PRODUCTS.map(a=>{
      const vs=apiVersions(a.id);
      return '<tr><td><div class="cellmain">'+esc(a.name)+'</div>'+
        '<div class="cellsub">'+esc(a.spec)+' · '+esc(a.audience||'Sellers')+'</div></td>'+
        '<td class="t-small">'+vs.map(v=>'<span class="tag" title="'+esc(v.status)+'">'+esc(v.version)+
          (v.breaking?'!':'')+'</span>').join(' ')+'</td>'+
        '<td class="t-small t-num">'+esc(apiCurrent(a.id))+'</td>'+
        '<td class="num t-num'+(apiSubs(a.id).length?'':' dim')+'">'+
          (apiSubs(a.id).length||'None')+'</td>'+
        '<td class="rowend">'+
          '<button class="btn btn-sm btn-quiet" onclick="apiVersionsDialog(\''+a.id+'\')">Versions</button>'+
          '<button class="btn btn-sm btn-quiet" onclick="apiDialog(\''+a.id+'\')">Configure</button>'+
        '</td></tr>';
    }).join('')+'</tbody></table></div>'+
    '<p class="t-tiny muted">A version marked <strong>!</strong> introduced a breaking change. Versions are '+
      'deprecated and then sunset, never deleted — a consumer calling a version nobody can look up cannot be '+
      'diagnosed.</p>',
    {icon:'history', sub:API_PRODUCTS.length+' APIs · '+API_SUBSCRIPTIONS.length+' subscriptions',
     acts:'<button class="btn btn-sm btn-primary" onclick="apiDialog(null)">Publish an API</button>'});
}

function apiSubMatrixPanel(){
  return panel('Who calls what',
    '<p class="t-small muted">APIs down the side, consumers across, showing the version each is on. A dash '+
    'means not subscribed. A version in amber is deprecated or withdrawn.</p>'+
    apiSubMatrix()+
    '<div class="divider"></div>'+
    dt('dtApiSub',{
      rows:API_SUBSCRIPTIONS.slice(), noun:'subscriptions', pageSize:10, idKey:'id',
      searchFields:['consumerName','api','version','env'],
      searchPlaceholder:'Search consumer, API or version',
      chips:[{key:'env',options:[{label:'Production',value:'production'},{label:'Sandbox',value:'sandbox'}]}],
      actions:exportBtn('API subscriptions','dtApiSub'),
      columns:[
        {key:'consumerName',label:'Consumer',render:r=>'<div class="cellmain">'+esc(r.consumerName)+'</div>'+
          '<div class="cellsub">'+esc(r.kind)+'</div>'},
        {key:'api',label:'API',render:r=>'<span class="t-small">'+esc((APIPMAP[r.api]||{}).name||r.api)+'</span>'},
        {key:'version',label:'Version',render:r=>{
          const v=apiVersions(r.api).filter(x=>x.version===r.version)[0]||{};
          return '<span class="t-num t-small">'+esc(r.version)+'</span> '+
            (v.status&&v.status!=='current'&&v.status!=='supported'?pill('warn',v.status):'');}},
        {key:'env',label:'Environment',render:r=>'<span class="t-small">'+esc(r.env)+'</span>'},
        {key:'scopes',label:'Scopes',render:r=>'<span class="t-tiny">'+
          (r.scopes.length?r.scopes.map(x=>esc(x)).join(', '):'<span class="dim">None granted</span>')+'</span>',
          exp:r=>r.scopes.join(' ')},
        {key:'calls30d',label:'Calls, 30 days',align:'right',sort:true,
          render:r=>'<span class="t-num">'+FMT.num(r.calls30d)+'</span>'},
        {key:'since',label:'Since',render:r=>'<span class="t-small muted">'+esc(r.since)+'</span>'}
      ]}),
    {icon:'layers', sub:API_SUBSCRIPTIONS.length+' subscriptions across '+
      new Set(API_SUBSCRIPTIONS.map(s=>s.consumer)).size+' consumers'});
}

/* ==========================================================================
   41. BILL TEMPLATE MANAGER (operator)
   --------------------------------------------------------------------------
   Multiple templates, because the audiences genuinely differ. A consumer bill
   wants a payment slip and one relevant offer; a self-billing invoice to a
   seller wants neither and would look absurd carrying them.

   Four sections cannot be switched off — masthead, parties, taxation and the
   summary. A document without them is not a bill, whatever it is called.
   ========================================================================== */

function billTplUsage(id){
  const A=BILL_TEMPLATE_ASSIGN;
  const out=[];
  ['consumer','enterprise','partner'].forEach(a=>{ if(A[a]===id) out.push('default for '+a); });
  Object.keys(A.overrides||{}).forEach(pid=>{
    if(A.overrides[pid]===id) out.push((PMAP[pid]||{name:pid}).name);
  });
  return out;
}

/* The template the open editor is editing, so the sketch can fall back to its
   saved values for the fields this dialog does not expose. */
let _btEdit = null;
function billTemplateDialog(id){
  const t = id ? BTMAP[id] : null;
  _btEdit = t;
  const isNew = !t;
  const used = t ? billTplUsage(t.id) : [];
  openModal('<div class="modal-head">'+ICO('invoice',18)+
    '<div class="grow"><h3 class="t-sub">'+(isNew?'New bill template':esc(t.name))+'</h3>'+
    '<div class="t-small muted">'+(isNew?'A named set of sections'
      :esc(t.id)+' · '+(used.length?esc(used.join(', ')):'not assigned to anybody'))+'</div></div>'+
    '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      (t&&t.system?banner('info','<strong>Built in.</strong> You can change its sections, but it cannot be '+
        'deleted — an audience with no template has no bill.'):'')+
      '<div class="grid g2">'+
        '<div class="field"><label for="btName">Name</label>'+
          '<input class="inp" id="btName" value="'+esc(t?t.name:'')+'" '+(t?'':'data-autofocus')+
          ' oninput="btPreview()" placeholder="Consumer standard"></div>'+
        '<div class="field"><label for="btTitle">Title printed on the document</label>'+
          '<input class="inp" id="btTitle" value="'+esc(t?t.docTitle:'')+'" oninput="btPreview()" '+
          'placeholder="Your monthly bill">'+
          '<p class="t-tiny muted">"Tax invoice" carries a legal meaning in some jurisdictions. Use it '+
          'deliberately.</p></div>'+
      '</div>'+
      '<div class="grid g2">'+
        '<div class="field"><label for="btAud">Audience</label>'+
          '<select class="inp" id="btAud" onchange="btPreview()">'+
          [['consumer','Consumer'],['enterprise','Enterprise buyer'],['partner','Seller'],['any','Any — assignable']]
            .map(a=>'<option value="'+a[0]+'"'+(t&&t.audience===a[0]?' selected':'')+'>'+esc(a[1])+'</option>').join('')+
          '</select></div>'+
        '<div class="field"><label for="btAccent">Accent</label>'+
          '<input class="inp" id="btAccent" value="'+esc(t?t.accent:'#0D47A1')+'"></div>'+
      '</div>'+
      '<div class="field"><label for="btNote">When to use it</label>'+
        '<input class="inp" id="btNote" value="'+esc(t?(t.note||''):'')+'"></div>'+

      '<div class="divider"></div><h4 class="t-sub" style="margin:0">Sections</h4>'+
      '<p class="t-tiny muted">Four cannot be switched off. A document without the parties, the tax breakdown '+
        'or a summary that reconciles is not a bill.</p>'+
      '<div class="checkgrid">'+BILL_SECTIONS.map(sec=>
        '<label class="checkline"><input type="checkbox" class="btSec" value="'+sec.id+'"'+
        ((!t || billHas(t,sec.id))?' checked':'')+(sec.locked?' disabled checked':'')+
        ' onchange="btPreview()">'+
        '<span>'+esc(sec.label)+(sec.locked?' <span class="t-tiny muted">always on</span>':'')+
        '<span class="t-tiny muted" style="display:block">'+esc(sec.note)+'</span></span></label>').join('')+
      '</div>'+
      '<div id="btWarn"></div>'+
      /* The sketch belongs beside the choices, not on another screen. Ticking
         a section here has to change something visible or the list is a form
         nobody can check their own work against. */
      '<div class="divider"></div><h4 class="t-sub" style="margin:0">How it comes out</h4>'+
      '<div id="btSketch"></div>'+
      '<p class="t-tiny muted">Redrawn as you tick a section. <strong>Preview a bill</strong> generates '+
        'the real PDF on this template.</p>'+
    '</div>'+
    '<div class="modal-foot"><span class="t-tiny muted grow">'+
      (used.length? 'In use: '+esc(used.join(', ')) : 'Not assigned to any audience yet')+'</span>'+
      '<button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      (t?'<button class="btn" onclick="duplicateBillTemplate(\''+t.id+'\')">Duplicate</button>':'')+
      (t&&!t.system&&!used.length?'<button class="btn" onclick="deleteBillTemplate(\''+t.id+'\')">Delete</button>':'')+
      (t?'<button class="btn" onclick="previewBillTemplate(\''+t.id+'\')">Preview a bill</button>':'')+
      '<button class="btn btn-primary" onclick="saveBillTemplate('+(t?'\''+t.id+'\'':'null')+')">'+
        (isNew?'Create it':'Save')+'</button></div>',
    {wide:true,label:'Bill template'});
  btPreview();
}
function btPreview(){
  const host=document.getElementById('btWarn'); if(!host) return;
  const on=Array.prototype.slice.call(document.querySelectorAll('.btSec'))
    .filter(c=>c.checked).map(c=>c.value);
  const aud=(document.getElementById('btAud')||{}).value;
  /* Draw from what is on the form right now, not from the saved record — the
     point of a preview is seeing the change before you commit it. */
  const sk=document.getElementById('btSketch');
  if(sk){
    const v=k=>((document.getElementById(k)||{}).value||'');
    /* Start from the record being edited so the fields this dialog does not
       expose — numbering, currency, remittance — still show something real,
       then lay the live form values over the top. */
    const base = _btEdit ? Object.assign({}, _btEdit) : {
      numbering:'INV-{YYYY}-{SEQ}', nextSeq:1, currency:'USD', taxLabel:'Tax',
      logo:true, showOrderLines:true, remittance:'', footer:''
    };
    base.audience = aud;
    base.sections = on;
    base.name     = v('btName') || base.name || 'Untitled';
    base.docTitle = v('btTitle') || base.docTitle ||
      (aud==='partner' ? 'Self-billing invoice' : 'Invoice');
    sk.innerHTML = billSketch(base,
      aud==='partner' ? 'operator' : aud==='enterprise' ? 'buyer' : 'consumer');
  }
  const msgs=[];
  if(on.indexOf('advert')>-1 && aud!=='consumer')
    msgs.push(banner('warning','An advertisement on an enterprise or seller document is unusual. A procurement '+
      'team did not ask to be sold to on an invoice.'));
  if(on.indexOf('slip')>-1 && aud==='partner')
    msgs.push(banner('warning','A payment slip on a self-billing invoice is backwards — the marketplace pays '+
      'the seller, not the reverse.'));
  if(on.indexOf('howtopay')===-1 && on.indexOf('slip')>-1)
    msgs.push(banner('warning','A payment slip without payment instructions leaves the reader with a reference '+
      'and nowhere to send it.'));
  if(on.indexOf('support')===-1)
    msgs.push(banner('warning','No support block. A bill is where people look when something is wrong with a '+
      'bill, so leaving it off sends them to a search engine.'));
  host.innerHTML = msgs.length? msgs.join('')
    : banner('success','A complete document for this audience.');
}
function saveBillTemplate(id){
  const g=k=>((document.getElementById(k)||{}).value||'').trim();
  const secs=Array.prototype.slice.call(document.querySelectorAll('.btSec'))
    .filter(c=>c.checked).map(c=>c.value);
  const name=g('btName'), title=g('btTitle');
  if(!name||!title){ toast('A template needs a name and a document title','warn'); return; }
  const spec={name:name, docTitle:title, audience:g('btAud'), accent:g('btAccent')||'#0D47A1',
              note:g('btNote')||'', sections:secs};
  if(id){
    Object.assign(BTMAP[id], spec);
    if(typeof audit==='function') audit('bill.template',{object:name, detail:'Template edited · '+secs.length+' sections'});
    closeModal(); toast(name+' saved');
  } else {
    const nid='BT-'+String(BILL_TEMPLATES.length+1).padStart(2,'0');
    const t=Object.assign({id:nid, system:false}, spec);
    BILL_TEMPLATES.push(t); BTMAP[nid]=t;
    if(typeof audit==='function') audit('bill.template',{object:name, after:'created',
      detail:'Template created · '+secs.length+' sections'});
    closeModal(); toast(name+' created — assign it to an audience to use it');
  }
  App.go(App.view);
}
function duplicateBillTemplate(id){
  const t=BTMAP[id]; if(!t) return;
  const nid='BT-'+String(BILL_TEMPLATES.length+1).padStart(2,'0');
  const copy=Object.assign({}, t, {id:nid, name:t.name+' (copy)', system:false,
    sections:t.sections.slice()});
  BILL_TEMPLATES.push(copy); BTMAP[nid]=copy;
  if(typeof audit==='function') audit('bill.template',{object:copy.name, detail:'Duplicated from '+t.name});
  closeModal(); toast(copy.name+' created'); App.go(App.view);
}
function deleteBillTemplate(id){
  const t=BTMAP[id]; if(!t) return;
  if(t.system){ toast('A built-in template cannot be deleted','warn'); return; }
  if(billTplUsage(id).length){ toast('It is assigned to an audience — reassign first','warn'); return; }
  closeModal();
  confirmAction({
    title:'Delete '+t.name, subtitle:t.id, confirmLabel:'Delete it', risk:'high',
    impact:['It is assigned to nobody, so no bill changes.',
            'Bills already issued under it are unaffected — a document is a snapshot, not a live render.'],
    onConfirm:()=>{
      const i=BILL_TEMPLATES.indexOf(t); if(i>-1) BILL_TEMPLATES.splice(i,1);
      delete BTMAP[id];
      if(typeof audit==='function') audit('bill.template',{object:t.name, after:'deleted',
        detail:'Unassigned template deleted', sev:'warn'});
      toast(t.name+' deleted'); App.go(App.view);
    }
  });
}
/* Generate a real bill on this template, so a change can be seen rather than
   imagined. */
function previewBillTemplate(id){
  const t=BTMAP[id]; if(!t) return;
  closeModal();
  const aud = t.audience==='any' ? 'consumer' : t.audience;
  const party = BILL_PARTIES[aud] || BILL_PARTIES.consumer;
  const cfg={
    no:'PREVIEW-'+t.id, template:t, audience:aud, period:'July 2026',
    issued:TODAY, due:'31 Aug 2026', status:'open',
    party:party, account:party.name, accountNo:party.ref, terms:'Net 30',
    subs:[{name:'Managed Firewall — Standard', seller:'Sentinel Cyber', qty:14, rate:24, amount:336},
          {name:'IoT Connect 500 MB', seller:'Aventa Telecom', qty:340, rate:1.4, amount:476}],
    oneoff:[{name:'Devices and professional services', ref:'Jul 2026', date:TODAY, amount:2450}],
    credits:[{name:'Service credit — provisioning delay', ref:'CR-7741', amount:120}],
    taxLines:[{name:'GST — Integrated', rate:'18.0%', base:3142, amount:565.56}],
    recurring:812, oneoffTotal:2450, creditTotal:120, tax:565.56, paid:0,
    total:3707.56, payments:[{date:'12 Jul 2026', method:'Bank transfer', ref:'TRF-9902', amount:0}]
  };
  cfg.advert=billAdvert(cfg);
  billDoc(cfg);
  toast('Preview generated on '+t.name);
}

