/* Which drawing a product gets. Category first, then a keyword in the name for
   the cases a category cannot separate — a tablet and a phone share "Phones"
   in nobody's catalogue, but a mesh pack and a CPE do share "Routers". */
function prodArtKey(p){
  const n=(p.name||'').toLowerCase(), c=p.cat||'';
  if(/mesh|wi-?fi/.test(n)) return 'router';
  if(/cpe|fixed wireless/.test(n)) return 'cpe';
  /* A kit of several things is a kit, whatever is in it. Checked before the
     component types or a starter of 25 sensors draws as one sensor. */
  if(/starter|bundle| duo\b|essentials/.test(n)) return 'bundle';
  if(/tab\b|tablet/.test(n)) return 'tablet';
  if(/watch|band/.test(n)) return 'watch';
  if(/charger|cable|gan|adapter/.test(n)) return 'charger';
  if(/gateway/.test(n)) return 'gateway';
  if(/tracker|telematics/.test(n)) return 'tracker';
  if(/sensor|cold-chain|occupancy|air quality/.test(n)) return 'sensor';
  if(/esim|sim|connect \d/.test(n)) return 'sim';
  if(/firewall/.test(n)) return 'firewall';
  if(/mdr|detection|response/.test(n)) return 'watchtower';
  if(/ztna|secure access|vpn/.test(n)) return 'zt';
  if(/endpoint/.test(n)) return 'laptop';
  if(/mail|defence|defense/.test(n)) return 'mail';
  if(/storage|vault/.test(n)) return 'cloud';
  if(/music|audio/.test(n)) return 'music';
  if(/gaming|game|loot|season pass/.test(n)) return 'game';
  if(/stream|sports|4k|premium|standard/.test(n) && p.v==='content') return 'stream';
  if(/insurance|protect|cover/.test(n)) return 'insurance';
  if(/storefront|white-label/.test(n)) return 'storefront';
  if(/api|sandbox/.test(n)) return 'api';
  if(/pack|bundle|duo|starter|essentials/.test(n)) return 'bundle';
  if(/seats|lines|wholesale/.test(n)) return 'seats';
  const byCat={'Phones':'phone','Tablets':'tablet','Routers':'router','CPE':'cpe','Wearables':'watch',
    'Accessories':'charger','Streaming':'stream','Gaming':'game','Music':'music','Cloud storage':'cloud',
    'IoT SIM plans':'sim','Sensors':'sensor','Trackers':'tracker','Gateways':'gateway','Bundles':'bundle',
    'Managed firewall':'firewall','MDR':'watchtower','VPN / ZTNA':'zt','Endpoint':'laptop',
    'Email security':'mail','Mobile plans':'plan','Insurance':'insurance','Reseller packs':'seats',
    'Enablement':'api'};
  return byCat[c] || 'bundle';
}
/* Colour comes from the marketplace category so the grid still groups by eye,
   with a per-product accent so twelve handsets are not twelve identical tiles. */
const V_INK  ={consumer:'#0B5FA5',partner:'#8A5300',iot:'#00676B',security:'#146C43',device:'#5E4B9B',content:'#9B2C6F'};
const V_TINT ={consumer:'#E9F3FC',partner:'#FFF3E0',iot:'#E3F3F3',security:'#E7F4EC',device:'#EFEBFA',content:'#FBEAF3'};
const V_ACC  ={consumer:['#0B5FA5','#1273C4','#2E8BD8'],partner:['#8A5300','#A8690C','#C07C18'],
               iot:['#00676B','#068C90','#1AA3A7'],security:['#146C43','#1C8A57','#2AA36B'],
               device:['#5E4B9B','#7360B4','#8A77C9'],content:['#9B2C6F','#B53C84','#C85399']};
function productArt(p, h){
  const key=prodArtKey(p);
  const draw=PROD_ART[key]||PROD_ART.bundle;
  const ink=V_INK[p.v]||'#4A4A4A', tint=V_TINT[p.v]||'#F4F4F4';
  const pool=V_ACC[p.v]||[ink];
  /* Deterministic per product, so a tile does not change colour on re-render. */
  let n=0; String(p.id||p.name||'').split('').forEach(c=>{n=(n*31+c.charCodeAt(0))>>>0;});
  const a=pool[n%pool.length];
  const id=ART_ID();
  return '<svg class="partsvg" viewBox="0 0 200 130" role="img" aria-label="Illustration of '+
    esc(p.name||'the product')+'" preserveAspectRatio="xMidYMid meet" '+
    'style="width:100%;height:'+(h||118)+'px;display:block;background:'+tint+'">'+
    _artDefs(id, ink, a)+draw(id, ink, a)+'</svg>';
}

/* ================= §4.58  WHAT THE SELLER GAVE US, AND CAN CHANGE =========
   A seller's own record of the settlement instruction, the tax position and
   the evidence submitted at each onboarding gate. Held here rather than only
   in the operator console, because a seller who cannot see what we hold about
   them cannot correct it and cannot answer their own auditor.
   ======================================================================== */
function sellerComplianceView(pid){
  const p=PMAP[pid]; if(!p) return '';
  const b=bankFor(pid);
  const subs=ONB_SUBMISSIONS[pid]||{};
  const gates=ONB_STEPS.filter(g=>subs[g.id]);
  return panel('Settlement account',
    (b? bankSummary(pid,{onAdd:"changeBankDialog('"+pid+"')"}) : bankSummary(pid))+
    '<div class="divider"></div>'+
    banner('warning','<strong>Changing where money is paid is the change most worth attacking.</strong> '+
      'A new account does not take effect on save — it is re-verified by micro-deposit, the marketplace '+
      'is notified, and payouts hold on the old account until the new one is confirmed.'),
    {icon:'wallet',
     acts:'<button class="btn btn-sm btn-primary" onclick="changeBankDialog(\''+pid+'\')">'+
       ICO('settings',13)+'Change settlement account</button>'})+

  panel('Tax position',
    b? dl([['Tax residency', b.residency],
           [b.taxLabel, '<span class="t-num">'+maskTaxId(b.taxId)+'</span>'],
           ['Treaty certificate', b.treaty.onFile
             ? 'On file, valid to '+b.treaty.expires : 'Not supplied'],
           ['Withholding applied to your settlements', b.treaty.withholding],
           ['Where this bites', b.treaty.onFile
             ? 'Nothing is withheld while the certificate is valid. It has to be renewed before it expires '+
               'or the statutory rate resumes automatically.'
             : 'Without a certificate the statutory rate comes off every settlement at source. It is not '+
               'a penalty and we cannot waive it — it is withheld and paid to the authority.']])
      : stateBlock('empty','No tax position on file','Recorded at the bank and tax gate.'),
    {icon:'file',
     acts:'<button class="btn btn-sm" onclick="uploadTreatyDialog(\''+pid+'\')">'+ICO('upload',13)+
       'Upload a certificate</button>'})+

  panel('What you submitted at onboarding',
    gates.length
      ? '<p class="t-small">Every gate you cleared, and the evidence it was cleared on. This is the same '+
        'record the marketplace reads.</p>'+
        '<div class="stack" style="gap:9px">'+gates.map(g=>{
          const sub=subs[g.id];
          const tasks=(typeof onbTasksFor==='function')? onbTasksFor(pid,g.id) : [];
          const openN=tasks.filter(t=>t.status!=='done'&&t.status!=='notstarted').length;
          return '<section class="modcard"><div class="modcard-head">'+
            '<div class="grow"><div class="t-sub">'+esc(g.name)+'</div>'+
            '<div class="t-tiny muted">'+esc(g.desc)+'</div></div>'+
            (openN? pill('pending',openN+' open') : pill('approved','Cleared'))+'</div>'+
            '<div class="modcard-body">'+
              '<div class="t-tiny muted" style="margin-bottom:7px">Submitted by '+esc(sub.submittedBy)+
              ' on '+esc(sub.submittedOn)+
              (sub.reviewedBy? ' · reviewed by '+esc(sub.reviewedBy)+' on '+esc(sub.reviewedOn) : '')+'</div>'+
              '<div class="tablewrap"><table class="tbl"><tbody>'+
              sub.fields.map(f=>'<tr><td style="width:44%"><span class="t-small muted">'+esc(f[0])+
                '</span></td><td><span class="t-small strong">'+esc(f[1])+'</span></td></tr>').join('')+
              '</tbody></table></div>'+
              ((sub.docs||[]).length
                ? '<div class="divider"></div><div class="stack" style="gap:6px">'+
                  sub.docs.map(dd=>'<div class="row" style="gap:9px">'+
                    '<span class="cartthumb" style="width:28px;height:28px">'+ICO('file',13)+'</span>'+
                    '<div class="grow"><div class="t-small strong">'+esc(dd[0])+'</div>'+
                    '<div class="t-tiny muted">'+esc(dd[1])+' · '+esc(dd[2])+'</div></div>'+
                    '<button class="btn btn-sm btn-quiet" onclick="viewGateDoc('+
                      JSON.stringify(dd[0]).replace(/"/g,'&quot;')+','+
                      JSON.stringify(p.name).replace(/"/g,'&quot;')+')">View</button></div>').join('')+
                  '</div>'
                : '<p class="t-tiny muted" style="margin-top:7px">No documents were attached to this gate.</p>')+
            '</div></section>';
        }).join('')+'</div>'
      : stateBlock('empty','Nothing submitted yet',
          'What you send at each onboarding gate appears here, with the documents attached to it.'),
    {icon:'checklist', sub:gates.length+' of '+ONB_STEPS.length+' gates have a record'});
}

function changeBankDialog(pid){
  const p=PMAP[pid], b=bankFor(pid)||{};
  const c=bankCodeFor(p?p.country:'');
  openModal('<div class="modal-head">'+ICO('wallet',18)+'<div class="grow">'+
      '<h3 class="t-sub">Change the settlement account</h3>'+
      '<div class="t-small muted">'+esc(p?p.name:pid)+' · currently '+esc(maskAcct(b.account))+
      ' at '+esc(b.bank||'—')+'</div></div>'+
      '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('warning','<strong>Nothing is paid to a new account until it is verified.</strong> Two '+
        'micro-deposits are sent and the amounts have to be confirmed. Until then settlements keep '+
        'running to the account on file, and the marketplace is told the account was changed and by whom.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="cbHolder">Account holder</label>'+
          '<input class="inp" id="cbHolder" data-autofocus value="'+esc(b.holder||(p?p.name:''))+'">'+
          '<div class="hint">It has to match the registered entity. A personal account in a director’s '+
          'name is refused.</div></div>'+
        '<div class="field"><label for="cbBank">Bank</label>'+
          '<input class="inp" id="cbBank" placeholder="'+esc(b.bank||'Bank name')+'"></div>'+
        '<div class="field"><label for="cbAcct">New account number</label>'+
          '<input class="inp" id="cbAcct" placeholder="Digits only"></div>'+
        '<div class="field"><label for="cbAcct2">Confirm the account number</label>'+
          '<input class="inp" id="cbAcct2" placeholder="Type it again"></div>'+
        '<div class="field"><label for="cbLocal">'+esc(c.local)+'</label>'+
          '<input class="inp" id="cbLocal" placeholder="'+esc(c.localEg)+'"></div>'+
        '<div class="field"><label for="cbSwift">SWIFT / BIC</label>'+
          '<input class="inp" id="cbSwift" placeholder="'+esc(b.swift||'HDFCINBB')+'"></div>'+
      '</div>'+
      '<div class="field"><label for="cbWhy">Why it is changing</label>'+
        '<input class="inp" id="cbWhy" placeholder="Moved banking to a new provider on 20 Jul">'+
        '<div class="hint">Recorded and visible to the marketplace. An unexplained payout change is the '+
        'shape every account-takeover takes.</div></div>'+
      '<div id="cbOut"></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="submitBankChange(\''+pid+'\')">Submit for verification</button>'+
    '</div>', {wide:true, label:'Change the settlement account'});
}
function submitBankChange(pid){
  const v=k=>((document.getElementById(k)||{}).value||'').trim();
  const out=document.getElementById('cbOut');
  const acct=v('cbAcct').replace(/\s+/g,''), acct2=v('cbAcct2').replace(/\s+/g,'');
  const holder=v('cbHolder'), bank=v('cbBank'), why=v('cbWhy');
  const say=h=>{ if(out) out.innerHTML=banner('danger',h); };
  if(!holder){ say('<strong>The account holder is required.</strong>'); return; }
  if(!bank){ say('<strong>Name the bank.</strong> An account number with no bank cannot be paid to.'); return; }
  if(!acct){ say('<strong>Enter the new account number.</strong>'); return; }
  if(acct!==acct2){ say('<strong>The two account numbers do not match.</strong> Check both — this is the '+
    'one field where a typo sends money to a stranger.'); return; }
  const b=bankFor(pid);
  if(b && acct===b.account){ say('<strong>That is the account already on file.</strong> Nothing to change.');
    return; }
  if(!why){ say('<strong>Say why it is changing.</strong> An unexplained payout change is the shape every '+
    'account-takeover takes, so the reason is required rather than optional.'); return; }
  const p=PMAP[pid];
  if(b){
    b.pending={account:acct, holder:holder, bank:bank, localCode:v('cbLocal')||b.localCode,
               swift:v('cbSwift')||b.swift, why:why, requestedOn:TODAY,
               requestedBy:((typeof orgUsers==='function'&&
                 (orgUsers(App.cfg.orgCtx).filter(u=>u.you)[0]||{}).name)||'The seller')};
  }
  if(typeof audit==='function') audit('bank.recorded',{object:(p?p.name:pid),
    before:maskAcct(b?b.account:''), after:maskAcct(acct),
    detail:'Change requested — '+why+'. Payouts hold on the old account until micro-deposits are matched.',
    sev:'high'});
  closeModal();
  toast('Two micro-deposits are on their way to '+maskAcct(acct)+' — payouts stay on the old account until '+
    'you confirm the amounts');
  App.go(App.view);
}
function uploadTreatyDialog(pid){
  const b=bankFor(pid); if(!b) return;
  confirmAction({title:'Upload a tax residency certificate',
    subtitle:(PMAP[pid]||{}).name+' · '+b.residency,
    risk:'normal', confirmLabel:'Record it',
    body:banner('info','<strong>A valid certificate applies the treaty rate to your settlements.</strong> '+
      'It is not backdated — anything already withheld stays withheld and is reclaimed from the authority, '+
      'not from us.')+
      '<div class="grid g2">'+
        '<div class="field"><label for="tcIssued">Issued</label>'+
          '<input class="inp" id="tcIssued" placeholder="01 Apr 2026" data-autofocus></div>'+
        '<div class="field"><label for="tcExp">Valid to</label>'+
          '<input class="inp" id="tcExp" placeholder="31 Mar 2028"></div>'+
      '</div>',
    impact:['The certificate is queued for review by the marketplace finance desk.',
            'Withholding changes on the settlement run after it is accepted, not before.',
            'You are reminded 60 days before it expires, because the statutory rate resumes on its own.'],
    validate:(v)=>((v&&v.tcExp)||'').trim() ? null
      : '<strong>A certificate with no expiry date cannot be checked.</strong> The whole point of the '+
        'reminder is knowing when the treaty rate stops applying.',
    onConfirm:(v)=>{
      const exp=((v&&v.tcExp)||'').trim();
      b.treaty={onFile:true, expires:exp, withholding:'Nil under treaty — pending marketplace review'};
      if(typeof audit==='function') audit('bank.recorded',{object:(PMAP[pid]||{}).name,
        detail:'Tax residency certificate recorded, valid to '+exp});
      toast('Certificate recorded — withholding changes on the next settlement run after review');
      App.go(App.view);
    }});
}

/* ---------------------------- action columns ------------------------------
   A table's action column has to hold its shape. When the primary action only
   exists on some rows, an empty slot lets the secondary action walk left and
   right down the column, and the eye reads that movement as noise before it
   reads any of the words.

   So the primary slot is always drawn. On a row where the action is genuinely
   unavailable it holds a non-interactive marker saying what happened instead —
   which is more useful than a gap and more honest than a greyed-out button
   that implies the action might come back.
   ------------------------------------------------------------------------ */
function actionCell(secondary, primary, opts){
  opts=opts||{};
  /* The fixed slot exists to line a column up. In a narrow table it does the
     opposite — it forces the pair apart until they stack — so a compact cell
     keeps the group together and gives up the column alignment it cannot have
     anyway. */
  if(opts.compact){
    return '<span class="actcell is-compact">'+(secondary||'')+(primary||'')+'</span>';
  }
  return '<span class="rowend actcell"'+(opts.width?' style="--slot:'+opts.width+'"':'')+'>'+
    (secondary||'')+
    '<span class="actslot">'+(primary||'')+'</span></span>';
}
/* The filled-but-inert slot. Not a button: it has no role, no tab stop and no
   hover, because there is nothing here to press. */
function actionDone(label, sub){
  return '<span class="actghost">'+SH('check',11)+
    '<span class="agl">'+esc(label)+(sub?' <span class="agsub">'+esc(sub)+'</span>':'')+'</span></span>';
}
function actionHeld(label, sub){
  return '<span class="actghost is-held">'+SH('dash',11)+
    '<span class="agl">'+esc(label)+(sub?' <span class="agsub">'+esc(sub)+'</span>':'')+'</span></span>';
}
/* What goes in the primary slot of a settlement row. Defined once, because a
   statement that offers Review and approve in one table and nothing in the
   other is one screen disagreeing with itself.

   On a row that is already approved the slot is filled rather than emptied,
   and it names the action that was taken and who took it. A greyed-out
   "Review and approve" was the other option and it is the wrong one: a
   disabled control says "not now", which invites the reader to wait for it to
   come back. This one has already happened and is never coming back. */
function settleActionSlot(r){
  if(r.status==='pending')
    return '<button class="btn btn-sm btn-primary" onclick="event.stopPropagation();openStatement(\''+
      r.id+'\')">Review and approve</button>';
  if(r.status==='paid')
    return actionDone('Paid', r.paidOn||'');
  return actionDone('Reviewed and approved',
    (r.approvedBy? r.approvedBy.split(' ')[0]+', ':'')+(r.approvedOn||''));
}

/* ======================= §4.62  MEDIA — VIEW AND TAKE AWAY ================
   A media list you can only read the filename of is a list of claims. Every
   item opens, and every item downloads something real: an image leaves as the
   artwork itself, a document as a PDF, and a video as its still — because the
   still is what the platform actually holds and pretending otherwise would put
   an empty file on somebody's disk.
   ======================================================================== */
function findMedia(mid){
  if(typeof PRODUCT_MEDIA!=='undefined'){
    for(const k in PRODUCT_MEDIA){
      const hit=(PRODUCT_MEDIA[k]||[]).filter(x=>x.id===mid)[0];
      if(hit) return {m:hit, product:(typeof SKUMAP!=='undefined'? SKUMAP[k] : null)};
    }
  }
  if(typeof NL!=='undefined' && NL.media){
    const hit=NL.media.filter(x=>x.id===mid)[0];
    if(hit) return {m:hit, product:{id:'NL-draft', name:NL.name||'New listing', v:NL.v, cat:NL.cat||''}};
  }
  return null;
}
function mediaKindLabel(k){
  return ((typeof MEDIA_KINDS!=='undefined' && MEDIA_KINDS.filter(x=>x.id===k)[0])||{}).label||k;
}
function viewMedia(mid, pid){
  const found=findMedia(mid); if(!found) return;
  const m=found.m;
  const p=(pid && typeof SKUMAP!=='undefined' && SKUMAP[pid]) ? SKUMAP[pid] : found.product;
  const isImg=m.kind==='image', isVid=m.kind==='video';
  const body =
    isImg || isVid
      ? '<div class="mediastage">'+
          (p && typeof productArt==='function' ? productArt(p, 260)
             : '<div class="state state-unavailable">'+ICO('image',22)+'</div>')+
          (isVid?'<span class="mediaplay" aria-hidden="true">'+ICO('play',26)+'</span>':'')+
          (m.shot?'<span class="mediashot">'+esc(m.shot)+'</span>':'')+
        '</div>'+
        (isVid
          ? banner('info','<strong>This is the still the catalogue uses.</strong> The clip itself is held '+
            'by the seller’s media service and plays on the storefront; what the marketplace keeps here is '+
            'the frame, the duration and the description.')
          : '')
      : '<div class="doc-preview" style="min-height:170px">'+
          '<div class="doc-head"><div class="doc-logo">'+esc(p?p.seller||p.name:'Document')+'</div>'+
          '<div class="doc-title">'+esc(m.name)+'</div></div>'+
          '<div class="doc-meta"><span>Type <strong>'+esc(mediaKindLabel(m.kind))+'</strong></span>'+
          '<span>Size <strong>'+esc(m.mb)+' MB</strong></span></div>'+
          '<div class="doc-block">'+esc(m.alt||'No description was supplied for this document.')+'</div>'+
        '</div>';
  openModal('<div class="modal-head">'+ICO(isImg?'image':isVid?'play':'file',18)+'<div class="grow">'+
      '<h3 class="t-sub">'+esc(m.name)+'</h3>'+
      '<div class="t-small muted">'+esc(mediaKindLabel(m.kind))+
      (p?' · '+esc(p.name):'')+(m.primary?' · primary image':'')+'</div></div>'+
      '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      body+
      dl([['File', m.name],
          ['Kind', mediaKindLabel(m.kind)],
          ['Dimensions', m.px || '*Not applicable*'],
          ['Size', m.mb+' MB'],
          ['Duration', m.secs? m.secs+' seconds' : '*Not applicable*'],
          ['Shot', m.shot || '*Not stated*'],
          ['Description', m.alt || '*None — this cannot be published without one*']])+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Close</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="downloadMedia(\''+mid+'\',\''+(p?p.id:'')+'\')">'+
        ICO('download',13)+(isVid?'Download the still':'Download')+'</button>'+
    '</div>', {wide:true, label:m.name});
}
function downloadMedia(mid, pid){
  const found=findMedia(mid); if(!found) return;
  const m=found.m;
  const p=(pid && typeof SKUMAP!=='undefined' && SKUMAP[pid]) ? SKUMAP[pid] : found.product;
  const base=String(m.name||'media').replace(/\.[a-z0-9]+$/i,'').replace(/[^\w.-]+/g,'-');

  if(m.kind==='doc'){
    /* A real PDF, through the same writer the rest of the platform uses. */
    if(typeof downloadGateDocPdf==='function'){
      downloadGateDocPdf(m.name, p? (p.seller||p.name) : 'Marketplace');
      if(typeof audit==='function') audit('doc.viewed',{object:m.name,
        detail:'Downloaded from the listing media'});
      return;
    }
  }
  /* An image, or a video's still: the artwork is vector, so it leaves as one
     rather than as a screenshot of one. */
  const svg = (p && typeof productArt==='function') ? productArt(p, 600) : null;
  if(!svg){ toast('There is nothing held for this item to download','warn'); return; }
  const clean = svg.replace(/^<svg /,'<svg xmlns="http://www.w3.org/2000/svg" ')
                   .replace(/style="[^"]*"/, 'width="900" height="585" viewBox="0 0 200 130"');
  const file = '<?xml version="1.0" encoding="UTF-8"?>\n'+
    '<!-- '+(m.name||'')+' · '+(p?p.name:'')+' · '+(m.alt||'')+' -->\n'+clean;
  const ok=downloadFile(base+'.svg', file, 'image/svg+xml');
  /* A shopper taking a copy of a public catalogue image is not an auditable
     event, and logging it only buries the ones that are. Inside a console it
     is recorded, because there the media belongs to a seller. */
  const ctx=(typeof App!=='undefined'&&App.cfg)?App.cfg.orgCtx:null;
  if(typeof audit==='function' && (ctx==='operator'||ctx==='partner'))
    audit('doc.viewed',{object:m.name,
      detail:'Downloaded from the listing media'+(m.kind==='video'?' (still frame)':'')});
  toast(ok ? (m.kind==='video'?'Still downloaded as '+base+'.svg':base+'.svg downloaded')
           : 'The download could not start','ok');
}

/* ======================= §4.63  WALLETS — THE OPERATOR'S VIEW =============
   The customer sees a balance. The operator has to see the obligation: how
   much is held, whose money it actually is, what is going dormant, and where
   it sits in the ledger. Stored value that nobody watches is how a platform
   discovers it owes six figures it had booked as income.
   ======================================================================== */
function walletSourceLabel(id){
  const x=(WALLET_POLICY.sources||[]).filter(s=>s.id===id)[0];
  return x? x.label : (id==='spend'?'Spent in the marketplace':id);
}
function walletsOperatorView(){
  const L=walletLiability();
  const moves=WALLET_LEDGER.slice();
  const inFlow=+moves.filter(t=>t.amount>0).reduce((a,t)=>a+t.amount,0).toFixed(2);
  const outFlow=+moves.filter(t=>t.amount<0).reduce((a,t)=>a+Math.abs(t.amount),0).toFixed(2);

  return pagehead(WALLET_POLICY.name,
    'What the marketplace is holding on behalf of customers, and whose money each part of it is.',
    exportBtn('Wallet ledger','walletLedger')+
    '<button class="btn" onclick="walletPolicyDialog()">'+ICO('shield',13)+'Wallet policy</button>')+
  '<div class="stack">'+

  banner('warning','<strong>A wallet balance is money the platform is holding for somebody else.</strong> '+
    'Unlike a reward point it is real money, and in most places the holder can ask for it back. It is never '+
    'income, however long it sits there.')+

  '<div class="grid g4">'+
    metric({icon:'wallet',label:'Held in wallets',value:CUR(L.total),
      foot:'Across '+L.accounts+' accounts'})+
    metric({icon:'lock',label:'The customer’s own money',value:CUR(L.cash),
      foot:'Top-ups and refunds — refundable on request'})+
    metric({icon:'zap',label:'Credit we issued',value:CUR(L.promo),
      foot:'Rewards and goodwill — spendable, not refundable'})+
    metric({icon:'clock',label:'Dormant',value:L.dormant?CUR(L.dormantValue):null,
      naLabel:'None dormant',
      foot:L.dormant? L.dormant+' account'+(L.dormant===1?'':'s')+' with no movement for '+
        WALLET_POLICY.dormancyMonths+' months' : 'Every account has moved recently'})+
  '</div>'+

  panel('Whose money it is',
    '<div class="grid g2"><div>'+
      dl([['Held in total', CUR(L.total)],
          ['Refundable as cash', CUR(L.cash)],
          ['Not refundable as cash', CUR(L.promo)],
          ['Topped up to date', CUR(inFlow)],
          ['Spent in the marketplace', CUR(outFlow)],
          ['Liability account', WALLET_POLICY.liabilityAccount+' — '+
            ((typeof GLMAP!=='undefined'&&GLMAP[WALLET_POLICY.liabilityAccount])
              ? GLMAP[WALLET_POLICY.liabilityAccount].name : 'Customer wallet liability')],
          ['Maximum balance', CUR(WALLET_POLICY.maxBalance)],
          ['Minimum top-up', CUR(WALLET_POLICY.minTopUp)]])+
    '</div><div class="stack" style="gap:9px">'+
      banner('info','<strong>Refundable.</strong> '+esc(WALLET_POLICY.cashRefundable))+
      banner('warning','<strong>Not refundable.</strong> '+esc(WALLET_POLICY.nonRefundable))+
      banner('stale','<strong>Dormancy.</strong> '+esc(WALLET_POLICY.dormancyNote))+
    '</div></div>',
    {icon:'wallet'})+

  panel('Where the money comes from',
    '<div class="tablewrap"><table class="tbl"><thead><tr><th>Source</th>'+
      '<th class="num">Movements</th><th class="num">Value</th><th>Pot</th><th>What it means</th>'+
      '</tr></thead><tbody>'+
    (WALLET_POLICY.sources||[]).map(src=>{
      const rows=WALLET_LEDGER.filter(t=>t.source===src.id);
      const val=+rows.reduce((a,t)=>a+t.amount,0).toFixed(2);
      return '<tr><td class="t-small"><strong>'+esc(src.label)+'</strong></td>'+
        '<td class="num t-num">'+rows.length+'</td>'+
        '<td class="num t-num">'+CUR(val)+'</td>'+
        '<td class="t-small">'+(src.id==='reward'||src.id==='goodwill'
          ? '<span class="warntext">'+SH('bang',11)+'Not refundable</span>'
          : '<span class="okmark">'+SH('check',11)+'The customer’s</span>')+'</td>'+
        '<td class="t-small muted">'+esc(src.note)+'</td></tr>';
    }).join('')+'</tbody></table></div>',
    {icon:'layers'})+

  panel('Accounts', dt('dtWal',{
    rows:WALLETS, noun:'wallets', pageSize:10, sortKey:'balance', sortDir:'desc', idKey:'id',
    onRow:"openWallet('$ID')",
    searchFields:['id','name','party'], searchPlaceholder:'Search holder, account or wallet id',
    chips:[{key:'state',options:[{label:'Active',value:'active'},{label:'Dormant',value:'dormant'}]},
      {key:'kind',options:[{label:'Consumer',value:'consumer'},{label:'Enterprise',value:'enterprise'}]}],
    columns:[
      {key:'name',label:'Holder',render:w=>'<div class="cellmain">'+esc(w.name)+'</div>'+
        '<div class="cellsub t-num">'+esc(w.party)+'</div>'},
      {key:'kind',label:'Kind',render:w=>esc(w.kind==='enterprise'?'Enterprise':'Consumer')},
      {key:'cash',label:'Their money',align:'right',render:w=>'<span class="t-num">'+CUR(w.cash)+'</span>'},
      {key:'promo',label:'Credit we issued',align:'right',render:w=>w.promo
        ? '<span class="t-num">'+CUR(w.promo)+'</span>' : '<span class="dim">—</span>'},
      {key:'balance',label:'Balance',align:'right',render:w=>'<span class="t-num cellmain">'+
        CUR(w.balance)+'</span>'},
      {key:'lastMove',label:'Last movement',render:w=>esc(w.lastMove)},
      {key:'state',label:'State',render:w=>w.state==='dormant'
        ? pill('stale','Dormant') : pill('active','Active')},
      {key:'_act',label:'',align:'right',render:w=>actionCell(
        '<button class="btn btn-sm btn-quiet" onclick="event.stopPropagation();openWallet(\''+w.id+
          '\')">Open</button>',
        w.state==='dormant'
          ? '<button class="btn btn-sm" onclick="event.stopPropagation();returnWallet(\''+w.id+
            '\')">Return it</button>'
          : actionDone('Active', w.lastMove),
        {width:'112px'})}
    ]}),
    {flush:true, icon:'group',
     sub:L.accounts+' accounts · '+CUR(L.total)+' held · a balance nobody watches is a balance nobody returns'})+

  panel('Every movement', dt('dtWalTx',{
    rows:WALLET_LEDGER, noun:'movements', pageSize:12, sortKey:'when', sortDir:'desc', idKey:'id',
    searchFields:['id','name','what'], searchPlaceholder:'Search a movement, holder or reason',
    chips:[{key:'source',options:(WALLET_POLICY.sources||[]).map(x=>({label:x.label,value:x.id}))
      .concat([{label:'Spent',value:'spend'}])}],
    columns:[
      {key:'when',label:'When',render:t=>esc(t.when)},
      {key:'name',label:'Holder',render:t=>esc(t.name)},
      {key:'source',label:'Source',render:t=>esc(walletSourceLabel(t.source))},
      {key:'what',label:'What',render:t=>'<span class="t-small">'+esc(t.what)+'</span>'},
      {key:'pot',label:'Pot',render:t=>t.pot==='promo'
        ? '<span class="t-tiny warntext">Credit we issued</span>'
        : '<span class="t-tiny muted">The customer’s</span>'},
      {key:'amount',label:'Amount',align:'right',render:t=>'<span class="t-num cellmain'+
        (t.amount<0?' negnum':'')+'">'+(t.amount<0?'−':'+')+CUR(Math.abs(t.amount))+'</span>'}
    ]}),
    {flush:true, icon:'list'})+
  '</div>';
}
function openWallet(id){
  const w=WALMAP[id]; if(!w) return;
  const rows=walletLedgerFor(id);
  openInspector('<div class="insp-head">'+ICO('wallet',18)+'<div class="grow">'+
      '<div class="row" style="gap:6px">'+(w.state==='dormant'?pill('stale','Dormant'):pill('active','Active'))+
      '<span class="tag">'+esc(w.kind==='enterprise'?'Enterprise':'Consumer')+'</span></div>'+
      '<h3 class="t-sub" style="margin-top:5px">'+esc(w.name)+'</h3>'+
      '<div class="t-small muted t-num">'+esc(w.id)+' · '+esc(w.party)+'</div></div>'+
      '<button class="iconbtn" onclick="closeInspector()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="insp-body stack">'+
      (w.state==='dormant'
        ? banner('warning','<strong>No movement since '+esc(w.lastMove)+'.</strong> '+esc(w.note||'')+
          ' The balance is returned or escheated — it is not absorbed as income, whatever the terms say.')
        : banner('info','<strong>'+CUR(w.cash)+' of this is the holder’s own money</strong> and is returned '+
          'on request to the instrument that funded it. '+CUR(w.promo)+' is credit the marketplace issued '+
          'and is spendable here only.'))+
      dl([['Balance', CUR(w.balance)],
          ['Their money', CUR(w.cash)+' — refundable'],
          ['Credit we issued', CUR(w.promo)+' — not refundable as cash'],
          ['Opened', w.opened],
          ['Last movement', w.lastMove],
          ['Movements', String(rows.length)],
          ['Against the ceiling', CUR(w.balance)+' of '+CUR(WALLET_POLICY.maxBalance)],
          ['Posted to', WALLET_POLICY.liabilityAccount+' — customer wallet liability']])+
      '<div class="divider"></div><h4 class="t-sub" style="margin-bottom:7px">Movements</h4>'+
      '<div class="tablewrap"><table class="tbl"><thead><tr><th>When</th><th>What</th>'+
        '<th class="num">Amount</th></tr></thead><tbody>'+
      rows.map(t=>'<tr><td class="t-small">'+esc(t.when)+'</td>'+
        '<td class="t-small">'+esc(t.what)+'<div class="cellsub t-tiny">'+
          esc(walletSourceLabel(t.source))+'</div></td>'+
        '<td class="num t-num'+(t.amount<0?' negnum':'')+'">'+(t.amount<0?'−':'+')+
          CUR(Math.abs(t.amount))+'</td></tr>').join('')+
      '</tbody></table></div>'+
    '</div>'+
    '<div class="insp-foot"><button class="btn btn-quiet" onclick="closeInspector()">Close</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-sm" onclick="closeInspector();adjustWallet(\''+w.id+'\')">Adjust</button>'+
      (w.cash>0
        ? '<button class="btn btn-sm btn-primary" onclick="closeInspector();returnWallet(\''+w.id+
          '\')">Return the balance</button>' : '')+
    '</div>', 'Wallet '+w.id);
}
function returnWallet(id){
  const w=WALMAP[id]; if(!w) return;
  if(w.cash<=0){ toast('There is nothing refundable in this wallet — the balance is credit we issued','warn');
    return; }
  confirmAction({title:'Return '+CUR(w.cash)+' to '+w.name,
    subtitle:w.id+' · '+CUR(w.balance)+' held, '+CUR(w.promo)+' of it not refundable',
    risk:'high', confirmLabel:'Return it',
    body:banner('warning','<strong>Only the holder’s own money goes back.</strong> '+CUR(w.cash)+
      ' of top-ups and refunds returns to the instrument that funded it. '+CUR(w.promo)+
      ' of reward and goodwill credit does not — it was never their money, and the screen says so rather '+
      'than quietly returning less than the balance shown.'),
    impact:[CUR(w.cash)+' leaves the wallet and the liability on '+WALLET_POLICY.liabilityAccount+
              ' falls by the same amount.',
            CUR(w.promo)+' of issued credit stays in the wallet and remains spendable here.',
            'The holder is told what was returned and what was not.'],
    onConfirm:()=>{
      const amt=w.cash;
      WALLET_LEDGER.unshift({id:'WTX-'+(79000+WALLET_LEDGER.length), wallet:w.id, party:w.party,
        name:w.name, when:TODAY, source:'refundout',
        what:'Balance returned to the holder at their request', amount:-amt, pot:'cash'});
      w.cash=0; w.balance=+w.promo.toFixed(2); w.lastMove=TODAY; w.state='active'; w.note=null;
      if(typeof SHOPPER!=='undefined' && w.party===SHOPPER.id) SHOPPER.wallet=w.balance;
      if(typeof audit==='function') audit('wallet.adjusted',{object:w.name,
        before:CUR(amt+w.balance), after:CUR(w.balance), amount:amt,
        detail:'Balance returned at the holder’s request — issued credit retained'});
      toast(CUR(amt)+' returned to '+w.name+' — '+CUR(w.promo)+' of issued credit stays');
      App.go(App.view);
    }});
}
function adjustWallet(id){
  const w=WALMAP[id]; if(!w) return;
  confirmAction({title:'Adjust '+w.name+'’s wallet',
    subtitle:w.id+' · '+CUR(w.balance)+' held',
    risk:'high', confirmLabel:'Apply it',
    body:banner('warning','<strong>This moves money on the balance sheet.</strong> It posts to '+
      WALLET_POLICY.liabilityAccount+' and it will be on the audit log with your name against it.')+
      '<div class="grid g3">'+
        '<div class="field"><label for="awDir">Direction</label><select class="inp" id="awDir">'+
          '<option value="1">Credit the wallet</option><option value="-1">Debit the wallet</option>'+
          '</select></div>'+
        '<div class="field"><label for="awAmt">Amount ('+esc(MP.currencyCode)+')</label>'+
          '<input class="inp" id="awAmt" type="number" min="0.01" step="0.5" value="10" data-autofocus></div>'+
        '<div class="field"><label for="awPot">Which pot</label><select class="inp" id="awPot">'+
          '<option value="promo">Credit we issue — not refundable</option>'+
          '<option value="cash">The holder’s money — refundable</option></select>'+
          '<div class="hint">Getting this wrong is how promotional credit ends up refunded as cash.</div>'+
        '</div>'+
      '</div>'+
      '<div class="field"><label for="awWhy">Reason</label>'+
        '<textarea class="inp" id="awWhy" rows="2" placeholder="Goodwill after ORD-881204 arrived '+
        'damaged"></textarea></div>',
    impact:['The balance changes immediately and the holder can spend it.',
            'The liability on '+WALLET_POLICY.liabilityAccount+' moves by the same amount.',
            '<strong>There is no approval step.</strong> That is why the reason is required.'],
    validate:(v)=>{
      const amt=Math.abs(parseFloat((v&&v.awAmt)||'0')||0);
      const dir=parseInt((v&&v.awDir)||'1',10);
      const pot=(v&&v.awPot)||'promo';
      if(!amt) return '<strong>Enter an amount.</strong>';
      if(!((v&&v.awWhy)||'').trim())
        return '<strong>An adjustment without a reason is indistinguishable from a mistake.</strong>';
      if(dir<0 && amt>(pot==='cash'?w.cash:w.promo))
        return '<strong>That is more than the '+(pot==='cash'?'refundable':'issued')+' pot holds.</strong> '+
          'The most that can come out of it is '+CUR(pot==='cash'?w.cash:w.promo)+'.';
      if(dir>0 && (w.balance+amt)>WALLET_POLICY.maxBalance)
        return '<strong>That would take the wallet past the '+CUR(WALLET_POLICY.maxBalance)+
          ' ceiling.</strong> The ceiling exists because a stored-value balance is somebody else’s money '+
          'sitting on our books.';
      return null;
    },
    onConfirm:(v)=>{
      const amt=Math.abs(parseFloat(v.awAmt)||0), dir=parseInt(v.awDir,10), pot=v.awPot;
      const why=String(v.awWhy||'').trim();
      const before=w.balance;
      w[pot]=+(w[pot]+dir*amt).toFixed(2);
      w.balance=+(w.cash+w.promo).toFixed(2);
      w.lastMove=TODAY; w.state='active'; w.note=null;
      WALLET_LEDGER.unshift({id:'WTX-'+(79000+WALLET_LEDGER.length), wallet:w.id, party:w.party,
        name:w.name, when:TODAY, source:dir>0?'goodwill':'spend', what:why,
        amount:dir*amt, pot:pot});
      if(typeof SHOPPER!=='undefined' && w.party===SHOPPER.id) SHOPPER.wallet=w.balance;
      if(typeof audit==='function') audit('wallet.adjusted',{object:w.name,
        before:CUR(before), after:CUR(w.balance), amount:amt, detail:why});
      toast(w.name+'’s wallet '+(dir>0?'credited ':'debited ')+CUR(amt));
      App.go(App.view);
    }});
}
function walletPolicyDialog(){
  openModal('<div class="modal-head">'+ICO('shield',18)+'<div class="grow">'+
      '<h3 class="t-sub">Wallet policy</h3><div class="t-small muted">'+esc(WALLET_POLICY.name)+
      '</div></div>'+
      '<button class="iconbtn" onclick="closeModal()" aria-label="Close">'+ICO('x',16)+'</button></div>'+
    '<div class="modal-body stack">'+
      banner('warning','<strong>The ceiling and the dormancy window are not cosmetic.</strong> A high '+
        'ceiling turns the platform into an unlicensed deposit-taker in some jurisdictions, and a long '+
        'dormancy window means holding money nobody is coming back for.')+
      '<div class="grid g3">'+
        '<div class="field"><label for="wpMax">Maximum balance ('+esc(MP.currencyCode)+')</label>'+
          '<input class="inp" id="wpMax" type="number" min="0" step="50" value="'+
          WALLET_POLICY.maxBalance+'" data-autofocus></div>'+
        '<div class="field"><label for="wpMin">Minimum top-up ('+esc(MP.currencyCode)+')</label>'+
          '<input class="inp" id="wpMin" type="number" min="1" step="1" value="'+
          WALLET_POLICY.minTopUp+'"></div>'+
        '<div class="field"><label for="wpDorm">Dormant after (months)</label>'+
          '<input class="inp" id="wpDorm" type="number" min="6" step="1" value="'+
          WALLET_POLICY.dormancyMonths+'"></div>'+
      '</div>'+
      '<div id="wpOut"></div>'+
    '</div>'+
    '<div class="modal-foot"><button class="btn btn-quiet" onclick="closeModal()">Cancel</button>'+
      '<div class="spacer"></div>'+
      '<button class="btn btn-primary" onclick="saveWalletPolicy()">Save</button></div>',
    {wide:true, label:'Wallet policy'});
}
function saveWalletPolicy(){
  const n=k=>parseFloat((document.getElementById(k)||{}).value||'0')||0;
  const out=document.getElementById('wpOut');
  const max=n('wpMax'), min=n('wpMin'), dorm=n('wpDorm');
  const over=WALLETS.filter(w=>w.balance>max);
  if(min<=0 || max<=0){
    if(out) out.innerHTML=banner('danger','<strong>Both figures have to be above zero.</strong>'); return; }
  if(min>max){
    if(out) out.innerHTML=banner('danger','<strong>The minimum top-up is above the ceiling.</strong> '+
      'Nobody could top up at all.'); return; }
  if(dorm<6){
    if(out) out.innerHTML=banner('danger','<strong>Six months is the floor.</strong> Declaring a balance '+
      'dormant faster than that catches people who are simply between purchases.'); return; }
  if(over.length){
    if(out) out.innerHTML=banner('warning','<strong>'+over.length+' wallet'+(over.length===1?' is':'s are')+
      ' already above '+CUR(max)+'.</strong> Lowering the ceiling does not claw anything back — those '+
      'balances stay and simply cannot be topped up until they fall below it. Save again to confirm.');
    if(out.getAttribute('data-warned')!=='1'){ out.setAttribute('data-warned','1'); return; }
  }
  const before=CUR(WALLET_POLICY.maxBalance)+' ceiling, '+WALLET_POLICY.dormancyMonths+' months';
  WALLET_POLICY.maxBalance=max; WALLET_POLICY.minTopUp=min; WALLET_POLICY.dormancyMonths=dorm;
  if(typeof audit==='function') audit('wallet.policy',{object:WALLET_POLICY.name,
    before:before, after:CUR(max)+' ceiling, '+dorm+' months',
    detail:'Minimum top-up '+CUR(min)});
  closeModal(); toast('Wallet policy saved'); App.go(App.view);
}
registerExport('walletLedger',()=>({
  columns:['Movement','Wallet','Holder','When','Source','What','Pot','Amount'],
  rows:WALLET_LEDGER.map(t=>[t.id,t.wallet,t.name,t.when,walletSourceLabel(t.source),t.what,
    t.pot==='promo'?'Credit we issued':'The holder’s',t.amount])
}));

/* When a shopper can expect it back, where the record actually says so. */
function invEta(sku){
  const r=(typeof inv==='function')? inv(sku) : null;
  if(!r) return null;
  if(r.backorder && r.onOrder) return 'on back order, due '+(r.dueIn||'shortly');
  return null;
}
